def search_companies(workspace_id, query, limit=None, cursor=None, sort=None, order=None, status=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "search-companies"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _jblob(o):
        if isinstance(o, dict):
            return o
        if isinstance(o, list):
            return o
        return None

    def _flatten_text(v, _depth=0):
        # convert nested dict/list into searchable text
        if _depth > 6:
            return ""
        if v is None:
            return ""
        if isinstance(v, (str, int, float, bool)):
            return str(v)
        if isinstance(v, dict):
            parts = []
            for k, vv in v.items():
                parts.append(str(k))
                parts.append(_flatten_text(vv, _depth + 1))
            return " ".join(parts)
        if isinstance(v, list):
            return " ".join(_flatten_text(x, _depth + 1) for x in v)
        return ""

    def _encode_cursor(payload_dict):
        raw = json.dumps(payload_dict, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        sig = hashlib.sha256(raw).hexdigest()[:16]
        blob = json.dumps({"p": payload_dict, "s": sig}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(blob).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return _err("VALIDATION_ERROR", "cursor is malformed")
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            blob = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(blob.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is malformed")
        if not isinstance(obj, dict) or "p" not in obj or "s" not in obj:
            return _err("VALIDATION_ERROR", "cursor is malformed")
        p = obj["p"]
        s = obj["s"]
        if not isinstance(p, dict) or not isinstance(s, str):
            return _err("VALIDATION_ERROR", "cursor is malformed")
        raw = json.dumps(p, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        sig = hashlib.sha256(raw).hexdigest()[:16]
        if sig != s:
            return _err("VALIDATION_ERROR", "cursor is malformed")
        return p

    # request log / quota / rate-limit support if present
    def _log_request(status_code, latency_ms, used_workspace_row_id=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "workspace_id": used_workspace_row_id,
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            })
            _save("request_logs.json", logs)

    def _enforce_limits(used_workspace_row_id=None):
        # Optional: enforce if rate_limits.json exists with a row for this endpoint or global.
        rate_cfg = _load("rate_limits.json")
        if not isinstance(rate_cfg, list) or not rate_cfg:
            return None
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        def _count(window_s, endpoint_match):
            cutoff = now - datetime.timedelta(seconds=window_s)
            c = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if used_workspace_row_id is not None and r.get("workspace_id") != used_workspace_row_id:
                    continue
                ep = r.get("endpoint")
                if endpoint_match is not None and ep != endpoint_match:
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts is None:
                    continue
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts >= cutoff:
                    c += 1
            return c

        for rule in rate_cfg:
            if not isinstance(rule, dict):
                continue
            ep = rule.get("endpoint")
            if ep not in (None, "*", endpoint):
                continue
            window_s = rule.get("window_seconds")
            limit_n = rule.get("limit")
            scope = rule.get("scope", "workspace")
            if not isinstance(window_s, int) or window_s <= 0 or not isinstance(limit_n, int) or limit_n < 0:
                continue
            if scope == "workspace" and used_workspace_row_id is None:
                continue
            current = _count(window_s, None if ep in (None, "*") else endpoint)
            if current >= limit_n:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=limit_n, window_seconds=window_s)
        return None

    # Validate inputs
    if not isinstance(workspace_id, str) or re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id) is None:
        # note: log after resolution attempt isn't possible; log with provided workspace_id
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), None)
        return _err("VALIDATION_ERROR", "workspace_id is not a valid att_ws_ ULID")

    if not isinstance(query, str):
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "query must be a string")
    q = query.strip()
    # allowed empty? description implies free-text; do not error unless explicitly required; treat empty as match-all with low relevance.
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    allowed_sort = {"relevance", "display_name", "created_at", "updated_at", "last_activity_at", "last_interaction_at"}
    allowed_order = {"asc", "desc"}
    allowed_status = {"active", "archived", "deleted"}
    if sort is None:
        sort = "relevance"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "sort must be one of the allowed values")
    if order is None:
        order = "desc" if sort != "display_name" else "asc"
    if not isinstance(order, str) or order not in allowed_order:
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "order must be one of the allowed values")
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in allowed_status:
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "status must be one of the allowed values")

    cur_payload = None
    if cursor is not None:
        dc = _decode_cursor(cursor)
        if isinstance(dc, dict) and "error" in dc:
            _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
            return dc
        cur_payload = dc

    # Resolve workspace: ambient auth; must exist and be usable
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("attio_workspace_id") == workspace_id and w.get("status") == "active":
            ws = w
            break
    if ws is None:
        # try disabled? tool spec says validation errors, but business rules: scoped to workspace with configured connection.
        # For this tool, if upstream id exists but disabled, treat as UNAUTHORIZED (cannot serve).
        for w in workspaces:
            if isinstance(w, dict) and w.get("attio_workspace_id") == workspace_id:
                _log_request("UNAUTHORIZED", int((time.time() - _t0) * 1000), w.get("id"))
                return _err("UNAUTHORIZED", "Workspace is not active or not authorized")
        _log_request("UNAUTHORIZED", int((time.time() - _t0) * 1000), None)
        return _err("UNAUTHORIZED", "No authorized workspace connection found")

    # enforce optional rate limits (if configured)
    rl = _enforce_limits(ws.get("id"))
    if rl is not None:
        _log_request("RATE_LIMIT", int((time.time() - _t0) * 1000), ws.get("id"))
        return rl

    # Cursor payload consistency check
    if cur_payload is not None:
        # Ensure cursor was issued for same workspace/query/sort/order/status
        expected_keys = ["workspace_attio_id", "query", "sort", "order", "status", "offset"]
        if any(k not in cur_payload for k in expected_keys):
            _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), ws.get("id"))
            return _err("VALIDATION_ERROR", "cursor is malformed")
        if cur_payload.get("workspace_attio_id") != workspace_id or cur_payload.get("query") != q or cur_payload.get("sort") != sort or cur_payload.get("order") != order or cur_payload.get("status") != status:
            _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), ws.get("id"))
            return _err("VALIDATION_ERROR", "cursor does not match request parameters")
        offset = cur_payload.get("offset")
        if not isinstance(offset, int) or offset < 0:
            _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), ws.get("id"))
            return _err("VALIDATION_ERROR", "cursor is malformed")
    else:
        offset = 0

    records = _load("records.json")
    if not isinstance(records, list):
        records = []

    q_l = q.lower()
    tokens = [t for t in re.split(r"\s+", q_l) if t] if q_l else []

    # Score + filter
    candidates = []
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != ws.get("id"):
            continue
        if r.get("record_type") != "company":
            continue
        if r.get("status") != status:
            continue

        display = r.get("display_name") or ""
        domain = r.get("domain") or ""
        attrs = _jblob(r.get("attributes")) or {}
        rawj = _jblob(r.get("raw_json")) or {}

        hay = " ".join([
            str(display),
            str(domain),
            _flatten_text(attrs),
            _flatten_text(rawj),
        ]).lower()

        if tokens:
            ok = True
            score = 0
            for t in tokens:
                if t not in hay:
                    ok = False
                    break
                # crude relevance: boost matches in display_name/domain
                if t and t in str(display).lower():
                    score += 5
                if t and t in str(domain).lower():
                    score += 3
                score += 1
            if not ok:
                continue
        else:
            score = 0

        # store sort fields
        def _dt_or_min(val):
            dt = _parse_dt(val) if isinstance(val, str) else None
            if dt is None:
                return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt

        candidates.append({
            "_row": r,
            "_score": score,
            "_display": (display or "").lower(),
            "_created": _dt_or_min(r.get("created_at")),
            "_updated": _dt_or_min(r.get("updated_at")),
            "_last_act": _dt_or_min(r.get("last_activity_at")),
            "_last_int": _dt_or_min(r.get("last_interaction_at")),
        })

    reverse = (order == "desc")
    if sort == "relevance":
        candidates.sort(key=lambda x: (x["_score"], x["_updated"], x["_created"]), reverse=True)
    elif sort == "display_name":
        candidates.sort(key=lambda x: (x["_display"], x["_updated"], x["_created"]), reverse=reverse)
    elif sort == "created_at":
        candidates.sort(key=lambda x: (x["_created"], x["_updated"]), reverse=reverse)
    elif sort == "updated_at":
        candidates.sort(key=lambda x: (x["_updated"], x["_created"]), reverse=reverse)
    elif sort == "last_activity_at":
        candidates.sort(key=lambda x: (x["_last_act"], x["_updated"]), reverse=reverse)
    elif sort == "last_interaction_at":
        candidates.sort(key=lambda x: (x["_last_int"], x["_updated"]), reverse=reverse)

    total = len(candidates)
    page = candidates[offset: offset + limit]
    rows = []
    for x in page:
        r = x["_row"]
        # return projection suited for "matching companies" without fabricating fields
        rows.append({
            "id": r.get("id"),
            "attio_record_id": r.get("attio_record_id"),
            "attio_object": r.get("attio_object"),
            "display_name": r.get("display_name"),
            "domain": r.get("domain"),
            "status": r.get("status"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
            "last_activity_at": r.get("last_activity_at"),
            "last_interaction_at": r.get("last_interaction_at"),
        })

    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({
        "workspace_attio_id": workspace_id,
        "query": q,
        "sort": sort,
        "order": order,
        "status": status,
        "offset": next_offset
    }) if has_more else None

    latency_ms = int((time.time() - _t0) * 1000)
    _log_request("OK", latency_ms, ws.get("id"))
    return {
        "companies": rows,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
            "status": status
        }
    }

def advanced_search_companies(workspace_id, filters, query=None, limit=None, cursor=None, sort=None, order=None, status=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "advanced-search-companies"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _get_log_file():
        for fn in ("request_logs.json", "usage.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(status_s, detail=None, ws_row_id=None):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
        row = {
            "id": rid,
            "endpoint": endpoint,
            "workspace_id": ws_row_id if ws_row_id is not None else workspace_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(wsid):
        # Best-effort: 120 req / 60s / workspace across all endpoints if logs exist.
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        n = 0

        def _parse_ts(v):
            if not isinstance(v, str):
                return None
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None

        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if wsid is not None and r.get("workspace_id") != wsid:
                continue
            dt = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if dt is None:
                continue
            if dt < cutoff:
                break
            n += 1
            if n >= 120:
                return True
        return False

    # ---- validate inputs ----
    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "workspace_id is invalid", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(filters, dict):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "filters must be an object", "field": "filters"}, ws_row_id=workspace_id)
        return _err("VALIDATION_ERROR", "filters must be an object", field="filters")
    if query is not None and not isinstance(query, str):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "query must be a string", "field": "query"}, ws_row_id=workspace_id)
        return _err("VALIDATION_ERROR", "query must be a string", field="query")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "limit must be between 1 and 100", "field": "limit"}, ws_row_id=workspace_id)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    allowed_sort = {"relevance", "display_name", "created_at", "updated_at", "last_activity_at", "last_interaction_at"}
    if sort is None:
        sort = "relevance"
    if sort not in allowed_sort:
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "sort is invalid", "field": "sort"}, ws_row_id=workspace_id)
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    if order is None:
        order = "desc" if sort in ("created_at", "updated_at", "last_activity_at", "last_interaction_at") else "asc"
    if order not in ("asc", "desc"):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "order is invalid", "field": "order"}, ws_row_id=workspace_id)
        return _err("VALIDATION_ERROR", "order is invalid", field="order")

    if status is None:
        status = "active"
    if status not in ("active", "archived", "deleted"):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "status is invalid", "field": "status"}, ws_row_id=workspace_id)
        return _err("VALIDATION_ERROR", "status is invalid", field="status")

    # cursor: DO NOT require base64; accept opaque vendor cursor (including att_ws_... seen in audit)
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log("error", detail={"code": "VALIDATION_ERROR", "message": "cursor is malformed", "field": "cursor"}, ws_row_id=workspace_id)
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        cur = cursor.strip()
        if cur.startswith("off:"):
            try:
                offset = int(cur.split(":", 1)[1])
                if offset < 0:
                    raise ValueError()
            except Exception:
                _log("error", detail={"code": "VALIDATION_ERROR", "message": "cursor is malformed", "field": "cursor"}, ws_row_id=workspace_id)
                return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        else:
            # Accept any opaque cursor; treat as 0 for compatibility.
            offset = 0

    # ---- resolve workspace context (ambient auth): workspace_id is a local workspaces.id ----
    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws_row is None:
        _log("error", detail={"code": "NOT_FOUND", "message": "Workspace not found"}, ws_row_id=workspace_id)
        return _err("NOT_FOUND", "Workspace not found")
    if ws_row.get("status") != "active":
        _log("error", detail={"code": "UNAUTHORIZED", "message": "No active workspace connection available for this request"}, ws_row_id=workspace_id)
        return _err("UNAUTHORIZED", "No active workspace connection available for this request")

    if _rate_limit_check(workspace_id):
        _log("error", detail={"code": "RATE_LIMIT", "message": "Rate limit exceeded"}, ws_row_id=workspace_id)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- filter evaluation ----
    records = _load("records.json")
    if isinstance(records, dict) and "rows" in records:
        records = records.get("rows")
    if not isinstance(records, list):
        records = []

    def _get_nested(obj, path):
        cur = obj
        for p in path:
            if not isinstance(cur, dict) or p not in cur:
                return (False, None)
            cur = cur[p]
        return (True, cur)

    def _parse_filter_obj(fobj):
        # Accept:
        # - {} meaning no structured filters
        # - {"and":[...]} / {"or":[...]} / {"not":{...}}
        # - {"attribute_key":..., "operator":..., "value":...} (condition)
        # - {"field":"display_name"/"domain"/"email"/"phone"/"id"/"attio_record_id"/"attio_object"/"status"/"created_at"/"updated_at"/"last_activity_at"/"last_interaction_at"/"attributes.X.Y", "op":..., "value":...}
        if not isinstance(fobj, dict):
            return ("err", "filters must be an object")
        if not fobj:
            return ("ok", ("true",))
        if "and" in fobj:
            arr = fobj.get("and")
            if not isinstance(arr, list):
                return ("err", "filters.and must be an array")
            parsed = []
            for it in arr:
                st, node = _parse_filter_obj(it)
                if st != "ok":
                    return (st, node)
                parsed.append(node)
            return ("ok", ("and", parsed))
        if "or" in fobj:
            arr = fobj.get("or")
            if not isinstance(arr, list):
                return ("err", "filters.or must be an array")
            parsed = []
            for it in arr:
                st, node = _parse_filter_obj(it)
                if st != "ok":
                    return (st, node)
                parsed.append(node)
            return ("ok", ("or", parsed))
        if "not" in fobj:
            st, node = _parse_filter_obj(fobj.get("not"))
            if st != "ok":
                return (st, node)
            return ("ok", ("not", node))

        # condition form A
        if "attribute_key" in fobj and "operator" in fobj:
            key = fobj.get("attribute_key")
            op = fobj.get("operator")
            val = fobj.get("value", None)
            if not isinstance(key, str) or not key.strip():
                return ("err", "attribute_key must be a non-empty string")
            if op not in ("eq", "neq", "in", "nin", "contains", "exists", "gte", "gt", "lte", "lt"):
                return ("err", "operator is invalid")
            return ("ok", ("cond_attr", key, op, val))

        # condition form B
        if "field" in fobj and ("op" in fobj or "operator" in fobj):
            field = fobj.get("field")
            op = fobj.get("op", fobj.get("operator"))
            val = fobj.get("value", None)
            if not isinstance(field, str) or not field.strip():
                return ("err", "field must be a non-empty string")
            if op not in ("eq", "neq", "in", "nin", "contains", "exists", "gte", "gt", "lte", "lt"):
                return ("err", "operator is invalid")
            return ("ok", ("cond_field", field, op, val))

        # shorthand: {"key": value, ...} means attributes[key] == value
        parsed = []
        for k, v in fobj.items():
            if not isinstance(k, str):
                return ("err", "invalid filters key")
            parsed.append(("cond_attr", k, "eq", v))
        return ("ok", ("and", parsed))

    def _cmp(op, left_exists, left, right):
        if op == "exists":
            return bool(left_exists)
        if not left_exists:
            return False
        if op == "eq":
            return left == right
        if op == "neq":
            return left != right
        if op == "contains":
            if isinstance(left, str) and isinstance(right, str):
                return right.lower() in left.lower()
            if isinstance(left, list):
                return right in left
            if isinstance(left, dict) and isinstance(right, str):
                return right in left
            return False
        if op in ("in", "nin"):
            if not isinstance(right, list):
                return False
            hit = left in right
            return hit if op == "in" else (not hit)
        # ordering
        try:
            if op == "gte":
                return left >= right
            if op == "gt":
                return left > right
            if op == "lte":
                return left <= right
            if op == "lt":
                return left < right
        except TypeError:
            return False
        return False

    st, ast = _parse_filter_obj(filters)
    if st != "ok":
        _log("error", detail={"code": "VALIDATION_ERROR", "message": str(ast)}, ws_row_id=workspace_id)
        return _err("VALIDATION_ERROR", str(ast))

    # validate attribute keys exist in workspace catalog when possible (invalid keys -> VALIDATION_ERROR)
    catalog = ws_row.get("attribute_catalog")
    valid_attr_keys = None
    if isinstance(catalog, dict):
        keys = set()
        def _walk(o, prefix=""):
            if isinstance(o, dict):
                for kk, vv in o.items():
                    if isinstance(kk, str):
                        keys.add((prefix + kk).strip("."))
                        _walk(vv, (prefix + kk + "."))
            elif isinstance(o, list):
                for vv in o:
                    _walk(vv, prefix)
        _walk(catalog, "")
        valid_attr_keys = keys if keys else None

    def _collect_attr_keys(node, out):
        t = node[0]
        if t in ("true",):
            return
        if t in ("and", "or"):
            for c in node[1]:
                _collect_attr_keys(c, out)
        elif t == "not":
            _collect_attr_keys(node[1], out)
        elif t == "cond_attr":
            out.add(node[1])

    if valid_attr_keys is not None:
        used = set()
        _collect_attr_keys(ast, used)
        # allow non-catalog keys if records actually contain them, else error
        rec_has = set()
        for r in records:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id and isinstance(r.get("attributes"), dict):
                for k in r["attributes"].keys():
                    if isinstance(k, str):
                        rec_has.add(k)
        for k in used:
            if k not in valid_attr_keys and k not in rec_has:
                _log("error", detail={"code": "VALIDATION_ERROR", "message": f"Unknown attribute key: {k}", "field": "filters"}, ws_row_id=workspace_id)
                return _err("VALIDATION_ERROR", f"Unknown attribute key: {k}", field="filters")

    def _eval(node, rec):
        t = node[0]
        if t == "true":
            return True
        if t == "and":
            return all(_eval(c, rec) for c in node[1])
        if t == "or":
            return any(_eval(c, rec) for c in node[1])
        if t == "not":
            return not _eval(node[1], rec)
        if t == "cond_attr":
            key, op, val = node[1], node[2], node[3]
            attrs = rec.get("attributes")
            if not isinstance(attrs, dict):
                return False if op != "exists" else False
            exists = key in attrs
            return _cmp(op, exists, attrs.get(key), val)
        if t == "cond_field":
            field, op, val = node[1], node[2], node[3]
            if field.startswith("attributes."):
                path = field.split(".")[1:]
                attrs = rec.get("attributes")
                if not isinstance(attrs, dict):
                    return False if op != "exists" else False
                ex, lv = _get_nested(attrs, path)
                return _cmp(op, ex, lv, val)
            ex = field in rec
            return _cmp(op, ex, rec.get(field), val)
        return False

    q = (query or "").strip().lower()

    def _text_blob(rec):
        parts = []
        for k in ("display_name", "domain", "email", "phone", "attio_object", "attio_record_id"):
            v = rec.get(k)
            if isinstance(v, str) and v:
                parts.append(v)
        attrs = rec.get("attributes")
        if isinstance(attrs, dict):
            for vv in attrs.values():
                if isinstance(vv, str):
                    parts.append(vv)
        raw = rec.get("raw_json")
        if isinstance(raw, dict):
            # small subset for FT: stringify scalars only
            for vv in raw.values():
                if isinstance(vv, str):
                    parts.append(vv)
        return " ".join(parts).lower()

    matches = []
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("record_type") != "company":
            continue
        if r.get("status") != status:
            continue
        if not _eval(ast, r):
            continue
        if q:
            blob = _text_blob(r)
            if q not in blob:
                continue
        matches.append(r)

    # ---- sorting ----
    def _dt_key(v):
        if not isinstance(v, str) or not v:
            return None
        s = v
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    if sort == "relevance":
        if q:
            def _score(rec):
                blob = _text_blob(rec)
                # simplistic: occurrences + display_name boost
                occ = blob.count(q)
                dn = rec.get("display_name") or ""
                boost = 2 if isinstance(dn, str) and q in dn.lower() else 0
                return occ + boost
            matches.sort(key=lambda r: (_score(r), (r.get("display_name") or "").lower()), reverse=(order == "desc"))
        else:
            matches.sort(key=lambda r: ((r.get("display_name") or "").lower(), r.get("id") or ""), reverse=(order == "desc"))
    elif sort == "display_name":
        matches.sort(key=lambda r: ((r.get("display_name") or "").lower(), r.get("id") or ""), reverse=(order == "desc"))
    elif sort in ("created_at", "updated_at", "last_activity_at", "last_interaction_at"):
        matches.sort(key=lambda r: (_dt_key(r.get(sort)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or ""), reverse=(order == "desc"))

    total = len(matches)
    page = matches[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = ("off:%d" % next_offset) if has_more else None

    resp = {
        "companies": page,
        "meta": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
    }
    _log("ok", ws_row_id=workspace_id)
    return resp

def search_companies_by_domain(workspace_id, domain, limit=None, cursor=None, status=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _get_request_log_filename():
        for fn in ("request_logs.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log_request(endpoint, ws_row, status_code, latency_ms, detail=None):
        fn = _get_request_log_filename()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now() + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "workspace_id": (ws_row or {}).get("id"),
            "attio_workspace_id": (ws_row or {}).get("attio_workspace_id"),
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save(fn, logs)

    def _enforce_rate_limit(ws_row, endpoint):
        fn = _get_request_log_filename()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        wsid = ws_row["id"]
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("workspace_id") != wsid:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120)
        if per_day >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=50000)
        return None

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8", "strict")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(offset):
        payload = {"v": 1, "offset": int(offset)}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _normalize_domain(inp):
        if not isinstance(inp, str):
            return None
        s = inp.strip()
        if not s:
            return None
        # if it's a bare domain, urlparse treats it as path; add scheme
        if "://" not in s:
            s2 = "http://" + s
        else:
            s2 = s
        try:
            u = urllib.parse.urlparse(s2)
        except Exception:
            return None
        host = u.hostname
        if not host:
            return None
        host = host.lower().strip(".")
        if host.startswith("www."):
            host = host[4:]
        if not re.match(r"^[a-z0-9.-]+$", host):
            return None
        if "." not in host:
            return None
        return host

    t0 = time.time()
    endpoint = "search-companies-by-domain"

    if not isinstance(workspace_id, str) or not re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
        _log_request(endpoint, None, 400, (time.time() - t0) * 1000, detail={"error": "invalid_workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid")
    norm = _normalize_domain(domain)
    if norm is None:
        _log_request(endpoint, None, 400, (time.time() - t0) * 1000, detail={"error": "invalid_domain"})
        return _err("VALIDATION_ERROR", "domain is invalid")
    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_request(endpoint, None, 400, (time.time() - t0) * 1000, detail={"error": "invalid_limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
    if status is None:
        status = "active"
    if status not in ("active", "archived", "deleted"):
        _log_request(endpoint, None, 400, (time.time() - t0) * 1000, detail={"error": "invalid_status"})
        return _err("VALIDATION_ERROR", "status is invalid")
    offset = _decode_cursor(cursor)
    if offset is None:
        _log_request(endpoint, None, 400, (time.time() - t0) * 1000, detail={"error": "malformed_cursor"})
        return _err("VALIDATION_ERROR", "cursor is malformed")

    workspaces = _load("workspaces.json")
    ws_row = None
    if isinstance(workspaces, list):
        for w in workspaces:
            if isinstance(w, dict) and w.get("attio_workspace_id") == workspace_id and w.get("status") == "active":
                ws_row = w
                break
    if ws_row is None:
        found = False
        if isinstance(workspaces, list):
            for w in workspaces:
                if isinstance(w, dict) and w.get("attio_workspace_id") == workspace_id:
                    found = True
                    break
        _log_request(endpoint, None, 403 if found else 404, (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Workspace is not accessible") if found else _err("NOT_FOUND", "Workspace not found")

    rl = _enforce_rate_limit(ws_row, endpoint)
    if rl:
        _log_request(endpoint, ws_row, 429, (time.time() - t0) * 1000, detail=rl)
        return rl

    records = _load("records.json")
    if not isinstance(records, list):
        records = []

    matches = []
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != ws_row.get("id"):
            continue
        if r.get("record_type") != "company":
            continue
        if r.get("status") != status:
            continue
        if (r.get("domain") or "").lower() == norm:
            matches.append(r)

    total = len(matches)
    # deterministic ordering: updated_at desc then id
    def _key(r):
        dt = _parse_dt(r.get("updated_at")) or datetime.datetime.min
        return (dt, r.get("id") or "")
    matches.sort(key=_key, reverse=True)

    page = matches[offset: offset + limit]
    data = [{
        "id": r.get("id"),
        "attio_record_id": r.get("attio_record_id"),
        "attio_object": r.get("attio_object"),
        "display_name": r.get("display_name"),
        "domain": r.get("domain"),
        "status": r.get("status"),
        "created_at": r.get("created_at"),
        "updated_at": r.get("updated_at"),
    } for r in page]

    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    body = {
        "data": data,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "status": status,
            "normalized_domain": norm,
        },
    }
    _log_request(endpoint, ws_row, 200, (time.time() - t0) * 1000, detail={"returned": len(data)})
    return body

