        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_request(endpoint, None, 400, (time.time() - t0) * 1000, detail={"error": "invalid_limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
    if status is None:
        status = "active"
    if status not in ("active", "archived", "deleted"):
        _log_request(endpoint, None, 400, (time.time() - t0) * 1000, detail={"error": "invalid_status"})
        return _err("VALIDATION_ERROR", "status is invalid")

    workspaces = _load("workspaces.json")
    ws_row = None
    if isinstance(workspaces, list):
        for w in workspaces:
            if isinstance(w, dict) and w.get("attio_workspace_id") == workspace_id and w.get("status") == "active":
                ws_row = w
                break
    if ws_row is None:
        found = False
        if isinstance(workspaces, list):
            for w in workspaces:
                if isinstance(w, dict) and w.get("attio_workspace_id") == workspace_id:
                    found = True
                    break
        _log_request(endpoint, None, 403 if found else 404, (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Workspace is not accessible") if found else _err("NOT_FOUND", "Workspace not found")

    rl = _enforce_rate_limit(ws_row, endpoint)
    if rl:
        _log_request(endpoint, ws_row, 429, (time.time() - t0) * 1000, detail=rl)
        return rl

    records = _load("records.json")
    if not isinstance(records, list):
        records = []

    q = query.strip()
    qsig = hashlib.sha256((q.lower() + "|" + status).encode("utf-8")).hexdigest()[:16]

    # Cursor validation (cursor binds to query/signature + mode)
    cur_obj = None
    if cursor is not None:
        cur_obj = _decode_cursor(cursor)
        if cur_obj is None:
            _log_request(endpoint, ws_row, 400, (time.time() - t0) * 1000, detail={"error": "malformed_cursor"})
            return _err("VALIDATION_ERROR", "cursor is malformed")
        if cur_obj.get("qsig") != qsig:
            _log_request(endpoint, ws_row, 400, (time.time() - t0) * 1000, detail={"error": "cursor_query_mismatch"})
            return _err("VALIDATION_ERROR", "cursor does not match the current query")
        offset = cur_obj["offset"]
        mode = cur_obj["mode"]
    else:
        offset = 0
        # infer mode
        mode = "domain" if _extract_domain_from_query(q) else "text"

    results = []

    if mode == "domain":
        dom = _extract_domain_from_query(q)
        if dom is None:
            # fall back to text search if inference fails
            mode = "text"
        else:
            matches = []
            for r in records:
                if not isinstance(r, dict):
                    continue
                if r.get("workspace_id") != ws_row.get("id"):
                    continue
                if r.get("record_type") != "company":
                    continue
                if r.get("status") != status:
                    continue
                if (r.get("domain") or "").lower() == dom:
                    matches.append(r)
            total = len(matches)
            # best matches: exact domain first (all are), then updated_at desc
            def _key(r):
                dt = _parse_dt(r.get("updated_at")) or datetime.datetime.min
                return (dt, r.get("id") or "")
            matches.sort(key=_key, reverse=True)
            page = matches[offset: offset + limit]
            for r in page:
                results.append({
                    "id": r.get("id"),
                    "attio_record_id": r.get("attio_record_id"),
                    "attio_object": r.get("attio_object"),
                    "display_name": r.get("display_name"),
                    "domain": r.get("domain"),
                    "status": r.get("status"),
                    "created_at": r.get("created_at"),
                    "updated_at": r.get("updated_at"),
                    "match": {"type": "domain", "value": dom},
                })
            next_offset = offset + len(page)
            has_more = next_offset < total
            next_cursor = _encode_cursor(next_offset, "domain", qsig) if has_more else None
            body = {
                "data": results,
                "meta": {
                    "mode": "domain",
                    "normalized_domain": dom,
                    "total": total,
                    "limit": limit,
                    "cursor": cursor,
                    "next_cursor": next_cursor,
                    "has_more": has_more,
                    "status": status,
                },
            }
            _log_request(endpoint, ws_row, 200, (time.time() - t0) * 1000, detail={"returned": len(results), "mode": "domain"})
            return body

    # Text mode
    toks = _tokenize(q)
    candidates = []
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != ws_row.get("id"):
            continue
        if r.get("record_type") != "company":
            continue
        if r.get("status") != status:
            continue
        text = _collect_text_fields(r)
        ok = True
        for t in toks:
            if t not in text:
                ok = False
                break
        if not ok:
            continue
        score = 0
        dn = (r.get("display_name") or "")
        if isinstance(dn, str) and dn:
            dn_l = dn.lower()
            for t in toks:
                if t in dn_l:
                    score += 10
            if q.lower() in dn_l:
                score += 5
        dom = (r.get("domain") or "")
        if isinstance(dom, str) and dom:
            dom_l = dom.lower()
            for t in toks:
                if t in dom_l:
                    score += 8
        candidates.append((score, r))

    total = len(candidates)
    candidates.sort(key=lambda x: (x[0], (_parse_dt(x[1].get("updated_at")) or datetime.datetime.min)), reverse=True)

    page = candidates[offset: offset + limit]
    for score, r in page:
        results.append({
            "id": r.get("id"),
            "attio_record_id": r.get("attio_record_id"),
            "attio_object": r.get("attio_object"),
            "display_name": r.get("display_name"),
            "domain": r.get("domain"),
            "status": r.get("status"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
            "match": {"type": "text", "score": score},
        })

    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset, "text", qsig) if has_more else None

    body = {
        "data": results,
        "meta": {
            "mode": "text",
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "status": status,
        },
    }
    _log_request(endpoint, ws_row, 200, (time.time() - t0) * 1000, detail={"returned": len(results), "mode": "text"})
    return body

def create_company(workspace_id, display_name, domain=None, phone=None, social=None, business=None, attributes=None, raw_json=None, **_extra):
    import json, os, datetime, re, time
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-company"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _get_log_file():
        for fn in ("request_logs.json", "usage.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(status_s, detail=None):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_%d_%d" % (int(time.time() * 1000), len(logs) + 1),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail,
        })
        _save(fn, logs)

    def _rate_limit_check(wsid):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        n = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != wsid:
                continue
            ts = r.get("timestamp") or r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                s = ts
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if dt < cutoff:
                break
            n += 1
            if n >= 60:
                return True
        return False

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "workspace_id is invalid", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")

    if not isinstance(display_name, str) or not display_name.strip():
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "display_name is required", "field": "display_name"})
        return _err("VALIDATION_ERROR", "display_name is required", field="display_name")

    def _normalize_domain(d):
        if d is None:
            return None
        if not isinstance(d, str):
            return _err("VALIDATION_ERROR", "domain must be a string", field="domain")
        s = d.strip().lower()
        if not s:
            return None
        host = None
        if "://" in s:
            p = urlparse(s)
            host = p.hostname
        if not host:
            host = s.split("/")[0].split("?")[0].split("#")[0]
            host = host.split("@")[-1]
            host = host.split(":")[0]
        host = (host or "").strip().lower()
        if host.startswith("www."):
            host = host[4:]
        if not host or any(c.isspace() for c in host) or "/" in host:
            return _err("VALIDATION_ERROR", "domain must be a normalized host (no scheme/path)", field="domain")
        return host

    nd = _normalize_domain(domain)
    if isinstance(nd, dict) and "error" in nd:
        _log("error", detail=nd["error"])
        return nd

    if phone is not None and not isinstance(phone, str):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "phone must be a string", "field": "phone"})
        return _err("VALIDATION_ERROR", "phone must be a string", field="phone")

    for obj_field, val in (("social", social), ("business", business), ("attributes", attributes), ("raw_json", raw_json)):
        if val is not None and not isinstance(val, dict):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"{obj_field} must be an object", "field": obj_field})
            return _err("VALIDATION_ERROR", f"{obj_field} must be an object", field=obj_field)

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws_row is None:
        _log("error", detail={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")
    if ws_row.get("status") != "active":
        _log("error", detail={"code": "UNAUTHORIZED", "message": "No active workspace connection available for this request"})
        return _err("UNAUTHORIZED", "No active workspace connection available for this request")

    if _rate_limit_check(workspace_id):
        _log("error", detail={"code": "RATE_LIMIT", "message": "Rate limit exceeded"})
        return _err("RATE_LIMIT", "Rate limit exceeded")

    records = _load("records.json")
    if isinstance(records, dict) and "rows" in records:
        records = records.get("rows")
    if not isinstance(records, list):
        records = []

    # enforce unique(workspace_id, attio_object, attio_record_id) only if those are set; for create-company, we generate attio_record_id locally
    # also enforce company domain normalization constraint if present.
    now = _now_iso()

    def _gen_id(prefix):
        # ULID-like 26 Crockford chars
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        v = ms
        ts_chars = []
        for _ in range(10):
            v, r = divmod(v, 32)
            ts_chars.append(alphabet[r])
        ts_chars = "".join(reversed(ts_chars))
        rand = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{ts_chars}{rand}"

    new_id = _gen_id("att_rec")
    while any(isinstance(r, dict) and r.get("id") == new_id for r in records):
        new_id = _gen_id("att_rec")

    attio_object = "companies"
    attio_record_id = _gen_id("attio")  # opaque upstream-ish id, must be unique within workspace+object
    # ensure uniqueness
    existing = {(r.get("workspace_id"), r.get("attio_object"), r.get("attio_record_id")) for r in records if isinstance(r, dict)}
    while (workspace_id, attio_object, attio_record_id) in existing:
        attio_record_id = _gen_id("attio")

    rec = {
        "id": new_id,
        "workspace_id": workspace_id,
        "record_type": "company",
        "attio_object": attio_object,
        "attio_record_id": attio_record_id,
        "status": "active",
        "display_name": display_name.strip(),
        "domain": nd,
        "email": None,
        "phone": phone.strip() if isinstance(phone, str) and phone.strip() else None,
        "social": social if isinstance(social, dict) else None,
        "contact": None,
        "business": business if isinstance(business, dict) else None,
        "attributes": attributes if isinstance(attributes, dict) else {},
        "raw_json": raw_json if isinstance(raw_json, dict) else {},
        "last_interaction_at": None,
        "last_activity_at": None,
        "attio_created_at": None,
        "attio_updated_at": None,
        "created_at": now,
        "updated_at": now,
    }

    records.append(rec)
    _save("records.json", records)
    _log("ok")
    return {"company": rec}

def update_company(workspace_id, record_id, display_name=None, domain=None, phone=None, social=None, business=None, attributes=None, status=None, raw_json=None, **_extra):
    import json, os, datetime, re, time, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, message=None, workspace_row_id=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_s,
            "message": message,
            "workspace_id": workspace_row_id,
            "credential_id": None,
            "timestamp": _now(),
            "latency_ms": latency_ms
        }
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_attio_ws_id(s):
        return isinstance(s, str) and re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", s) is not None

    def _is_attio_rec_id(s):
        return isinstance(s, str) and re.match(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$", s) is not None

    def _normalize_domain(d):
        if d is None:
            return None
        if not isinstance(d, str):
            return None
        s = d.strip()
        if not s:
            return None
        if "://" not in s:
            s2 = "http://" + s
        else:
            s2 = s
        try:
            u = urllib.parse.urlparse(s2)
            host = (u.hostname or "").strip().lower()
        except Exception:
            host = ""
        if not host:
            host = s.split("/")[0].split("?")[0].split("#")[0].strip().lower()
        if host.startswith("www."):
            host = host[4:]
        if not host or any(c.isspace() for c in host) or "." not in host:
            return None
        return host

    def _normalize_phone(p):
        if p is None:
            return None
        if not isinstance(p, str):
            return None
        s = p.strip()
        if not s:
            return None
        if s.startswith("+"):
            digits = "+" + "".join(ch for ch in s[1:] if ch.isdigit())
            if 8 <= len(digits) <= 20:
                return digits
        digits_only = "".join(ch for ch in s if ch.isdigit())
        if 7 <= len(digits_only) <= 16:
            return digits_only
        return s

    # Validate inputs
    if not _is_attio_ws_id(workspace_id):
        _log("update-company", "error", "Invalid workspace_id format", None)
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")

    if not _is_attio_rec_id(record_id):
        _log("update-company", "error", "Invalid record_id format", None)
        return _err("VALIDATION_ERROR", "record_id is invalid", field="record_id")

    if display_name is not None and (not isinstance(display_name, str) or not display_name.strip()):
        _log("update-company", "error", "Invalid display_name", None)
        return _err("VALIDATION_ERROR", "display_name must be a non-empty string", field="display_name")

    if domain is not None and not isinstance(domain, str):
        _log("update-company", "error", "Invalid domain type", None)
        return _err("VALIDATION_ERROR", "domain must be a string", field="domain")

    if phone is not None and not isinstance(phone, str):
        _log("update-company", "error", "Invalid phone type", None)
        return _err("VALIDATION_ERROR", "phone must be a string", field="phone")

    if social is not None and not isinstance(social, dict):
        _log("update-company", "error", "Invalid social type", None)
        return _err("VALIDATION_ERROR", "social must be an object", field="social")

    if business is not None and not isinstance(business, dict):
        _log("update-company", "error", "Invalid business type", None)
        return _err("VALIDATION_ERROR", "business must be an object", field="business")

    if attributes is not None and not isinstance(attributes, dict):
        _log("update-company", "error", "Invalid attributes type", None)
        return _err("VALIDATION_ERROR", "attributes must be an object", field="attributes")

    if raw_json is not None and not isinstance(raw_json, dict):
        _log("update-company", "error", "Invalid raw_json type", None)
        return _err("VALIDATION_ERROR", "raw_json must be an object", field="raw_json")

    if status is not None and status not in ("active", "archived", "deleted"):
        _log("update-company", "error", "Invalid status", None)
        return _err("VALIDATION_ERROR", "status is invalid", field="status")

    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces if isinstance(workspaces, list) else []:
        if w.get("attio_workspace_id") == workspace_id:
            ws = w
            break
    if ws is None:
        _log("update-company", "error", "Workspace not found", None)
        return _err("NOT_FOUND", "workspace not found", field="workspace_id")
    if ws.get("status") != "active":
        _log("update-company", "error", "Workspace not active", ws.get("id"))
        return _err("UNAUTHORIZED", "workspace is not active")

    records = _load("records.json")
    if not isinstance(records, list):
        records = []

    idx = None
    rec = None
    for i, r in enumerate(records):
        if r.get("id") == record_id and r.get("workspace_id") == ws.get("id"):
            rec = r
            idx = i
            break
    if rec is None or rec.get("record_type") != "company":
        _log("update-company", "error", "Company record not found", ws.get("id"))
        return _err("NOT_FOUND", "company record not found", field="record_id")

    # lifecycle transition check
    if status is not None and status != rec.get("status"):
        transitions = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
        cur = rec.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _log("update-company", "error", "Invalid status transition", ws.get("id"))
            return _err("INVALID_TRANSITION", "illegal status transition", from_status=cur, to_status=status)

    # Apply updates
    changed = False
    if display_name is not None:
        rec["display_name"] = display_name.strip()
        changed = True

    if domain is not None:
        norm_domain = _normalize_domain(domain)
        if norm_domain is None:
            _log("update-company", "error", "Domain normalization failed", ws.get("id"))
            return _err("VALIDATION_ERROR", "domain must be a normalized host (no scheme/path)", field="domain")
        rec["domain"] = norm_domain
        changed = True

    if phone is not None:
        rec["phone"] = _normalize_phone(phone)
        changed = True

    if social is not None:
        rec["social"] = social
        changed = True

    if business is not None:
        rec["business"] = business
        changed = True

    if raw_json is not None:
        rec["raw_json"] = raw_json
        changed = True

    if attributes is not None:
        # merge/overwrite server-side
        if not isinstance(rec.get("attributes"), dict):
            rec["attributes"] = {}
        for k, v in attributes.items():
            rec["attributes"][k] = v
        changed = True

    if status is not None:
        rec["status"] = status
        changed = True

    if not changed:
        # No success without effect: if record exists but nothing to change, treat as conflict-ish validation
        _log("update-company", "error", "No fields to update", ws.get("id"))
        return _err("VALIDATION_ERROR", "no updatable fields provided")

    rec["updated_at"] = _now()
    records[idx] = rec
    _save("records.json", records)

    ws["updated_at"] = rec["updated_at"]
    for i, w in enumerate(workspaces if isinstance(workspaces, list) else []):
        if w.get("id") == ws.get("id"):
            workspaces[i] = ws
            break
    _save("workspaces.json", workspaces)

    _log("update-company", "success", None, ws.get("id"))
    return {"company": rec}

