            "endpoint": endpoint,
            "status": status_s,
            "message": message,
            "workspace_id": workspace_row_id,
            "credential_id": None,
            "timestamp": _now(),
            "latency_ms": latency_ms
        }
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_attio_ws_id(s):
        return isinstance(s, str) and re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", s) is not None

    def _is_attio_rec_id(s):
        return isinstance(s, str) and re.match(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$", s) is not None

    if not _is_attio_ws_id(workspace_id):
        _log("update-company-attribute", "error", "Invalid workspace_id format", None)
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")

    if not _is_attio_rec_id(record_id):
        _log("update-company-attribute", "error", "Invalid record_id format", None)
        return _err("VALIDATION_ERROR", "record_id is invalid", field="record_id")

    if not isinstance(attribute_name, str) or not attribute_name.strip():
        _log("update-company-attribute", "error", "Invalid attribute_name", None)
        return _err("VALIDATION_ERROR", "attribute_name is required", field="attribute_name")
    attribute_name = attribute_name.strip()

    if mode not in ("set", "unset"):
        _log("update-company-attribute", "error", "Invalid mode", None)
        return _err("VALIDATION_ERROR", "mode must be 'set' or 'unset'", field="mode")

    if mode == "set" and "attribute_value" not in locals():
        _log("update-company-attribute", "error", "Missing attribute_value", None)
        return _err("VALIDATION_ERROR", "attribute_value is required when mode=set", field="attribute_value")
    if mode == "set" and attribute_value is None:
        # allow explicit null set? treat as allowed JSON null
        pass

    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces if isinstance(workspaces, list) else []:
        if w.get("attio_workspace_id") == workspace_id:
            ws = w
            break
    if ws is None:
        _log("update-company-attribute", "error", "Workspace not found", None)
        return _err("NOT_FOUND", "workspace not found", field="workspace_id")
    if ws.get("status") != "active":
        _log("update-company-attribute", "error", "Workspace not active", ws.get("id"))
        return _err("UNAUTHORIZED", "workspace is not active")

    records = _load("records.json")
    if not isinstance(records, list):
        records = []

    idx = None
    rec = None
    for i, r in enumerate(records):
        if r.get("id") == record_id and r.get("workspace_id") == ws.get("id"):
            rec = r
            idx = i
            break
    if rec is None or rec.get("record_type") != "company":
        _log("update-company-attribute", "error", "Company record not found", ws.get("id"))
        return _err("NOT_FOUND", "company record not found", field="record_id")

    if not isinstance(rec.get("attributes"), dict):
        rec["attributes"] = {}

    before = json.dumps(rec["attributes"], sort_keys=True, ensure_ascii=False)
    if mode == "set":
        rec["attributes"][attribute_name] = attribute_value
    else:
        rec["attributes"].pop(attribute_name, None)
    after = json.dumps(rec["attributes"], sort_keys=True, ensure_ascii=False)

    if before == after:
        _log("update-company-attribute", "error", "No effect", ws.get("id"))
        return _err("VALIDATION_ERROR", "attribute update had no effect")

    rec["updated_at"] = _now()
    records[idx] = rec
    _save("records.json", records)

    ws["updated_at"] = rec["updated_at"]
    for i, w in enumerate(workspaces if isinstance(workspaces, list) else []):
        if w.get("id") == ws.get("id"):
            workspaces[i] = ws
            break
    _save("workspaces.json", workspaces)

    _log("update-company-attribute", "success", None, ws.get("id"))
    return {"company": rec}

def delete_company(workspace_id, record_id, hard_delete=None, **_extra):
    import json, os, datetime, re, time, random, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-company"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_req_id():
        raw = (endpoint + "|" + _now_iso() + "|" + str(time.time()) + "|" + str(random.getrandbits(64))).encode("utf-8")
        return "req_" + hashlib.sha256(raw).hexdigest()[:24]

    def _get_log_file():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _append_log(status, detail=None, workspace_id_for_log=None):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_req_id(),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "workspace_id": workspace_id_for_log,
            "detail": detail,
        }
        logs.append(row)
        _save(fn, logs)

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    rec_re = re.compile(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _append_log("error", {"code": "VALIDATION_ERROR", "message": "workspace_id is invalid", "field": "workspace_id"}, None)
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(record_id, str) or not rec_re.fullmatch(record_id):
        _append_log("error", {"code": "VALIDATION_ERROR", "message": "record_id is invalid", "field": "record_id"}, workspace_id)
        return _err("VALIDATION_ERROR", "record_id is invalid", field="record_id")
    if hard_delete is not None and not isinstance(hard_delete, bool):
        _append_log("error", {"code": "VALIDATION_ERROR", "message": "hard_delete must be boolean", "field": "hard_delete"}, workspace_id)
        return _err("VALIDATION_ERROR", "hard_delete must be boolean", field="hard_delete")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _append_log("error", {"code": "NOT_FOUND", "message": "Workspace not found"}, workspace_id)
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _append_log("error", {"code": "UNAUTHORIZED", "message": "Workspace is not active", "status": ws.get("status")}, workspace_id)
        return _err("UNAUTHORIZED", "Workspace is not active", status=ws.get("status"))

    records = _load("records.json")
    if not isinstance(records, list):
        records = []
    idx = None
    rec = None
    for i, r in enumerate(records):
        if isinstance(r, dict) and r.get("id") == record_id:
            idx = i
            rec = r
            break
    if rec is None or rec.get("workspace_id") != workspace_id:
        _append_log("error", {"code": "NOT_FOUND", "message": "Company record not found"}, workspace_id)
        return _err("NOT_FOUND", "Company record not found", record_id=record_id)

    if rec.get("record_type") != "company":
        _append_log("error", {"code": "CONFLICT", "message": "Record is not a company", "record_type": rec.get("record_type")}, workspace_id)
        return _err("CONFLICT", "Record is not a company", record_type=rec.get("record_type"))

    # Refuse if already deleted (per delete-record semantics; apply here too)
    if rec.get("status") == "deleted":
        _append_log("error", {"code": "CONFLICT", "message": "Record is already deleted"}, workspace_id)
        return _err("CONFLICT", "Record is already deleted", record_id=record_id)

    now = _now_iso()

    # Remove list entries (soft remove) regardless of soft/hard delete, to preserve constraints
    list_entries = _load("list_entries.json")
    if not isinstance(list_entries, list):
        list_entries = []
    changed_entries = 0
    for e in list_entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id:
            continue
        if e.get("record_id") != record_id:
            continue
        if e.get("status") == "active":
            e["status"] = "removed"
            e["removed_at"] = now
            e["updated_at"] = now
            changed_entries += 1

    if hard_delete:
        # Hard delete: physically remove the record row
        del records[idx]
        _save("records.json", records)
        if changed_entries:
            _save("list_entries.json", list_entries)
        resp = {"deleted": True, "hard_delete": True, "record_id": record_id, "workspace_id": workspace_id, "removed_list_entries": changed_entries}
        _append_log("ok", {"deleted": True, "hard_delete": True, "removed_list_entries": changed_entries}, workspace_id)
        return resp

    # Soft delete: lifecycle transition active/archived -> deleted
    cur = rec.get("status")
    if cur not in ("active", "archived"):
        _append_log("error", {"code": "INVALID_TRANSITION", "message": "illegal status transition", "from_status": cur, "to_status": "deleted"}, workspace_id)
        return _err("INVALID_TRANSITION", "illegal status transition", from_status=cur, to_status="deleted")
    rec["status"] = "deleted"
    rec["updated_at"] = now
    records[idx] = rec
    _save("records.json", records)
    if changed_entries:
        _save("list_entries.json", list_entries)

    _append_log("ok", {"deleted": True, "hard_delete": False, "removed_list_entries": changed_entries}, workspace_id)
    return {"record": rec, "meta": {"deleted": True, "hard_delete": False, "removed_list_entries": changed_entries, "latency_ms": int((time.time() - t0) * 1000)}}

