    if isinstance(records, dict) and "rows" in records:
        records = records.get("rows")
    if not isinstance(records, list):
        records = []
    company = next((r for r in records if isinstance(r, dict)
                    and r.get("id") == company_record_id
                    and r.get("workspace_id") == workspace_id
                    and r.get("record_type") == "company"), None)
    if not company:
        _append_request_log("NOT_FOUND", {"company_record_id": company_record_id})
        return _err("NOT_FOUND", "Company record not found", company_record_id=company_record_id)

    catalog = ws.get("attribute_catalog")
    if not isinstance(catalog, dict):
        # constraint says it must be an object, but be resilient
        catalog = {}

    # Try to locate "custom" flags in a few common shapes. Fallback: empty.
    custom_defs = []
    for container_key in ("companies", "company", "objects", "attributes", "fields", "schema"):
        v = catalog.get(container_key)
        if isinstance(v, list):
            custom_defs = v
            break
        if isinstance(v, dict):
            # pick nested list if present
            for lk in ("attributes", "fields", "properties"):
                if isinstance(v.get(lk), list):
                    custom_defs = v.get(lk)
                    break
            if custom_defs:
                break

    def _is_custom(defn):
        if not isinstance(defn, dict):
            return False
        for k in ("custom", "is_custom", "isCustom"):
            if defn.get(k) is True:
                return True
        if isinstance(defn.get("source"), str) and defn.get("source").lower() == "custom":
            return True
        return False

    custom_keys = []
    for d in custom_defs:
        if not _is_custom(d):
            continue
        key = d.get("key") or d.get("name") or d.get("slug") or d.get("id")
        if isinstance(key, str) and key.strip():
            custom_keys.append(key)

    attrs = company.get("attributes")
    if not isinstance(attrs, dict):
        attrs = {}

    # Return map of custom_key -> value for those keys present; include null for custom fields not present
    out = {k: attrs.get(k, None) for k in custom_keys}

    _append_request_log("OK", {"custom_field_count": len(out)})
    return {"data": out}

def discover_company_attributes(workspace_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "discover-company-attributes"
    status = "success"

    try:
        if not isinstance(workspace_id, str):
            status = "error"
            return _err("VALIDATION_ERROR", "workspace_id must be a string")
        if not re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
            status = "error"
            return _err("VALIDATION_ERROR", "workspace_id is not a valid ULID", field="workspace_id")

        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws:
            status = "error"
            return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
        if ws.get("status") != "active":
            status = "error"
            return _err("UNAUTHORIZED", "Workspace is not accessible", workspace_id=workspace_id, workspace_status=ws.get("status"))

        catalog = ws.get("attribute_catalog")
        if not isinstance(catalog, dict):
            status = "error"
            return _err("VALIDATION_ERROR", "Workspace attribute_catalog is invalid", workspace_id=workspace_id)

        # Filter to company-relevant attributes. Support multiple catalog shapes.
        company_catalog = None
        if isinstance(catalog.get("company"), dict):
            company_catalog = catalog.get("company")
        elif isinstance(catalog.get("companies"), dict):
            company_catalog = catalog.get("companies")
        else:
            # fallback: if catalog is already scoped to company, return as-is
            company_catalog = catalog

        # Standardize output: {attributes: <dict|list>, last_schema_sync_at: ...}
        attrs = None
        if isinstance(company_catalog, dict):
            if isinstance(company_catalog.get("attributes"), (list, dict)):
                attrs = company_catalog.get("attributes")
            elif isinstance(company_catalog.get("fields"), (list, dict)):
                attrs = company_catalog.get("fields")
            elif isinstance(company_catalog.get("schema"), (list, dict)):
                attrs = company_catalog.get("schema")
        if attrs is None:
            # fallback: attempt to use top-level attributes if present
            if isinstance(catalog.get("attributes"), (list, dict)):
                attrs = catalog.get("attributes")
            else:
                # nothing to return but still success
                attrs = {} if isinstance(company_catalog, dict) else {}

        return {
            "data": {
                "workspace_id": workspace_id,
                "company_attributes": attrs,
                "last_schema_sync_at": ws.get("last_schema_sync_at")
            },
            "meta": {
                "workspace_status": ws.get("status"),
            }
        }
    finally:
        try:
            logs = _load("request_logs.json")
            now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            latency_ms = int((time.time() - t0) * 1000)
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
                "status": status,
                "latency_ms": latency_ms,
                "created_at": now
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

