def get_company_notes(workspace_id, company_record_id, limit=None, cursor=None, sort=None, order=None, status=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- validation ----
    ws_pat = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    rec_pat = re.compile(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(workspace_id, str) or not ws_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(company_record_id, str) or not rec_pat.match(company_record_id):
        return _err("VALIDATION_ERROR", "Invalid company_record_id.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at"):
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order.")
    if status is not None and status not in ("active", "completed", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status.")

    # ---- load data ----
    workspaces = _load("workspaces.json")
    records = _load("records.json")
    notes_tasks = _load("notes_tasks.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("NOT_FOUND", "Workspace not available.")

    comp = next((r for r in records if isinstance(r, dict) and r.get("id") == company_record_id and r.get("workspace_id") == workspace_id), None)
    if not comp or comp.get("record_type") != "company":
        return _err("NOT_FOUND", "Company record not found.")

    # ---- cursor decoding ----
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            cobj = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "Unsupported cursor.")
        if not isinstance(cobj, dict) or cobj.get("v") != 1 or cobj.get("ws") != workspace_id or cobj.get("company") != company_record_id:
            return _err("VALIDATION_ERROR", "Unsupported cursor.")
        if cobj.get("sort") != sort or cobj.get("order") != order or cobj.get("status") != (status if status is not None else None):
            return _err("VALIDATION_ERROR", "Cursor does not match the requested parameters.")
        start = cobj.get("start")
        if not isinstance(start, int) or start < 0:
            return _err("VALIDATION_ERROR", "Unsupported cursor.")

    # ---- filter ----
    rows = []
    for nt in notes_tasks:
        if not isinstance(nt, dict):
            continue
        if nt.get("workspace_id") != workspace_id:
            continue
        if nt.get("activity_type") != "note":
            continue
        if status is not None and nt.get("status") != status:
            continue
        linked = nt.get("linked_record_ids")
        if not isinstance(linked, list):
            continue
        if company_record_id not in linked:
            continue
        rows.append(nt)

    # ---- sort/paginate ----
    def _dt_key(v):
        if not v:
            return ""
        return str(v)

    reverse = (order == "desc")
    rows.sort(key=lambda x: _dt_key(x.get(sort)), reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < total:
        cobj = {"v": 1, "ws": workspace_id, "company": company_record_id, "sort": sort, "order": order, "status": (status if status is not None else None), "start": start + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(cobj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # ---- observable dynamics (request log) ----
    latency_ms = int((time.time() - t0) * 1000)
    req = _load("request_log.json")
    if not isinstance(req, list):
        req = []
    req.append({
        "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + str(int(time.time() * 1000))[-6:],
        "endpoint": "get-company-notes",
        "workspace_id": workspace_id,
        "status": "ok",
        "timestamp": now,
        "latency_ms": latency_ms
    })
    _save("request_log.json", req)

    return {
        "notes": page,
        "page": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "total": total,
            "has_more": (next_cursor is not None)
        }
    }

