def search_companies_by_people(workspace_id, people_query, company_filters=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_domain(s):
        if not isinstance(s, str):
            return None
        s = s.strip()
        if not s:
            return None
        if "://" not in s:
            s2 = "http://" + s
        else:
            s2 = s
        try:
            u = urlparse(s2)
            host = (u.hostname or "").lower()
        except Exception:
            host = ""
        if host.startswith("www."):
            host = host[4:]
        if not host:
            # fallback: treat as host token before slash
            t = s.split("/")[0].lower()
            if t.startswith("www."):
                t = t[4:]
            host = t
        return host or None

    def _stringify_for_search(obj, max_chars=20000):
        # Flatten dict/list into searchable text without blowing up.
        out = []
        def walk(x, depth=0):
            if len(out) > 2000:
                return
            if depth > 6:
                return
            if isinstance(x, str):
                out.append(x)
            elif isinstance(x, (int, float, bool)):
                out.append(str(x))
            elif isinstance(x, dict):
                for k, v in x.items():
                    if isinstance(k, str):
                        out.append(k)
                    walk(v, depth + 1)
            elif isinstance(x, list):
                for v in x[:200]:
                    walk(v, depth + 1)
        walk(obj)
        s = " ".join(out)
        if len(s) > max_chars:
            s = s[:max_chars]
        return s.lower()

    t0 = time.time()
    now = _now()

    # ---- validation ----
    ws_pat = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(workspace_id, str) or not ws_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(people_query, dict):
        return _err("VALIDATION_ERROR", "people_query must be an object.")
    for k in people_query.keys():
        if k not in ("text", "attributes", "status"):
            return _err("VALIDATION_ERROR", f"Unsupported people_query field: {k}")
    pq_text = people_query.get("text")
    if pq_text is not None and not isinstance(pq_text, str):
        return _err("VALIDATION_ERROR", "people_query.text must be a string.")
    pq_attrs = people_query.get("attributes")
    if pq_attrs is not None and not isinstance(pq_attrs, dict):
        return _err("VALIDATION_ERROR", "people_query.attributes must be an object.")
    pq_status = people_query.get("status")
    if pq_status is not None and pq_status not in ("active", "archived", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid people_query.status.")

    if company_filters is not None and not isinstance(company_filters, dict):
        return _err("VALIDATION_ERROR", "company_filters must be an object.")
    if company_filters:
        for k in company_filters.keys():
            if k not in ("status", "domain"):
                return _err("VALIDATION_ERROR", f"Unsupported company_filters field: {k}")
        if company_filters.get("status") is not None and company_filters.get("status") not in ("active", "archived", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid company_filters.status.")
        if company_filters.get("domain") is not None and not isinstance(company_filters.get("domain"), str):
            return _err("VALIDATION_ERROR", "company_filters.domain must be a string.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    if sort is None:
        sort = "display_name"
    if sort not in ("display_name", "last_activity_at", "last_interaction_at", "created_at", "updated_at"):
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order.")

    # ---- load data ----
    workspaces = _load("workspaces.json")
    records = _load("records.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("NOT_FOUND", "Workspace not available.")

    # ---- cursor ----
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            cobj = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "Unsupported cursor.")
        if not isinstance(cobj, dict) or cobj.get("v") != 1 or cobj.get("ws") != workspace_id:
            return _err("VALIDATION_ERROR", "Unsupported cursor.")
        if cobj.get("sort") != sort or cobj.get("order") != order:
            return _err("VALIDATION_ERROR", "Cursor does not match the requested parameters.")
        if cobj.get("pq") != people_query or cobj.get("cf") != (company_filters if company_filters is not None else None):
            return _err("VALIDATION_ERROR", "Cursor does not match the requested filters.")
        start = cobj.get("start")
        if not isinstance(start, int) or start < 0:
            return _err("VALIDATION_ERROR", "Unsupported cursor.")

    # ---- person selection ----
    pq_status_eff = pq_status if pq_status is not None else "active"
    text_terms = []
    if isinstance(pq_text, str):
        text_terms = [t for t in re.split(r"\s+", pq_text.strip().lower()) if t]

    matched_people = []
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("record_type") != "person":
            continue
        if r.get("status") != pq_status_eff:
            continue

        ok = True
        if pq_attrs:
            attrs = r.get("attributes")
            if not isinstance(attrs, dict):
                ok = False
            else:
                for k, v in pq_attrs.items():
                    if k not in attrs:
                        return _err("VALIDATION_ERROR", f"Invalid attribute key in people_query.attributes: {k}")
                    if attrs.get(k) != v:
                        ok = False
                        break

        if ok and text_terms:
            hay = " ".join([
                str(r.get("display_name") or ""),
                str(r.get("email") or ""),
                _stringify_for_search(r.get("attributes") if isinstance(r.get("attributes"), dict) else {}),
                _stringify_for_search(r.get("raw_json") if isinstance(r.get("raw_json"), dict) else {})
            ]).lower()
            for term in text_terms:
                if term not in hay:
                    ok = False
                    break

        if ok:
            matched_people.append(r)

    # ---- association heuristic ----
    # Datastore schema provides no explicit company-person relation. Implement best-effort:
    # - If person.attributes has 'company_record_id' referencing a company id, use it.
    # - Else if person.attributes has 'company_domain' or 'domain' or 'website', match to company.domain.
    company_ids = set()
    companies_by_domain = {}
    for r in records:
        if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("record_type") == "company":
            d = r.get("domain")
            if isinstance(d, str) and d:
                companies_by_domain.setdefault(d, []).append(r)

    for p in matched_people:
        attrs = p.get("attributes") if isinstance(p.get("attributes"), dict) else {}
        cid = attrs.get("company_record_id")
        if isinstance(cid, str):
            company_ids.add(cid)
            continue
        d = attrs.get("company_domain") or attrs.get("domain") or attrs.get("website")
        d = _norm_domain(d) if d is not None else None
        if d and d in companies_by_domain:
            for c in companies_by_domain[d]:
                company_ids.add(c.get("id"))

    # ---- company filtering ----
    comp_status = None
    comp_domain = None
    if company_filters:
        comp_status = company_filters.get("status")
        comp_domain = company_filters.get("domain")
    comp_status_eff = comp_status if comp_status is not None else "active"
    comp_domain_norm = _norm_domain(comp_domain) if comp_domain is not None else None

    companies = []
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("record_type") != "company":
            continue
        if r.get("id") not in company_ids:
            continue
        if r.get("status") != comp_status_eff:
            continue
        if comp_domain_norm is not None and r.get("domain") != comp_domain_norm:
            continue
        companies.append(r)

    # ---- sort/paginate ----
    reverse = (order == "desc")

    def _key(r):
        v = r.get(sort)
        if v is None:
            return ""
        return str(v).lower() if isinstance(v, str) else str(v)

    companies.sort(key=_key, reverse=reverse)
    total = len(companies)
    page = companies[start:start + limit]

    next_cursor = None
    if start + limit < total:
        cobj = {"v": 1, "ws": workspace_id, "sort": sort, "order": order, "pq": people_query, "cf": (company_filters if company_filters is not None else None), "start": start + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(cobj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # ---- observable dynamics (request log) ----
    latency_ms = int((time.time() - t0) * 1000)
    req = _load("request_log.json")
    if not isinstance(req, list):
        req = []
    req.append({
        "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + str(int(time.time() * 1000))[-6:],
        "endpoint": "search-companies-by-people",
        "workspace_id": workspace_id,
        "status": "ok",
        "timestamp": now,
        "latency_ms": latency_ms
    })
    _save("request_log.json", req)

    return {
        "companies": page,
        "page": {
            "limit": limit,
