        }
    }

def search_companies_by_people_list(workspace_id, people_list_id, company_filters=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_domain(s):
        if not isinstance(s, str):
            return None
        s = s.strip()
        if not s:
            return None
        if "://" not in s:
            s2 = "http://" + s
        else:
            s2 = s
        try:
            u = urlparse(s2)
            host = (u.hostname or "").lower()
        except Exception:
            host = ""
        if host.startswith("www."):
            host = host[4:]
        if not host:
            t = s.split("/")[0].lower()
            if t.startswith("www."):
                t = t[4:]
            host = t
        return host or None

    t0 = time.time()
    now = _now()

    # ---- validation ----
    ws_pat = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    lst_pat = re.compile(r"^att_lst_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(workspace_id, str) or not ws_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(people_list_id, str) or not lst_pat.match(people_list_id):
        return _err("VALIDATION_ERROR", "Invalid people_list_id.")

    if company_filters is not None and not isinstance(company_filters, dict):
        return _err("VALIDATION_ERROR", "company_filters must be an object.")
    if company_filters:
        for k in company_filters.keys():
            if k not in ("status", "domain"):
                return _err("VALIDATION_ERROR", f"Unsupported company_filters field: {k}")
        if company_filters.get("status") is not None and company_filters.get("status") not in ("active", "archived", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid company_filters.status.")
        if company_filters.get("domain") is not None and not isinstance(company_filters.get("domain"), str):
            return _err("VALIDATION_ERROR", "company_filters.domain must be a string.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    if sort is None:
        sort = "display_name"
    if sort not in ("display_name", "last_activity_at", "last_interaction_at", "created_at", "updated_at"):
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order.")

    # ---- load data ----
    workspaces = _load("workspaces.json")
    lists = _load("lists.json")
    list_entries = _load("list_entries.json")
    records = _load("records.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("NOT_FOUND", "Workspace not available.")

    lst = next((l for l in lists if isinstance(l, dict) and l.get("id") == people_list_id and l.get("workspace_id") == workspace_id), None)
    if not lst:
        return _err("NOT_FOUND", "People list not found.")
    if lst.get("status") != "active":
        return _err("NOT_FOUND", "People list not available.")
    if lst.get("applies_to") not in ("person", "mixed"):
        return _err("VALIDATION_ERROR", "people_list_id does not reference a people-compatible list.")

    # ---- cursor ----
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            cobj = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "Unsupported cursor.")
        if not isinstance(cobj, dict) or cobj.get("v") != 1 or cobj.get("ws") != workspace_id or cobj.get("list") != people_list_id:
            return _err("VALIDATION_ERROR", "Unsupported cursor.")
        if cobj.get("sort") != sort or cobj.get("order") != order:
            return _err("VALIDATION_ERROR", "Cursor does not match the requested parameters.")
        if cobj.get("cf") != (company_filters if company_filters is not None else None):
            return _err("VALIDATION_ERROR", "Cursor does not match the requested filters.")
        start = cobj.get("start")
        if not isinstance(start, int) or start < 0:
            return _err("VALIDATION_ERROR", "Unsupported cursor.")

    # ---- people in list ----
    active_people_ids = set()
    for e in list_entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id:
            continue
        if e.get("list_id") != people_list_id:
            continue
        if e.get("status") != "active":
            continue
        rid = e.get("record_id")
        if isinstance(rid, str):
            active_people_ids.add(rid)

    # keep only those that are actually person records
    people_records = []
    for r in records:
        if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("id") in active_people_ids and r.get("record_type") == "person":
            if r.get("status") == "active":  # tools default to active only
                people_records.append(r)

    # ---- association heuristic (same as other endpoint) ----
    companies_by_domain = {}
    for r in records:
        if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("record_type") == "company":
            d = r.get("domain")
            if isinstance(d, str) and d:
                companies_by_domain.setdefault(d, []).append(r)

    company_ids = set()
    for p in people_records:
        attrs = p.get("attributes") if isinstance(p.get("attributes"), dict) else {}
        cid = attrs.get("company_record_id")
        if isinstance(cid, str):
            company_ids.add(cid)
            continue
        d = attrs.get("company_domain") or attrs.get("domain") or attrs.get("website")
        d = _norm_domain(d) if d is not None else None
        if d and d in companies_by_domain:
            for c in companies_by_domain[d]:
                company_ids.add(c.get("id"))

    # ---- company filters ----
    comp_status = None
    comp_domain = None
    if company_filters:
        comp_status = company_filters.get("status")
        comp_domain = company_filters.get("domain")
    comp_status_eff = comp_status if comp_status is not None else "active"
    comp_domain_norm = _norm_domain(comp_domain) if comp_domain is not None else None

    companies = []
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("record_type") != "company":
            continue
        if r.get("id") not in company_ids:
            continue
        if r.get("status") != comp_status_eff:
            continue
        if comp_domain_norm is not None and r.get("domain") != comp_domain_norm:
            continue
        companies.append(r)

    # ---- sort/paginate ----
    reverse = (order == "desc")

    def _key(r):
        v = r.get(sort)
        if v is None:
            return ""
        return str(v).lower() if isinstance(v, str) else str(v)

    companies.sort(key=_key, reverse=reverse)
    total = len(companies)
    page = companies[start:start + limit]

    next_cursor = None
    if start + limit < total:
        cobj = {"v": 1, "ws": workspace_id, "list": people_list_id, "sort": sort, "order": order, "cf": (company_filters if company_filters is not None else None), "start": start + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(cobj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # ---- observable dynamics (request log) ----
    latency_ms = int((time.time() - t0) * 1000)
    req = _load("request_log.json")
    if not isinstance(req, list):
        req = []
    req.append({
        "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + str(int(time.time() * 1000))[-6:],
        "endpoint": "search-companies-by-people-list",
        "workspace_id": workspace_id,
        "status": "ok",
        "timestamp": now,
        "latency_ms": latency_ms
    })
    _save("request_log.json", req)

    return {
        "companies": page,
        "page": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "total": total,
            "has_more": (next_cursor is not None)
        }
    }

def search_companies_by_notes(workspace_id, query, match=None, include_archived=None, note_status=None, updated_after=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "search-companies-by-notes"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _encode_cursor(payload_dict):
        raw = json.dumps(payload_dict, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        sig = hashlib.sha256(raw).hexdigest()[:16]
        blob = json.dumps({"p": payload_dict, "s": sig}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(blob).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return _err("VALIDATION_ERROR", "cursor is malformed")
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            blob = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(blob.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is malformed")
        if not isinstance(obj, dict) or "p" not in obj or "s" not in obj:
            return _err("VALIDATION_ERROR", "cursor is malformed")
        p = obj["p"]
        s = obj["s"]
        if not isinstance(p, dict) or not isinstance(s, str):
            return _err("VALIDATION_ERROR", "cursor is malformed")
        raw = json.dumps(p, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        sig = hashlib.sha256(raw).hexdigest()[:16]
        if sig != s:
            return _err("VALIDATION_ERROR", "cursor is malformed")
        return p

    def _log_request(status_code, latency_ms, used_workspace_row_id=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "workspace_id": used_workspace_row_id,
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            })
            _save("request_logs.json", logs)

    def _enforce_limits(used_workspace_row_id=None):
        rate_cfg = _load("rate_limits.json")
        if not isinstance(rate_cfg, list) or not rate_cfg:
            return None
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        def _count(window_s, endpoint_match):
            cutoff = now - datetime.timedelta(seconds=window_s)
            c = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if used_workspace_row_id is not None and r.get("workspace_id") != used_workspace_row_id:
                    continue
                ep = r.get("endpoint")
                if endpoint_match is not None and ep != endpoint_match:
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts is None:
                    continue
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts >= cutoff:
                    c += 1
            return c

        for rule in rate_cfg:
            if not isinstance(rule, dict):
                continue
            ep = rule.get("endpoint")
            if ep not in (None, "*", endpoint):
                continue
            window_s = rule.get("window_seconds")
            limit_n = rule.get("limit")
            scope = rule.get("scope", "workspace")
            if not isinstance(window_s, int) or window_s <= 0 or not isinstance(limit_n, int) or limit_n < 0:
                continue
            if scope == "workspace" and used_workspace_row_id is None:
                continue
            current = _count(window_s, None if ep in (None, "*") else endpoint)
            if current >= limit_n:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=limit_n, window_seconds=window_s)
        return None

    # Validate inputs
    if not isinstance(workspace_id, str) or re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id) is None:
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), None)
        return _err("VALIDATION_ERROR", "workspace_id is not a valid att_ws_ ULID")

    if not isinstance(query, str) or len(query.strip()) < 1:
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    q = query.strip()

    if match is None:
        match = "contains"
    if not isinstance(match, str) or match not in {"contains", "exact"}:
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "match must be one of the allowed values")

    if include_archived is None:
        include_archived = False
    if not isinstance(include_archived, bool):
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "include_archived must be a boolean")

    if note_status is not None:
        if not isinstance(note_status, str) or note_status not in {"active", "deleted"}:
            _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
            return _err("VALIDATION_ERROR", "note_status must be one of the allowed values")

    updated_after_dt = None
    if updated_after is not None:
        updated_after_dt = _parse_dt(updated_after)
        if updated_after_dt is None:
            _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
            return _err("VALIDATION_ERROR", "updated_after is not a valid date-time")
        if updated_after_dt.tzinfo is None:
            updated_after_dt = updated_after_dt.replace(tzinfo=datetime.timezone.utc)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if sort is None:
        sort = "relevance"
    if not isinstance(sort, str) or sort not in {"relevance", "last_activity_at", "updated_at", "display_name"}:
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "sort must be one of the allowed values")

    if order is None:
        order = "desc" if sort != "display_name" else "asc"
    if not isinstance(order, str) or order not in {"asc", "desc"}:
        _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
        return _err("VALIDATION_ERROR", "order must be one of the allowed values")

    cur_payload = None
    if cursor is not None:
        dc = _decode_cursor(cursor)
        if isinstance(dc, dict) and "error" in dc:
            _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), workspace_id)
            return dc
        cur_payload = dc

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("attio_workspace_id") == workspace_id:
            ws = w
            break
    if ws is None:
        _log_request("NOT_FOUND", int((time.time() - _t0) * 1000), None)
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log_request("UNAUTHORIZED", int((time.time() - _t0) * 1000), ws.get("id"))
        return _err("UNAUTHORIZED", "Workspace is not active or not authorized")

    rl = _enforce_limits(ws.get("id"))
    if rl is not None:
        _log_request("RATE_LIMIT", int((time.time() - _t0) * 1000), ws.get("id"))
        return rl

    if cur_payload is not None:
        expected_keys = ["workspace_attio_id", "query", "match", "include_archived", "note_status", "updated_after", "sort", "order", "offset"]
        if any(k not in cur_payload for k in expected_keys):
            _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), ws.get("id"))
            return _err("VALIDATION_ERROR", "cursor is malformed")
        if cur_payload.get("workspace_attio_id") != workspace_id or cur_payload.get("query") != q or cur_payload.get("match") != match or cur_payload.get("include_archived") != include_archived or cur_payload.get("note_status") != note_status or cur_payload.get("updated_after") != updated_after or cur_payload.get("sort") != sort or cur_payload.get("order") != order:
            _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), ws.get("id"))
            return _err("VALIDATION_ERROR", "cursor does not match request parameters")
        offset = cur_payload.get("offset")
        if not isinstance(offset, int) or offset < 0:
            _log_request("VALIDATION_ERROR", int((time.time() - _t0) * 1000), ws.get("id"))
            return _err("VALIDATION_ERROR", "cursor is malformed")
    else:
        offset = 0

    records = _load("records.json")
    if not isinstance(records, list):
        records = []
    notes = _load("notes_tasks.json")
    if not isinstance(notes, list):
        notes = []

    # Build company map in workspace (active plus optionally archived; never include deleted companies here)
    company_rows = {}
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != ws.get("id"):
            continue
        if r.get("record_type") != "company":
            continue
        st = r.get("status")
        if st == "deleted":
            continue
        if st == "archived" and not include_archived:
            continue
        if st not in ("active", "archived"):
            continue
        company_rows[r.get("id")] = r

    q_l = q.lower()

    def _note_matches(nrow):
        body = nrow.get("body") or ""
        title = nrow.get("title") or ""
        txt = (str(title) + "\n" + str(body)).strip()
        if match == "exact":
            return txt.lower() == q_l
        return q_l in txt.lower()

    def _dt_or_min(val):
        dt = _parse_dt(val) if isinstance(val, str) else None
        if dt is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    # Find matching notes and aggregate by company
    company_agg = {}  # company_id -> {score, last_note_updated, matched_notes_count}
    for n in notes:
        if not isinstance(n, dict):
            continue
        if n.get("workspace_id") != ws.get("id"):
            continue
        if n.get("activity_type") != "note":
            continue
        if note_status is not None and n.get("status") != note_status:
            continue
        # notes are active/deleted per schema; treat completed irrelevant
        if n.get("status") not in ("active", "deleted"):
            continue
        upd = _dt_or_min(n.get("updated_at"))
        if updated_after_dt is not None and upd <= updated_after_dt:
            continue
        if not _note_matches(n):
            continue

        linked = n.get("linked_record_ids")
        if not isinstance(linked, list):
            continue
        # only consider linked companies in current eligible set
        for rid in linked:
            if rid in company_rows:
                agg = company_agg.get(rid)
                if agg is None:
                    agg = {"score": 0, "last_note_updated": upd, "matched_notes_count": 0}
                    company_agg[rid] = agg
                agg["matched_notes_count"] += 1
                # simple relevance: exact match yields bigger score; contains yields proportional
                if match == "exact":
                    agg["score"] += 10
                else:
                    agg["score"] += 3
                if upd > agg["last_note_updated"]:
                    agg["last_note_updated"] = upd

    # Convert to candidates
    candidates = []
    for cid, agg in company_agg.items():
        r = company_rows.get(cid)
        if not isinstance(r, dict):
            continue
        candidates.append({
            "_row": r,
            "_score": agg["score"],
            "_last_note_updated": agg["last_note_updated"],
            "_matched_notes_count": agg["matched_notes_count"],
            "_display": (r.get("display_name") or "").lower(),
            "_updated": _dt_or_min(r.get("updated_at")),
            "_last_act": _dt_or_min(r.get("last_activity_at")),
        })

    reverse = (order == "desc")
    if sort == "relevance":
        candidates.sort(key=lambda x: (x["_score"], x["_last_note_updated"], x["_updated"]), reverse=True)
    elif sort == "last_activity_at":
        candidates.sort(key=lambda x: (x["_last_act"], x["_updated"]), reverse=reverse)
    elif sort == "updated_at":
        candidates.sort(key=lambda x: (x["_updated"], x["_last_note_updated"]), reverse=reverse)
    elif sort == "display_name":
        candidates.sort(key=lambda x: (x["_display"], x["_updated"]), reverse=reverse)

    total = len(candidates)
    page = candidates[offset: offset + limit]
    rows = []
    for x in page:
        r = x["_row"]
        rows.append({
            "id": r.get("id"),
            "attio_record_id": r.get("attio_record_id"),
            "attio_object": r.get("attio_object"),
            "display_name": r.get("display_name"),
            "domain": r.get("domain"),
            "status": r.get("status"),
            "updated_at": r.get("updated_at"),
            "last_activity_at": r.get("last_activity_at"),
            "matched_notes_count": x["_matched_notes_count"],
            "last_matching_note_updated_at": x["_last_note_updated"].isoformat().replace("+00:00", "Z"),
        })

    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({
        "workspace_attio_id": workspace_id,
        "query": q,
        "match": match,
        "include_archived": include_archived,
        "note_status": note_status,
        "updated_after": updated_after,
        "sort": sort,
        "order": order,
        "offset": next_offset
    }) if has_more else None

    latency_ms = int((time.time() - _t0) * 1000)
    _log_request("OK", latency_ms, ws.get("id"))
    return {
        "companies": rows,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
            "match": match,
            "include_archived": include_archived,
            "note_status": note_status,
            "updated_after": updated_after
        }
    }

def get_company_lists(workspace_id, company_id, include_removed=None, list_type=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _b64url_decode(s):
        try:
            if not isinstance(s, str):
                return None
            pad = "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("utf-8"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _b64url_encode(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _ensure_request_log(status_s, latency_ms, used_cred=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "req_" + re.sub(r"[^0-9]", "", str(int(time.time() * 1000))) + "_" + str(len(logs) + 1),
                "endpoint": "get-company-lists",
                "workspace_id": workspace_id,
                "credential_id": used_cred,
                "status": status_s,
                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            })
            _save("request_logs.json", logs)

    t0 = time.time()

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
        out = _err("VALIDATION_ERROR", "Invalid workspace_id.")
        _ensure_request_log("error", int((time.time() - t0) * 1000))
        return out

    if not isinstance(company_id, str) or not re.match(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$", company_id):
        out = _err("VALIDATION_ERROR", "Invalid company_id.")
        _ensure_request_log("error", int((time.time() - t0) * 1000))
        return out

    if include_removed is None:
        include_removed = False
    if not isinstance(include_removed, bool):
        out = _err("VALIDATION_ERROR", "include_removed must be boolean.")
        _ensure_request_log("error", int((time.time() - t0) * 1000))
        return out

    if list_type is not None and list_type not in ("pipeline", "segment", "static", "other"):
        out = _err("VALIDATION_ERROR", "Invalid list_type.")
        _ensure_request_log("error", int((time.time() - t0) * 1000))
        return out

    if status is not None and status not in ("active", "archived", "deleted"):
        out = _err("VALIDATION_ERROR", "Invalid status.")
        _ensure_request_log("error", int((time.time() - t0) * 1000))
        return out

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        out = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        _ensure_request_log("error", int((time.time() - t0) * 1000))
        return out

    if sort is None:
        sort = "name"
    if sort not in ("name", "created_at", "updated_at"):
        out = _err("VALIDATION_ERROR", "Invalid sort.")
        _ensure_request_log("error", int((time.time() - t0) * 1000))
        return out

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        out = _err("VALIDATION_ERROR", "Invalid order.")
        _ensure_request_log("error", int((time.time() - t0) * 1000))
        return out
    order_desc = (order == "desc")

    cursor_obj = None
    if cursor is not None:
        cursor_obj = _b64url_decode(cursor)
        if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1 or cursor_obj.get("endpoint") != "get-company-lists":
            out = _err("VALIDATION_ERROR", "Invalid cursor.")
            _ensure_request_log("error", int((time.time() - t0) * 1000))
            return out
        if cursor_obj.get("workspace_id") != workspace_id or cursor_obj.get("company_id") != company_id or cursor_obj.get("include_removed") != include_removed or cursor_obj.get("list_type") != list_type or cursor_obj.get("status") != status or cursor_obj.get("sort") != sort or cursor_obj.get("order") != order:
            out = _err("VALIDATION_ERROR", "Cursor does not match request parameters.")
            _ensure_request_log("error", int((time.time() - t0) * 1000))
            return out

    # Workspace existence
    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if ws is None:
        out = _err("NOT_FOUND", "Workspace not found.")
        _ensure_request_log("error", int((time.time() - t0) * 1000))
        return out

    # Company existence (must be in workspace and type company)
    records = _load("records.json")
    company = None
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("id") == company_id and r.get("workspace_id") == workspace_id and r.get("record_type") == "company":
            company = r
            break
    if company is None:
        out = _err("NOT_FOUND", "Company not found.")
        _ensure_request_log("error", int((time.time() - t0) * 1000))
        return out

    lists = _load("lists.json")
    entries = _load("list_entries.json")

    # Build active/removed memberships for company
    memberships = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id:
            continue
        if e.get("record_id") != company_id:
            continue
        est = e.get("status")
        if est == "active":
            pass
        elif est == "removed":
            if not include_removed:
                continue
        else:
            continue

        lid = e.get("list_id")
        if not isinstance(lid, str):
            continue

        # Find list
        lst = None
        for l in lists:
            if isinstance(l, dict) and l.get("id") == lid and l.get("workspace_id") == workspace_id:
                lst = l
                break
        if lst is None:
            # FK says cascade, but if inconsistent, skip rather than crash
            continue

        if list_type is not None and lst.get("list_type") != list_type:
            continue
        if status is not None and lst.get("status") != status:
            continue

        memberships.append({
            "list": lst,
            "entry": e,
            "_sort": {
                "name": (lst.get("name") or "").lower() if isinstance(lst.get("name"), str) else "",
                "created_at": _parse_dt(lst.get("created_at")) if isinstance(lst.get("created_at"), str) else None,
                "updated_at": _parse_dt(lst.get("updated_at")) if isinstance(lst.get("updated_at"), str) else None,
            }
        })

    def _dt_or_min(x):
        if isinstance(x, datetime.datetime):
            return x
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    if sort == "name":
        memberships.sort(key=lambda x: (x["_sort"]["name"],), reverse=order_desc)
    elif sort == "created_at":
        memberships.sort(key=lambda x: (_dt_or_min(x["_sort"]["created_at"]), x["_sort"]["name"]), reverse=order_desc)
    elif sort == "updated_at":
        memberships.sort(key=lambda x: (_dt_or_min(x["_sort"]["updated_at"]), x["_sort"]["name"]), reverse=order_desc)

    start = 0
    if cursor_obj is not None:
        last_list_id = cursor_obj.get("last_list_id")
        last_entry_id = cursor_obj.get("last_entry_id")
        if isinstance(last_list_id, str) and isinstance(last_entry_id, str):
            for i, it in enumerate(memberships):
                if it.get("list", {}).get("id") == last_list_id and it.get("entry", {}).get("id") == last_entry_id:
                    start = i + 1
                    break

    page = memberships[start:start + limit]
    has_more = (start + limit) < len(memberships)
    next_cursor = None
    if has_more and page:
        next_cursor = _b64url_encode({
            "v": 1,
            "endpoint": "get-company-lists",
            "workspace_id": workspace_id,
            "company_id": company_id,
            "include_removed": include_removed,
            "list_type": list_type,
            "status": status,
            "sort": sort,
            "order": order,
            "last_list_id": page[-1]["list"].get("id"),
            "last_entry_id": page[-1]["entry"].get("id"),
        })

    out_rows = []
    for it in page:
        lst = it["list"]
        e = it["entry"]
        out_rows.append({
            "list": lst,
            "membership": {
                "entry_id": e.get("id"),
                "status": e.get("status"),
                "added_at": e.get("added_at"),
                "removed_at": e.get("removed_at"),
                "entry_attributes": e.get("entry_attributes"),
                "attio_entry_id": e.get("attio_entry_id"),
                "created_at": e.get("created_at"),
                "updated_at": e.get("updated_at"),
            }
        })

    latency_ms = int((time.time() - t0) * 1000)
    _ensure_request_log("ok", latency_ms)

    return {
        "company": {"id": company_id, "display_name": company.get("display_name"), "domain": company.get("domain"), "status": company.get("status")},
        "lists": out_rows,
        "meta": {
            "total": len(memberships),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order
        }
    }

def batch_create_companies(workspace_id, companies, **_extra):
    import json, os, datetime, re, time, secrets
    from urllib.parse import urlparse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "batch-create-companies"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _get_log_file():
        for fn in ("request_logs.json", "usage.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(status_s, detail=None):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_%d_%d" % (int(time.time() * 1000), len(logs) + 1),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail,
        })
        _save(fn, logs)

    def _normalize_domain(d):
        if d is None:
            return None
        if not isinstance(d, str):
            return _err("VALIDATION_ERROR", "domain must be a string")
        s = d.strip().lower()
        if not s:
            return None
        host = None
        if "://" in s:
            p = urlparse(s)
            host = p.hostname
        if not host:
            host = s.split("/")[0].split("?")[0].split("#")[0]
            host = host.split("@")[-1]
            host = host.split(":")[0]
        host = (host or "").strip().lower()
        if host.startswith("www."):
            host = host[4:]
        if not host or any(c.isspace() for c in host) or "/" in host:
            return _err("VALIDATION_ERROR", "domain must be a normalized host (no scheme/path)")
        return host

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "workspace_id is invalid", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(companies, list) or len(companies) < 1 or len(companies) > 100:
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "companies must be an array with 1..100 items", "field": "companies"})
        return _err("VALIDATION_ERROR", "companies must be an array with 1..100 items", field="companies")
    for i, c in enumerate(companies):
        if not isinstance(c, dict):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"companies[{i}] must be an object", "field": "companies"})
            return _err("VALIDATION_ERROR", f"companies[{i}] must be an object", field="companies")
        dn = c.get("display_name")
        if not isinstance(dn, str) or not dn.strip():
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"companies[{i}].display_name is required", "field": "display_name"})
            return _err("VALIDATION_ERROR", f"companies[{i}].display_name is required", field="display_name")

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws_row is None:
        _log("error", detail={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")
    if ws_row.get("status") != "active":
        _log("error", detail={"code": "UNAUTHORIZED", "message": "No active workspace connection available for this request"})
        return _err("UNAUTHORIZED", "No active workspace connection available for this request")

    records = _load("records.json")
    if isinstance(records, dict) and "rows" in records:
        records = records.get("rows")
    if not isinstance(records, list):
        records = []

    existing_trip = {(r.get("workspace_id"), r.get("attio_object"), r.get("attio_record_id")) for r in records if isinstance(r, dict)}

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        v = ms
        ts_chars = []
        for _ in range(10):
            v, r = divmod(v, 32)
            ts_chars.append(alphabet[r])
        ts = "".join(reversed(ts_chars))
        rand = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{ts}{rand}"

    now = _now_iso()
    results = []
    created = []

    for idx, c in enumerate(companies):
        item_err = None
        try:
            dom = _normalize_domain(c.get("domain"))
            if isinstance(dom, dict) and "error" in dom:
                item_err = dom["error"]
            elif c.get("status") is not None and c.get("status") not in ("active", "archived", "deleted"):
                item_err = {"code": "VALIDATION_ERROR", "message": "status is invalid", "field": "status"}
            else:
                for fld in ("social", "contact", "business", "attributes", "raw_json"):
                    if c.get(fld) is not None and not isinstance(c.get(fld), dict):
                        item_err = {"code": "VALIDATION_ERROR", "message": f"{fld} must be an object", "field": fld}
                        break
        except Exception:
            item_err = {"code": "VALIDATION_ERROR", "message": "Invalid company payload"}

        if item_err is not None:
            results.append({"index": idx, "ok": False, "error": item_err})
            continue

        rec_id = _gen_id("att_rec")
        while any(isinstance(r, dict) and r.get("id") == rec_id for r in records) or any(r.get("id") == rec_id for r in created):
            rec_id = _gen_id("att_rec")

        attio_object = c.get("attio_object") if isinstance(c.get("attio_object"), str) and c.get("attio_object").strip() else "companies"
        attio_record_id = c.get("attio_record_id") if isinstance(c.get("attio_record_id"), str) and c.get("attio_record_id").strip() else _gen_id("attio")
        while (workspace_id, attio_object, attio_record_id) in existing_trip:
            attio_record_id = _gen_id("attio")

        row = {
            "id": rec_id,
            "workspace_id": workspace_id,
            "record_type": "company",
            "attio_object": attio_object,
            "attio_record_id": attio_record_id,
            "status": c.get("status") or "active",
            "display_name": c.get("display_name").strip(),
            "domain": dom,
            "email": None,  # companies schema allows nullable; tool may provide email but not persisted as primary by constraints for companies
            "phone": c.get("phone").strip() if isinstance(c.get("phone"), str) and c.get("phone").strip() else None,
            "social": c.get("social") if isinstance(c.get("social"), dict) else None,
            "contact": c.get("contact") if isinstance(c.get("contact"), dict) else None,
            "business": c.get("business") if isinstance(c.get("business"), dict) else None,
            "attributes": c.get("attributes") if isinstance(c.get("attributes"), dict) else {},
            "raw_json": c.get("raw_json") if isinstance(c.get("raw_json"), dict) else {},
            "last_interaction_at": None,
            "last_activity_at": None,
            "attio_created_at": None,
            "attio_updated_at": None,
            "created_at": now,
            "updated_at": now,
        }
        created.append(row)
        existing_trip.add((workspace_id, attio_object, attio_record_id))
        results.append({"index": idx, "ok": True, "company": row})

    if created:
        records.extend(created)
        _save("records.json", records)
    _log("ok", detail={"created": len(created), "failed": len(results) - len(created)})
    return {"results": results, "meta": {"created": len(created), "failed": len(results) - len(created)}}

