    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log("error", detail={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log("error", detail={"code": "UNAUTHORIZED", "message": "Workspace is not active", "status": ws.get("status")})
        return _err("UNAUTHORIZED", "Workspace is not active", status=ws.get("status"))

    records = _load("records.json")
    if not isinstance(records, list):
        records = []

    id_to_index = {}
    for i, r in enumerate(records):
        if isinstance(r, dict) and isinstance(r.get("id"), str):
            id_to_index[r["id"]] = i

    def _transition_ok(cur, to):
        transitions = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
        return cur == to or (cur in transitions and to in transitions[cur])

    results = []
    mutated = False
    now = _now_iso()

    for i, upd in enumerate(updates):
        if not isinstance(upd, dict):
            results.append({"company_id": None, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": f"updates[{i}] must be an object", "field": f"updates[{i}]"}})
            continue
        cid = upd.get("company_id")
        if not isinstance(cid, str) or not rec_re.fullmatch(cid):
            results.append({"company_id": cid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "company_id is invalid", "field": "company_id"}})
            continue
        idx = id_to_index.get(cid)
        if idx is None:
            results.append({"company_id": cid, "ok": False, "error": {"code": "NOT_FOUND", "message": "Company not found"}})
            continue
        rec = records[idx]
        if rec.get("workspace_id") != workspace_id:
            results.append({"company_id": cid, "ok": False, "error": {"code": "CONFLICT", "message": "Cross-workspace company update is not allowed"}})
            continue
        if rec.get("record_type") != "company":
            results.append({"company_id": cid, "ok": False, "error": {"code": "CONFLICT", "message": "Record is not a company", "record_type": rec.get("record_type")}})
            continue

        # Apply updates with validation
        patch = {}
        for k in ("display_name", "email", "phone", "attio_object", "attio_record_id"):
            if k in upd:
                if upd[k] is not None and not isinstance(upd[k], str):
                    results.append({"company_id": cid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": f"{k} must be a string", "field": k}})
                    patch = None
                    break
                patch[k] = upd[k]
        if patch is None:
            continue

        if "domain" in upd:
            nd = _normalize_domain(upd.get("domain"))
            if isinstance(nd, dict) and "error" in nd:
                results.append({"company_id": cid, "ok": False, "error": nd["error"]})
                continue
            patch["domain"] = nd

        for k in ("social", "contact", "business", "attributes", "raw_json"):
            if k in upd:
                v = upd.get(k)
                if v is not None and not isinstance(v, dict):
                    results.append({"company_id": cid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": f"{k} must be an object", "field": k}})
                    patch = None
                    break
                patch[k] = v
        if patch is None:
            continue

        if "status" in upd:
            st = upd.get("status")
            if st is not None and st not in ("active", "archived", "deleted"):
                results.append({"company_id": cid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "status is invalid", "field": "status"}})
                continue
            if st is not None and not _transition_ok(rec.get("status"), st):
                results.append({"company_id": cid, "ok": False, "error": {"code": "INVALID_TRANSITION", "message": "illegal status transition", "from_status": rec.get("status"), "to_status": st}})
                continue
            patch["status"] = st

        # Enforce constraints on email format (lightweight)
        if "email" in patch and patch["email"] is not None:
            em = patch["email"].strip().lower()
            if "@" not in em:
                results.append({"company_id": cid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "email must contain '@'", "field": "email"}})
                continue
            patch["email"] = em

        # Apply
        for k, v in patch.items():
            if k in ("attributes", "raw_json"):
                if v is None:
                    # keep existing non-null object (schema requires objects); treat None as no-op
                    continue
                rec[k] = v
            elif k in ("social", "contact", "business"):
                rec[k] = v
            elif k in ("display_name", "domain", "email", "phone", "attio_object", "attio_record_id", "status"):
                rec[k] = v

        rec["updated_at"] = now
        records[idx] = rec
        mutated = True
        results.append({"company_id": cid, "ok": True, "company": rec})

    if mutated:
        _save("records.json", records)
        _log("ok", detail={"updated": True, "count": sum(1 for r in results if r.get("ok"))})
    else:
        _log("ok", detail={"updated": False, "count": 0})

    return {
        "results": results,
        "meta": {
            "workspace_id": workspace_id,
            "updated_count": sum(1 for r in results if r.get("ok")),
            "failed_count": sum(1 for r in results if not r.get("ok")),
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def batch_delete_companies(workspace_id, company_ids, hard_delete=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "batch-delete-companies"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_request_log(status, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail
        })
        _save("request_logs.json", logs)

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    rec_re = re.compile(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _append_request_log("VALIDATION_ERROR", {"field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(company_ids, list) or len(company_ids) < 1 or len(company_ids) > 200:
        _append_request_log("VALIDATION_ERROR", {"field": "company_ids"})
        return _err("VALIDATION_ERROR", "company_ids must contain 1..200 items", field="company_ids")
    for i, cid in enumerate(company_ids):
        if not isinstance(cid, str) or not rec_re.fullmatch(cid):
            _append_request_log("VALIDATION_ERROR", {"field": "company_ids", "index": i})
            return _err("VALIDATION_ERROR", "company_ids contains an invalid id", field="company_ids", index=i)
    if hard_delete is not None and not isinstance(hard_delete, bool):
        _append_request_log("VALIDATION_ERROR", {"field": "hard_delete"})
        return _err("VALIDATION_ERROR", "hard_delete must be boolean when provided", field="hard_delete")
    if hard_delete is None:
        hard_delete = False

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _append_request_log("NOT_FOUND", {"workspace_id": workspace_id})
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    records = _load("records.json")
    if isinstance(records, dict) and "rows" in records:
        records = records.get("rows")
    if not isinstance(records, list):
        records = []

    list_entries = _load("list_entries.json")
    if isinstance(list_entries, dict) and "rows" in list_entries:
        list_entries = list_entries.get("rows")
    if not isinstance(list_entries, list):
        list_entries = []

    now = _now_iso()
    results = []
    any_effect = False

    # index for faster lookup
    rec_index = {r.get("id"): i for i, r in enumerate(records) if isinstance(r, dict) and isinstance(r.get("id"), str)}

    for cid in company_ids:
        idx = rec_index.get(cid)
        if idx is None:
            results.append({"id": cid, "ok": False, "error": {"code": "NOT_FOUND", "message": "Company record not found"}})
            continue
        r = records[idx]
        if r.get("workspace_id") != workspace_id or r.get("record_type") != "company":
            results.append({"id": cid, "ok": False, "error": {"code": "NOT_FOUND", "message": "Company record not found"}})
            continue

        if hard_delete:
            # physical delete
            any_effect = True
            records.pop(idx)
            # rebuild index after pop
            rec_index = {rr.get("id"): i for i, rr in enumerate(records) if isinstance(rr, dict) and isinstance(rr.get("id"), str)}
            # cascade: list_entries fk(record_id) on delete cascade
            new_le = []
            removed_count = 0
            for e in list_entries:
                if not isinstance(e, dict):
                    continue
                if e.get("record_id") == cid and e.get("workspace_id") == workspace_id:
                    removed_count += 1
                    continue
                new_le.append(e)
            list_entries = new_le
            results.append({"id": cid, "ok": True, "hard_deleted": True, "list_entries_deleted": removed_count})
        else:
            # soft delete: status transition active/archived -> deleted; deleted is terminal
            cur = r.get("status")
            if cur == "deleted":
                # idempotent success for already soft-deleted record
                results.append({"id": cid, "ok": True, "deleted": True, "already_deleted": True})
                continue
            if cur not in ("active", "archived"):
                results.append({"id": cid, "ok": False, "error": {"code": "INVALID_TRANSITION", "message": f"Cannot delete from status '{cur}'"}})
                continue

            r["status"] = "deleted"
            r["updated_at"] = now
            any_effect = True

            # remove active list memberships for this record in this workspace
            le_changed = 0
            for e in list_entries:
                if not isinstance(e, dict):
                    continue
                if e.get("workspace_id") != workspace_id:
                    continue
                if e.get("record_id") != cid:
                    continue
                if e.get("status") == "active":
                    e["status"] = "removed"
                    e["removed_at"] = now
                    e["updated_at"] = now
                    le_changed += 1

            results.append({"id": cid, "ok": True, "deleted": True, "list_entries_removed": le_changed})

    if any_effect:
        _save("records.json", records)
        _save("list_entries.json", list_entries)

    _append_request_log("OK", {"hard_delete": hard_delete, "requested": len(company_ids), "any_effect": any_effect})
    return {"data": {"results": results, "hard_delete": hard_delete}}

def batch_search_companies(workspace_id, searches, **_extra):
    import json, os, datetime, time, re, hashlib
    from urllib.parse import urlparse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "batch-search-companies"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _get_log_file():
        for fn in ("request_logs.json", "usage.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(status_s, detail=None):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail,
        })
        _save(fn, logs)

    def _normalize_domain(d):
        if d is None:
            return None
        if not isinstance(d, str):
            return None
        s = d.strip().lower()
        if not s:
            return None
        host = None
        if "://" in s:
            try:
                p = urlparse(s)
                host = p.hostname
            except Exception:
                host = None
        if not host:
            host = s.split("/")[0].split("?")[0].split("#")[0]
            host = host.split("@")[-1]
            host = host.split(":")[0]
        host = (host or "").strip().lower()
        if host.startswith("www."):
            host = host[4:]
        if not host or any(c.isspace() for c in host) or "/" in host:
            return None
        return host

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "workspace_id is invalid", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(searches, list) or len(searches) < 1 or len(searches) > 50:
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "searches must be an array with 1..50 items", "field": "searches"})
        return _err("VALIDATION_ERROR", "searches must be an array with 1..50 items", field="searches")
    for i, s in enumerate(searches):
        if not isinstance(s, dict):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"searches[{i}] must be an object", "field": "searches"})
            return _err("VALIDATION_ERROR", f"searches[{i}] must be an object", field="searches")
        if s.get("limit") is not None and (not isinstance(s.get("limit"), int) or s["limit"] < 1 or s["limit"] > 200):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"searches[{i}].limit must be 1..200", "field": "limit"})
            return _err("VALIDATION_ERROR", f"searches[{i}].limit must be 1..200", field="limit")
        if s.get("cursor") is not None and (not isinstance(s.get("cursor"), str) or not s.get("cursor").strip()):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"searches[{i}].cursor is malformed", "field": "cursor"})
            return _err("VALIDATION_ERROR", f"searches[{i}].cursor is malformed", field="cursor")
        if s.get("sort") is not None and s.get("sort") not in ("relevance", "last_activity_at", "updated_at", "display_name"):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"searches[{i}].sort is invalid", "field": "sort"})
            return _err("VALIDATION_ERROR", f"searches[{i}].sort is invalid", field="sort")
        if s.get("order") is not None and s.get("order") not in ("asc", "desc"):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"searches[{i}].order is invalid", "field": "order"})
            return _err("VALIDATION_ERROR", f"searches[{i}].order is invalid", field="order")
        if s.get("status") is not None and s.get("status") not in ("active", "archived", "deleted"):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"searches[{i}].status is invalid", "field": "status"})
            return _err("VALIDATION_ERROR", f"searches[{i}].status is invalid", field="status")
        if s.get("attributes") is not None and not isinstance(s.get("attributes"), dict):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"searches[{i}].attributes must be an object", "field": "attributes"})
            return _err("VALIDATION_ERROR", f"searches[{i}].attributes must be an object", field="attributes")

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws_row is None:
        _log("error", detail={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")
    if ws_row.get("status") != "active":
        _log("error", detail={"code": "UNAUTHORIZED", "message": "No active workspace connection available for this request"})
        return _err("UNAUTHORIZED", "No active workspace connection available for this request")

    records = _load("records.json")
    if isinstance(records, dict) and "rows" in records:
        records = records.get("rows")
    if not isinstance(records, list):
        records = []

    def _dt_key(v):
        if not isinstance(v, str) or not v:
            return None
        s = v
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _text_blob(rec):
        parts = []
        for k in ("display_name", "domain", "email", "phone", "attio_record_id", "attio_object"):
            v = rec.get(k)
            if isinstance(v, str) and v:
                parts.append(v)
        attrs = rec.get("attributes")
        if isinstance(attrs, dict):
            for vv in attrs.values():
                if isinstance(vv, str):
                    parts.append(vv)
        raw = rec.get("raw_json")
        if isinstance(raw, dict):
            for vv in raw.values():
                if isinstance(vv, str):
                    parts.append(vv)
        return " ".join(parts).lower()

    out = []
    for s in searches:
        q = (s.get("query") or "").strip().lower()
        dom = _normalize_domain(s.get("domain"))
        st = s.get("status") or "active"
        lim = s.get("limit") if s.get("limit") is not None else 20
        sort = s.get("sort") or "relevance"
        order = s.get("order") or ("desc" if sort in ("updated_at", "last_activity_at") else "asc")
        cur = s.get("cursor")
        offset = 0
        if isinstance(cur, str) and cur.strip().startswith("off:"):
            try:
                offset = int(cur.strip().split(":", 1)[1])
                if offset < 0:
                    offset = 0
            except Exception:
                offset = 0

        attr_filter = s.get("attributes") if isinstance(s.get("attributes"), dict) else {}

        matches = []
        for r in records:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id:
                continue
            if r.get("record_type") != "company":
                continue
            if r.get("status") != st:
                continue
            if dom is not None and r.get("domain") != dom:
                continue
            ok = True
            if attr_filter:
                attrs = r.get("attributes")
                if not isinstance(attrs, dict):
                    ok = False
                else:
                    for k, v in attr_filter.items():
                        if k not in attrs or attrs.get(k) != v:
                            ok = False
                            break
            if not ok:
                continue
            if q:
                if q not in _text_blob(r):
                    continue
            matches.append(r)

        if sort == "relevance":
            if q:
                matches.sort(key=lambda r: (_text_blob(r).count(q), (r.get("display_name") or "").lower()), reverse=(order == "desc"))
            else:
                matches.sort(key=lambda r: ((r.get("display_name") or "").lower(), r.get("id") or ""), reverse=(order == "desc"))
        elif sort == "display_name":
            matches.sort(key=lambda r: ((r.get("display_name") or "").lower(), r.get("id") or ""), reverse=(order == "desc"))
        elif sort == "updated_at":
            matches.sort(key=lambda r: (_dt_key(r.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or ""), reverse=(order == "desc"))
        elif sort == "last_activity_at":
            matches.sort(key=lambda r: (_dt_key(r.get("last_activity_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or ""), reverse=(order == "desc"))

        total = len(matches)
        page = matches[offset:offset + lim]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = ("off:%d" % next_offset) if has_more else None

        out.append({
            "companies": page,
            "meta": {"total": total, "limit": lim, "cursor": cur, "next_cursor": next_cursor, "has_more": has_more},
        })

    _log("ok")
    return {"results": out}

