def get_company_json(workspace_id, company_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Usage/audit log (observability). Create if missing.
    usage_file = "usage_logs.json"
    usage = _load(usage_file)
    if not isinstance(usage, list):
        usage = []

    def _log(status, endpoint="get-company-json", code=None, message=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(usage)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential_id": None,
            "status": status,
            "error_code": code,
            "error_message": message,
            "latency_ms": latency_ms,
            "created_at": now
        }
        usage.append(row)
        _save(usage_file, usage)

    def _enforce_limits():
        # Simple per-workspace rolling rate limit + daily quota, derived from usage logs.
        # Rate: 120 req/min; Quota: 5000 req/day.
        if not isinstance(workspace_id, str):
            return None  # validation will handle
        rate_limit = 120
        quota_limit = 5000
        try:
            now_dt = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
        except Exception:
            return None
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        per_min = 0
        per_day = 0
        for r in usage:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if ts_dt >= window_start:
                per_min += 1
            if ts_dt >= day_start:
                per_day += 1
        if per_min >= rate_limit:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=rate_limit, window_seconds=60)
        if per_day >= quota_limit:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=quota_limit, window="day")
        return None

    # Validate patterns
    if not isinstance(workspace_id, str) or not re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
        _log("error", code="VALIDATION_ERROR", message="Invalid workspace_id format.")
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    if not isinstance(company_id, str) or not re.match(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$", company_id):
        _log("error", code="VALIDATION_ERROR", message="Invalid company_id format.")
        return _err("VALIDATION_ERROR", "Invalid company_id format.")

    limerr = _enforce_limits()
    if limerr:
        _log("error", code=limerr["error"]["code"], message=limerr["error"]["message"])
        return limerr

    # Authenticate ambiently by ensuring the workspace exists and is accessible/active.
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        # If caller supplies a workspace_id, treat unknown as unauthorized scope.
        _log("error", code="UNAUTHORIZED", message="Workspace not accessible.")
        return _err("UNAUTHORIZED", "Workspace not accessible.")
    if ws.get("status") != "active":
        _log("error", code="UNAUTHORIZED", message="Workspace is not active.")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    records = _load("records.json")
    if not isinstance(records, list):
        records = []
    rec = next((r for r in records if isinstance(r, dict) and r.get("id") == company_id and r.get("workspace_id") == workspace_id), None)
    if rec is None or rec.get("record_type") != "company" or rec.get("status") != "active":
        _log("error", code="NOT_FOUND", message="Company not found.")
        return _err("NOT_FOUND", "Company not found.")
    raw = rec.get("raw_json")
    if not isinstance(raw, dict):
        _log("error", code="NOT_FOUND", message="raw_json not available for this company.")
        return _err("NOT_FOUND", "raw_json not available for this company.")

    _log("ok")
    return {
        "data": {
            "workspace_id": workspace_id,
            "company_id": company_id,
            "raw_json": raw
        }
    }

