def create_person(workspace_id, body, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(status_val, error_code=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": "create-person",
                "workspace_id": workspace_id,
                "credential_id": None,
                "status": status_val,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid_like(prefix):
        return prefix + "".join(random.choice(_CROCK) for _ in range(26))

    def _norm_email(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        e = v.strip().lower()
        if "@" not in e or e.startswith("@") or e.endswith("@"):
            return None
        return e

    def _norm_domain(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip().lower()
        s = re.sub(r"^\s*https?://", "", s)
        s = s.split("/")[0]
        s = s.split("?")[0]
        s = s.split("#")[0]
        if s.startswith("www."):
            s = s[4:]
        s = s.strip(".")
        if not s:
            return None
        if any(c.isspace() for c in s):
            return None
        if "." not in s:
            return None
        return s

    def _digits_only(p):
        return "".join(ch for ch in p if ch.isdigit())

    def _norm_phone(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        d = _digits_only(s)
        if not d:
            return None
        # Very lightweight E.164-ish normalization: if leading + provided and digits length 8..15 -> keep.
        if s.strip().startswith("+") and 8 <= len(d) <= 15:
            return "+" + d
        # If looks like US 10-digit, assume +1
        if len(d) == 10:
            return "+1" + d
        # If already 11-15 digits, prefix +
        if 8 <= len(d) <= 15:
            return "+" + d
        return d  # fallback digits-only

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")
        if not isinstance(body, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body must be an object.", field="body")

        allowed = {
            "display_name",
            "email",
            "phone",
            "domain",
            "social",
            "contact",
            "business",
            "attributes",
            "attio_object",
            "raw_json",
        }
        unknown = [k for k in body.keys() if k not in allowed]
        if unknown:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unknown fields in body.", unknown_fields=unknown)

        dn = body.get("display_name")
        if not isinstance(dn, str) or not dn.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.display_name is required.", field="body.display_name")

        social = body.get("social")
        contact = body.get("contact")
        business = body.get("business")
        attributes = body.get("attributes")
        raw_json = body.get("raw_json")

        for fld, val in (("social", social), ("contact", contact), ("business", business), ("attributes", attributes), ("raw_json", raw_json)):
            if val is not None and not isinstance(val, dict):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"body.{fld} must be an object.", field=f"body.{fld}")

        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws:
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No accessible workspace found for this request.")
        if ws.get("status") != "active":
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=ws.get("status"))

        email = body.get("email")
        phone = body.get("phone")
        domain = body.get("domain")

        norm_email = _norm_email(email) if email is not None else None
        if email is not None and norm_email is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid email format.", field="body.email")

        norm_domain = _norm_domain(domain) if domain is not None else None
        if domain is not None and norm_domain is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid domain format.", field="body.domain")

        norm_phone = _norm_phone(phone) if phone is not None else None
        if phone is not None and norm_phone is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid phone format.", field="body.phone")

        records = _load("records.json")

        attio_object = body.get("attio_object")
        if attio_object is None:
            attio_object = "people"
        if not isinstance(attio_object, str) or not attio_object.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "attio_object must be a non-empty string.", field="body.attio_object")

        # Generate unique local id and an opaque upstream id placeholder.
        for _ in range(50):
            new_id = _ulid_like("att_rec_")
            if not any(r.get("id") == new_id for r in records):
                break
        else:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Could not generate unique record id.")

        for _ in range(50):
            attio_record_id = _ulid_like("attio_rec_")
            if not any(
                r.get("workspace_id") == workspace_id
                and r.get("attio_object") == attio_object
                and r.get("attio_record_id") == attio_record_id
                for r in records
            ):
                break
        else:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Could not generate unique upstream record id.")

        now = _now()
        rec = {
            "id": new_id,
            "workspace_id": workspace_id,
            "record_type": "person",
            "attio_object": attio_object,
            "attio_record_id": attio_record_id,
            "status": "active",
            "display_name": dn.strip(),
            "domain": None,  # persons keep domain nullable per constraints; store associated domain in attributes/raw_json instead
            "email": norm_email,
            "phone": norm_phone,
            "social": social if social is not None else None,
            "contact": contact if contact is not None else None,
            "business": business if business is not None else None,
            "attributes": attributes if attributes is not None else {},
            "raw_json": raw_json if raw_json is not None else {},
            "last_interaction_at": None,
            "last_activity_at": None,
            "attio_created_at": None,
            "attio_updated_at": None,
            "created_at": now,
            "updated_at": now,
        }

        # Optional: if caller provided domain for person, tuck into attributes without violating column constraint.
        if norm_domain is not None:
            if not isinstance(rec["attributes"], dict):
                rec["attributes"] = {}
            rec["attributes"].setdefault("company_domain", norm_domain)

        records.append(rec)
        _save("records.json", records)

        _log("ok")
        return {"data": rec}
    except Exception as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

