def search_people(workspace_id, query=None, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(status_val, error_code=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": "search-people",
                "workspace_id": workspace_id,
                "credential_id": None,
                "status": status_val,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be RFC3339 date-time string.", field=field)
        try:
            # handle trailing Z
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"Invalid date-time for {field}.", field=field)

    def _norm_email(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        e = v.strip().lower()
        if "@" not in e or e.startswith("@") or e.endswith("@"):
            return None
        return e

    def _norm_domain(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip().lower()
        s = re.sub(r"^\s*https?://", "", s)
        s = s.split("/")[0]
        s = s.split("?")[0]
        s = s.split("#")[0]
        if s.startswith("www."):
            s = s[4:]
        s = s.strip(".")
        if not s or any(c.isspace() for c in s) or "." not in s:
            return None
        return s

    def _dt_of_row(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        try:
            ss = v
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _cursor_decode(c):
        if c is None:
            return 0, None
        if not isinstance(c, str) or not c:
            return None, _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    def _cursor_encode(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")

        if query is not None and not isinstance(query, str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "query must be a string.", field="query")

        if filters is not None and not isinstance(filters, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "filters must be an object.", field="filters")

        if sort is not None and not isinstance(sort, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort must be an object.", field="sort")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")

        offset, cerr = _cursor_decode(cursor)
        if cerr:
            _log("error", cerr["error"]["code"])
            return cerr

        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws:
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No accessible workspace found for this request.")
        if ws.get("status") != "active":
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=ws.get("status"))

        f_status = None
        f_email = None
        f_domain = None
        lia = lib = laa = lab = None
        f_attrs = None

        if filters:
            allowed_f = {
                "status",
                "email",
                "domain",
                "last_interaction_after",
                "last_interaction_before",
                "last_activity_after",
                "last_activity_before",
                "attributes",
            }
            unknown = [k for k in filters.keys() if k not in allowed_f]
            if unknown:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unknown filters fields.", unknown_fields=unknown)

            if "status" in filters:
                f_status = filters.get("status")
                if f_status not in ("active", "archived", "deleted"):
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Invalid status filter.", field="filters.status")

            if "email" in filters:
                f_email = _norm_email(filters.get("email"))
                if filters.get("email") is not None and f_email is None:
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Invalid email filter.", field="filters.email")

            if "domain" in filters:
                f_domain = _norm_domain(filters.get("domain"))
                if filters.get("domain") is not None and f_domain is None:
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Invalid domain filter.", field="filters.domain")

            lia, err = _parse_dt(filters.get("last_interaction_after"), "filters.last_interaction_after")
            if err:
                _log("error", err["error"]["code"])
                return err
            lib, err = _parse_dt(filters.get("last_interaction_before"), "filters.last_interaction_before")
            if err:
                _log("error", err["error"]["code"])
                return err
            laa, err = _parse_dt(filters.get("last_activity_after"), "filters.last_activity_after")
            if err:
                _log("error", err["error"]["code"])
                return err
            lab, err = _parse_dt(filters.get("last_activity_before"), "filters.last_activity_before")
            if err:
                _log("error", err["error"]["code"])
                return err

            if "attributes" in filters:
                f_attrs = filters.get("attributes")
                if f_attrs is not None and not isinstance(f_attrs, dict):
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "filters.attributes must be an object.", field="filters.attributes")

        # Sort validation/default
        sort_field = "updated_at"
        sort_dir = "desc"
        if sort is not None:
            req = set(sort.keys())
            if req != {"field", "direction"}:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sort must include exactly field and direction.", field="sort")
            sort_field = sort.get("field")
            sort_dir = sort.get("direction")
            if sort_field not in (
                "display_name",
                "last_interaction_at",
                "last_activity_at",
                "attio_updated_at",
                "created_at",
                "updated_at",
            ):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid sort.field.", field="sort.field")
            if sort_dir not in ("asc", "desc"):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid sort.direction.", field="sort.direction")

        records = _load("records.json")
        q = (query or "").strip().lower()

        # Business rule default: only active unless explicitly requesting otherwise
        if f_status is None:
            f_status = "active"

        def _matches_text(r):
            if not q:
                return True
            hay = []
            dn = r.get("display_name") or ""
            hay.append(dn)
            em = r.get("email") or ""
            hay.append(em)
            # include some attributes/raw_json text
            attrs = r.get("attributes")
            if isinstance(attrs, dict):
                for k, v in attrs.items():
                    if isinstance(v, (str, int, float, bool)):
                        hay.append(f"{k}:{v}")
            raw = r.get("raw_json")
            if isinstance(raw, dict):
                # shallow
                for k, v in list(raw.items())[:50]:
                    if isinstance(v, (str, int, float, bool)):
                        hay.append(f"{k}:{v}")
            blob = " ".join(str(x) for x in hay).lower()
            return q in blob

        def _attrs_match(r):
            if not f_attrs:
                return True
            attrs = r.get("attributes")
            if not isinstance(attrs, dict):
                return False
            # invalid attribute keys yield error: key must exist in attributes dict
            for k, v in f_attrs.items():
                if k not in attrs:
                    return None  # signal invalid key
                if attrs.get(k) != v:
                    return False
            return True

        out = []
        invalid_attr_key = None

        for r in records:
            if r.get("workspace_id") != workspace_id:
                continue
            if r.get("record_type") != "person":
                continue
            if r.get("status") != f_status:
                continue

            if f_email is not None and (r.get("email") or "").lower() != f_email:
                continue

            # domain for person may be stored in attributes.company_domain (per create-person behavior)
            if f_domain is not None:
                ad = None
                attrs = r.get("attributes")
                if isinstance(attrs, dict):
                    ad = attrs.get("company_domain")
                if (ad or "").lower() != f_domain:
                    continue

            li = _dt_of_row(r.get("last_interaction_at"))
            if lia and (li is None or li <= lia):
                continue
            if lib and (li is None or li >= lib):
                continue

            la = _dt_of_row(r.get("last_activity_at"))
            if laa and (la is None or la <= laa):
                continue
            if lab and (la is None or la >= lab):
                continue

            if not _matches_text(r):
                continue

            am = _attrs_match(r)
            if am is None:
                invalid_attr_key = True
                break
            if not am:
                continue

            out.append(r)

        if invalid_attr_key:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid attribute key in filters.attributes (key not present on record).", field="filters.attributes")

        def _sort_key(r):
            if sort_field == "display_name":
                return (r.get("display_name") or "").lower()
            if sort_field in ("last_interaction_at", "last_activity_at", "attio_updated_at", "created_at", "updated_at"):
                dt = _dt_of_row(r.get(sort_field))
                return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (r.get("updated_at") or "")

        reverse = sort_dir == "desc"
        out.sort(key=_sort_key, reverse=reverse)

        total = len(out)
        page = out[offset : offset + limit]
        next_off = offset + len(page)
        has_more = next_off < total
        next_cursor = _cursor_encode(next_off) if has_more else None

        _log("ok")
        return {
            "data": page,
            "meta": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
            },
        }
    except Exception as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

