def advanced_search_people(workspace_id, query=None, filters=None, limit=None, cursor=None, sort=None, sort_direction=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "advanced-search-people"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field_name):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Accept trailing 'Z'
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _get_field(obj, path):
        cur = obj
        for p in path:
            if isinstance(cur, dict) and p in cur:
                cur = cur[p]
            else:
                return None
        return cur

    def _flatten_text(v, max_len=20000):
        # Deterministic textual representation for matching.
        if v is None:
            return ""
        if isinstance(v, (str, int, float, bool)):
            return str(v)
        if isinstance(v, list):
            parts = []
            for it in v:
                parts.append(_flatten_text(it))
                if sum(len(x) for x in parts) > max_len:
                    break
            return " ".join(parts)
        if isinstance(v, dict):
            parts = []
            for k in sorted(v.keys()):
                parts.append(str(k))
                parts.append(_flatten_text(v[k]))
                if sum(len(x) for x in parts) > max_len:
                    break
            return " ".join(parts)
        return str(v)

    def _normalize_email(s):
        if not isinstance(s, str):
            return None
        e = s.strip().lower()
        if "@" not in e or e.startswith("@") or e.endswith("@"):
            return None
        return e

    def _normalize_domain(s):
        if not isinstance(s, str):
            return None
        x = s.strip().lower()
        x = re.sub(r"^\s*https?://", "", x)
        x = x.split("/")[0].split("?")[0].split("#")[0]
        if x.startswith("www."):
            x = x[4:]
        x = x.strip(".")
        if not x:
            return None
        # Disallow spaces
        if re.search(r"\s", x):
            return None
        return x

    def _digits_only(s):
        return "".join(ch for ch in s if ch.isdigit()) if isinstance(s, str) else ""

    def _normalize_phone(s):
        if not isinstance(s, str):
            return (None, None)
        raw = s.strip()
        d = _digits_only(raw)
        # Basic normalization: accept + and digits; if starts with + -> E.164-ish
        if raw.startswith("+") and d:
            return ("+" + d, d)
        # If 10-15 digits, consider it normalized without plus? We'll keep digits-only fallback.
        if 10 <= len(d) <= 15:
            return (None, d)
        if d:
            return (None, d)
        return (None, None)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if obj.get("v") != 1 or obj.get("ep") != endpoint:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(offset):
        payload = {"v": 1, "ep": endpoint, "offset": offset}
        b = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    def _log(status, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256((endpoint + "|" + _iso_now() + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _iso_now(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        # If no usage schema exists, do nothing. If it exists, enforce generic limits.
        usage = _load("usage.json")
        if not isinstance(usage, list) or len(usage) == 0:
            return None
        # Find any applicable row; tolerate different shapes.
        now = datetime.datetime.now(datetime.timezone.utc)
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        # Rate limit: 120/min default, quota: 10000/day default; can be overridden in usage row.
        row = usage[0] if isinstance(usage[0], dict) else {}
        rate = row.get("rate_limit_per_minute", 120)
        quota = row.get("quota_per_day", 10000)
        try:
            rate = int(rate)
        except Exception:
            rate = 120
        try:
            quota = int(quota)
        except Exception:
            quota = 10000
        recent = 0
        daily = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            dt = _parse_dt(ts, "timestamp")
            if dt is None:
                continue
            if dt >= minute_ago:
                recent += 1
            if dt >= day_ago:
                daily += 1
        if rate >= 0 and recent >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if quota >= 0 and daily >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    # Validate workspace_id
    if not isinstance(workspace_id, str) or not re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
        _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    if query is not None and not isinstance(query, str):
        _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "query must be a string.")
    if filters is not None and not isinstance(filters, dict):
        _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "filters must be an object.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if sort is None:
        sort = "relevance"
    if sort not in {"relevance", "created_at", "updated_at", "last_interaction_at", "last_activity_at", "display_name"}:
        _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if sort_direction is None:
        sort_direction = "desc"
    if sort_direction not in {"asc", "desc"}:
        _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort_direction.")
    off = _decode_cursor(cursor)
    if off is None:
        _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    rl = _enforce_limits()
    if rl is not None:
        _log("error", (time.time() - t0) * 1000, {"code": rl["error"]["code"]})
        return rl

    # Resolve workspace; ambient auth but still ensure workspace exists & is active
    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces if isinstance(workspaces, list) else []:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if ws is None:
        _log("error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # Validate filters content
    status_filter = "active"
    dt_filters = {}
    email_f = domain_f = phone_f = None
    attrs_filter = None
    attio_object_f = None

    if filters:
        if "status" in filters:
            if filters["status"] not in {"active", "archived", "deleted"}:
                _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "filters.status must be one of active, archived, deleted.")
            status_filter = filters["status"]
        for k in ["created_at", "updated_at", "last_interaction_at", "last_activity_at"]:
            if k in filters:
                v = filters[k]
                if not isinstance(v, dict):
                    _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", f"filters.{k} must be an object.")
                gte = v.get("gte")
                lte = v.get("lte")
                if gte is not None:
                    dt = _parse_dt(gte, f"filters.{k}.gte")
                    if dt is None:
                        _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
                        return _err("VALIDATION_ERROR", f"Malformed date-time for filters.{k}.gte.")
                    dt_filters.setdefault(k, {})["gte"] = dt
                if lte is not None:
                    dt = _parse_dt(lte, f"filters.{k}.lte")
                    if dt is None:
                        _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
                        return _err("VALIDATION_ERROR", f"Malformed date-time for filters.{k}.lte.")
                    dt_filters.setdefault(k, {})["lte"] = dt
                if k in dt_filters and "gte" in dt_filters[k] and "lte" in dt_filters[k]:
                    if dt_filters[k]["gte"] > dt_filters[k]["lte"]:
                        _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
                        return _err("VALIDATION_ERROR", f"Invalid range for filters.{k}: gte must be <= lte.")
        if "email" in filters:
