            if email_f is None:
                _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "filters.email must be a valid email.")
        if "domain" in filters:
            if not isinstance(filters["domain"], str):
                _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "filters.domain must be a string.")
            domain_f = _normalize_domain(filters["domain"])
            if domain_f is None:
                _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "filters.domain must be a valid domain/host.")
        if "phone" in filters:
            if not isinstance(filters["phone"], str):
                _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "filters.phone must be a string.")
