            if not isinstance(filters["attio_object"], str):
                _log("error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "filters.attio_object must be a string.")
            attio_object_f = filters["attio_object"]

    records = _load("records.json")
    if not isinstance(records, list):
        records = []

    q = (query or "").strip().lower()
    q_terms = [t for t in re.split(r"\s+", q) if t] if q else []

    def _dt_from_row(row, field):
        v = row.get(field)
        if v is None:
            return None
        if isinstance(v, str):
            return _parse_dt(v, field)
        return None

    def _attrs_has_all(row_attrs, wanted):
        if wanted is None:
            return True
        if not isinstance(row_attrs, dict):
            return False
        # Exact-key matching: each key must exist and equal (deep-equal)
        for k, v in wanted.items():
            if k not in row_attrs:
                return False
            if row_attrs[k] != v:
                return False
        return True

    def _matches_text(row):
        if not q_terms:
            return (True, 0)
        hay = []
        if row.get("display_name"):
            hay.append(str(row.get("display_name")))
        if row.get("email"):
            hay.append(str(row.get("email")))
        if row.get("phone"):
            hay.append(str(row.get("phone")))
        attrs = row.get("attributes") if isinstance(row.get("attributes"), dict) else {}
        raw = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else {}
        # selected fields: attributes + raw_json flattened (bounded)
        hay.append(_flatten_text(attrs))
        hay.append(_flatten_text(raw))
        text = (" ".join(hay)).lower()
        # require all terms present
        for t in q_terms:
            if t not in text:
                return (False, 0)
        # relevance score: count term occurrences
        score = 0
        for t in q_terms:
            score += text.count(t)
        return (True, score)

    matched = []
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("record_type") != "person":
            continue

        # default status is active unless explicitly filtered
        if status_filter:
            if r.get("status") != status_filter:
                continue

        if attio_object_f is not None and r.get("attio_object") != attio_object_f:
            continue

        if email_f is not None:
            if (r.get("email") or "").lower() != email_f:
                continue
        if domain_f is not None:
            # People generally have null domain, but filter allows it (exact match)
            if (r.get("domain") or "").lower() != domain_f:
                continue
        if phone_f is not None:
            row_phone = r.get("phone")
            if isinstance(row_phone, str) and phone_f["norm"] is not None:
                if row_phone != phone_f["norm"]:
                    continue
            else:
                if _digits_only(row_phone or "") != phone_f["digits"]:
                    continue

        # datetime filters
        ok_dt = True
        for fld, rng in dt_filters.items():
            dtv = _dt_from_row(r, fld)
            if dtv is None:
                ok_dt = False
                break
            if "gte" in rng and dtv < rng["gte"]:
                ok_dt = False
                break
            if "lte" in rng and dtv > rng["lte"]:
                ok_dt = False
                break
        if not ok_dt:
            continue

        if attrs_filter is not None:
            if not _attrs_has_all(r.get("attributes"), attrs_filter):
                continue

        ok_text, score = _matches_text(r)
        if not ok_text:
            continue

        matched.append((r, score))

    # sort
    rev = (sort_direction == "desc")
    def _sort_key(item):
        r, score = item
        if sort == "relevance":
            # Higher score first; tie-break by updated_at desc then id
            udt = _dt_from_row(r, "updated_at") or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (score, udt.timestamp(), r.get("id") or "")
        if sort in {"created_at", "updated_at", "last_interaction_at", "last_activity_at"}:
            dtv = _dt_from_row(r, sort)
            ts = dtv.timestamp() if dtv else float("-inf")
            return (ts, r.get("id") or "")
        if sort == "display_name":
            return ((r.get("display_name") or "").lower(), r.get("id") or "")
        return (r.get("id") or "",)

    if sort == "relevance":
        matched.sort(key=_sort_key, reverse=True)  # relevance always desc-ish
        if sort_direction == "asc":
            matched.reverse()
    else:
        matched.sort(key=_sort_key, reverse=rev)

    total = len(matched)
    start = off
    end = min(start + limit, total)
    page = [matched[i][0] for i in range(start, end)]
    has_more = end < total
    next_cursor = _encode_cursor(end) if has_more else None

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "sort_direction": sort_direction
        }
    }
    _log("ok", (time.time() - t0) * 1000, {"returned": len(page), "total": total})
    return resp

