        return _err("VALIDATION_ERROR", "sort_direction must be one of: asc, desc", field="sort_direction")

    mf = _parse_dt(modified_from, "modified_from")
    if isinstance(mf, tuple) and mf and mf[0] == "__err__":
        _log("VALIDATION_ERROR", resolved_workspace_id=workspace_id)
        return mf[1]
    mt = _parse_dt(modified_to, "modified_to")
    if isinstance(mt, tuple) and mt and mt[0] == "__err__":
        _log("VALIDATION_ERROR", resolved_workspace_id=workspace_id)
        return mt[1]
    if mf is not None and mt is not None and mf > mt:
        _log("VALIDATION_ERROR", resolved_workspace_id=workspace_id)
        return _err("VALIDATION_ERROR", "modified_from must be <= modified_to", field="modified_from")

    # Decode cursor
    start = 0
    cursor_payload = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cursor_payload = json.loads(raw.decode("utf-8"))
            if not isinstance(cursor_payload, dict) or cursor_payload.get("v") != 1 or cursor_payload.get("endpoint") != endpoint:
                _log("VALIDATION_ERROR", resolved_workspace_id=workspace_id)
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            if cursor_payload.get("workspace_id") != workspace_id:
                _log("VALIDATION_ERROR", resolved_workspace_id=workspace_id)
