        # updated_at
        dt = _dt_from_row(r.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, r.get("id") or "")

    reverse = (sort_direction == "desc")
    try:
        filtered.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # if unexpected bad data types break sort, return validation-ish error rather than crash
        _log("VALIDATION_ERROR", resolved_workspace_id=workspace_id)
        return _err("VALIDATION_ERROR", "Unable to sort results due to invalid stored data", field="sort")

    total = len(filtered)
    page = filtered[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {
            "v": 1,
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "sort": sort,
            "dir": sort_direction,
            "offset": next_offset
        }
