def search_people_by_activity(workspace_id, activity_type=None, activity_status=None, activity_from=None, activity_to=None, status=None, limit=None, cursor=None, sort=None, sort_direction=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v, field):
        if v is None:
            return None, None
        if not isinstance(v, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string")
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string")

    def _is_ulid(pref, v):
        if not isinstance(v, str):
            return False
        return re.match(r"^" + re.escape(pref) + r"[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    def _cursor_encode(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _cursor_decode(cur):
        if cur is None:
            return None, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        s = cur.strip()
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            return obj, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _log(endpoint, status, workspace_row_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now_iso()}|{time.time()}".encode("utf-8")).hexdigest()[:26],
            "endpoint": endpoint,
            "workspace_id": workspace_row_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, workspace_row_id):
        # Best-effort: enforce if request_logs.json exists and contains limit config rows.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None

        cfg = None
        for r in logs:
            if isinstance(r, dict) and r.get("type") == "rate_limit" and r.get("workspace_id") == workspace_row_id and r.get("endpoint") == endpoint:
                cfg = r
                break
        if cfg is None:
            for r in logs:
                if isinstance(r, dict) and r.get("type") == "rate_limit" and r.get("workspace_id") == workspace_row_id and r.get("endpoint") in (None, "*"):
                    cfg = r
                    break

        if cfg:
            window_s = cfg.get("window_seconds", 60)
            max_req = cfg.get("max_requests", 60)
            try:
                window_s = int(window_s)
                max_req = int(max_req)
            except Exception:
                return None
            if window_s > 0 and max_req >= 0:
                now = datetime.datetime.now(datetime.timezone.utc)
                cutoff = now - datetime.timedelta(seconds=window_s)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("workspace_id") != workspace_row_id:
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    ts = _dt_from_row(r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= max_req:
                    return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=window_s)

        qcfg = None
        for r in logs:
            if isinstance(r, dict) and r.get("type") == "quota" and r.get("workspace_id") == workspace_row_id and r.get("endpoint") == endpoint:
                qcfg = r
                break
        if qcfg is None:
            for r in logs:
                if isinstance(r, dict) and r.get("type") == "quota" and r.get("workspace_id") == workspace_row_id and r.get("endpoint") in (None, "*"):
                    qcfg = r
                    break
        if qcfg:
            period = qcfg.get("period", "day")  # day|month
            max_calls = qcfg.get("max_calls", None)
            try:
                max_calls = int(max_calls)
            except Exception:
                max_calls = None
            if max_calls is not None and max_calls >= 0:
                now = datetime.datetime.now(datetime.timezone.utc)
                if period == "month":
                    start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
                else:
                    start = now.replace(hour=0, minute=0, second=0, microsecond=0)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("workspace_id") != workspace_row_id:
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    ts = _dt_from_row(r.get("created_at"))
                    if ts and ts >= start:
                        cnt += 1
                if cnt >= max_calls:
                    return _err("QUOTA_EXCEEDED", "Quota exceeded", period=period)
        return None

    endpoint = "search-people-by-activity"

    # Validate inputs
    if not _is_ulid("att_ws_", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match ^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    if activity_type is not None and activity_type not in ("note", "task"):
        return _err("VALIDATION_ERROR", "activity_type must be one of: note, task")
    if activity_status is not None and activity_status not in ("active", "completed", "deleted"):
        return _err("VALIDATION_ERROR", "activity_status must be one of: active, completed, deleted")
    if status is not None and status not in ("active", "archived", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if sort is None:
        sort = "last_activity_at"
    if sort not in ("last_activity_at", "last_interaction_at", "updated_at", "display_name"):
        return _err("VALIDATION_ERROR", "sort must be one of: last_activity_at, last_interaction_at, updated_at, display_name")
    if sort_direction is None:
        sort_direction = "desc"
    if sort_direction not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_direction must be one of: asc, desc")

    dt_from, e = _parse_dt(activity_from, "activity_from")
    if e:
        return e
    dt_to, e = _parse_dt(activity_to, "activity_to")
    if e:
        return e
    if dt_from and dt_to and dt_from > dt_to:
        return _err("VALIDATION_ERROR", "activity_from must be <= activity_to")

    cur_obj, e = _cursor_decode(cursor)
    if e:
        return e

    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if not ws:
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        # Treat disabled/deleting as unauthorized to serve operations
        return _err("UNAUTHORIZED", "Workspace is not active")

    limerr = _enforce_limits(endpoint, workspace_id)
    if limerr:
        _log(endpoint, "error", workspace_id, limerr["error"]["code"])
        return limerr

    records = _load("records.json")
    acts = _load("notes_tasks.json")

    # Build activity indexes
    relevant_acts = []
    for a in acts:
        if not isinstance(a, dict):
            continue
        if a.get("workspace_id") != workspace_id:
            continue
        if activity_type is not None and a.get("activity_type") != activity_type:
            continue
        if activity_status is not None and a.get("status") != activity_status:
            continue

        # Use updated_at as "activity time" proxy; tasks may have completed_at; prefer completed_at when filtering completed.
        at = None
        if a.get("status") == "completed":
            at = _dt_from_row(a.get("completed_at")) or _dt_from_row(a.get("updated_at")) or _dt_from_row(a.get("created_at"))
        else:
            at = _dt_from_row(a.get("updated_at")) or _dt_from_row(a.get("created_at"))
        if dt_from and (at is None or at < dt_from):
            continue
        if dt_to and (at is None or at > dt_to):
            continue

        relevant_acts.append((a, at))

    # Determine people linked by those activities
    linked_people_ids = set()
    if relevant_acts:
        for a, _at in relevant_acts:
            l = a.get("linked_record_ids")
            if isinstance(l, list):
                for rid in l:
                    if isinstance(rid, str):
                        linked_people_ids.add(rid)

    # If no relevant activities, result is empty (not error)
    # Filter person records
    people = []
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("record_type") != "person":
            continue
        if status is None:
            if r.get("status") != "active":
                continue
        else:
            if r.get("status") != status:
                continue
        if linked_people_ids:
            if r.get("id") not in linked_people_ids:
                continue
        else:
            continue

        people.append(r)

    # Sorting
    def _key(r):
        if sort == "display_name":
            v = r.get("display_name")
            return (v is None, (v or "").casefold(), r.get("id") or "")
        dt = _dt_from_row(r.get(sort))
        # None sorts last for desc by using minimal/max sentinel in tuple
        if dt is None:
            return (1, datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or "")
        return (0, dt, r.get("id") or "")

    reverse = (sort_direction == "desc")
    people.sort(key=_key, reverse=reverse)

    # Pagination via cursor offset
    offset = 0
    if cur_obj:
        if cur_obj.get("endpoint") != endpoint or cur_obj.get("workspace_id") != workspace_id:
            _log(endpoint, "error", workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor does not match this request context")
        try:
            offset = int(cur_obj.get("offset", 0))
        except Exception:
            _log(endpoint, "error", workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if offset < 0:
            _log(endpoint, "error", workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    total = len(people)
    page = people[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _cursor_encode({"endpoint": endpoint, "workspace_id": workspace_id, "offset": next_offset}) if has_more else None

    # Response projection: return person basics + relevant denormalized fields
    items = []
    for r in page:
        items.append({
            "id": r.get("id"),
            "attio_record_id": r.get("attio_record_id"),
            "display_name": r.get("display_name"),
            "email": r.get("email"),
            "phone": r.get("phone"),
            "status": r.get("status"),
            "last_activity_at": r.get("last_activity_at"),
            "last_interaction_at": r.get("last_interaction_at"),
            "updated_at": r.get("updated_at"),
        })

    resp = {
        "data": items,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "sort_direction": sort_direction,
        }
    }
    _log(endpoint, "ok", workspace_id, None)
    return resp

def get_person_notes(workspace_id, person_record_id, status=None, limit=None, cursor=None, sort=None, sort_direction=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_ulid(pref, v):
        if not isinstance(v, str):
            return False
        return re.match(r"^" + re.escape(pref) + r"[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    def _cursor_encode(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        import base64
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _cursor_decode(cur):
        if cur is None:
            return None, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        s = cur.strip()
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        import base64
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            return obj, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _log(endpoint, status_s, workspace_row_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now_iso()}|{time.time()}".encode("utf-8")).hexdigest()[:26],
            "endpoint": endpoint,
            "workspace_id": workspace_row_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, workspace_row_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None

        cfg = None
        for r in logs:
            if isinstance(r, dict) and r.get("type") == "rate_limit" and r.get("workspace_id") == workspace_row_id and r.get("endpoint") == endpoint:
                cfg = r
                break
        if cfg is None:
            for r in logs:
                if isinstance(r, dict) and r.get("type") == "rate_limit" and r.get("workspace_id") == workspace_row_id and r.get("endpoint") in (None, "*"):
                    cfg = r
                    break
        if cfg:
            window_s = cfg.get("window_seconds", 60)
            max_req = cfg.get("max_requests", 60)
            try:
                window_s = int(window_s)
                max_req = int(max_req)
            except Exception:
                return None
            if window_s > 0 and max_req >= 0:
                now = datetime.datetime.now(datetime.timezone.utc)
                cutoff = now - datetime.timedelta(seconds=window_s)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("workspace_id") != workspace_row_id:
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    ts = _dt_from_row(r.get("created_at"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt >= max_req:
                    return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=window_s)

        qcfg = None
        for r in logs:
            if isinstance(r, dict) and r.get("type") == "quota" and r.get("workspace_id") == workspace_row_id and r.get("endpoint") == endpoint:
                qcfg = r
                break
        if qcfg is None:
            for r in logs:
                if isinstance(r, dict) and r.get("type") == "quota" and r.get("workspace_id") == workspace_row_id and r.get("endpoint") in (None, "*"):
                    qcfg = r
                    break
        if qcfg:
            period = qcfg.get("period", "day")
            max_calls = qcfg.get("max_calls", None)
            try:
                max_calls = int(max_calls)
            except Exception:
                max_calls = None
            if max_calls is not None and max_calls >= 0:
                now = datetime.datetime.now(datetime.timezone.utc)
                if period == "month":
                    start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
                else:
                    start = now.replace(hour=0, minute=0, second=0, microsecond=0)
                cnt = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("workspace_id") != workspace_row_id:
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    ts = _dt_from_row(r.get("created_at"))
                    if ts and ts >= start:
                        cnt += 1
                if cnt >= max_calls:
                    return _err("QUOTA_EXCEEDED", "Quota exceeded", period=period)
        return None

    endpoint = "get-person-notes"

    # Validate
    if not _is_ulid("att_ws_", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match ^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    if not _is_ulid("att_rec_", person_record_id):
        return _err("VALIDATION_ERROR", "person_record_id must match ^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")
    if status is not None and status not in ("active", "completed", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, completed, deleted")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at"):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at")
    if sort_direction is None:
        sort_direction = "desc"
    if sort_direction not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_direction must be one of: asc, desc")

    cur_obj, e = _cursor_decode(cursor)
    if e:
        return e

    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if not ws:
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active")

    limerr = _enforce_limits(endpoint, workspace_id)
    if limerr:
        _log(endpoint, "error", workspace_id, limerr["error"]["code"])
        return limerr

    records = _load("records.json")
    person = None
    for r in records:
        if isinstance(r, dict) and r.get("id") == person_record_id:
            person = r
            break
    if not person or person.get("workspace_id") != workspace_id:
        _log(endpoint, "error", workspace_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Person record not found")
    if person.get("record_type") != "person":
        _log(endpoint, "error", workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "person_record_id must refer to a person record")

    notes_tasks = _load("notes_tasks.json")

    # Filter notes linked to person
    notes = []
