        if a.get("activity_type") != "note":
            continue
        l = a.get("linked_record_ids")
        if not isinstance(l, list) or person_record_id not in l:
            continue
        if status is not None:
            if a.get("status") != status:
                continue
        else:
            # Default: only non-deleted notes
            if a.get("status") == "deleted":
                continue
        notes.append(a)

    # Sort
    reverse = (sort_direction == "desc")

    def _key(a):
        dt = _dt_from_row(a.get(sort))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, a.get("id") or "")

    notes.sort(key=_key, reverse=reverse)

    # Pagination
    offset = 0
    if cur_obj:
        if cur_obj.get("endpoint") != endpoint or cur_obj.get("workspace_id") != workspace_id or cur_obj.get("person_record_id") != person_record_id:
            _log(endpoint, "error", workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor does not match this request context")
        try:
            offset = int(cur_obj.get("offset", 0))
        except Exception:
            _log(endpoint, "error", workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")
