    next_cursor = _cursor_encode({"endpoint": endpoint, "workspace_id": workspace_id, "person_record_id": person_record_id, "offset": next_offset}) if has_more else None

    # Project notes
    items = []
    for a in page:
        items.append({
            "id": a.get("id"),
            "attio_activity_id": a.get("attio_activity_id"),
            "status": a.get("status"),
