def create_person_note(workspace_id, person_record_id, body, title=None, author_record_id=None, metadata=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-person-note"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_request_log(status, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _new_activity_id(existing_ids):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        for _ in range(50):
            nid = "att_act_" + "".join(alphabet[random.randrange(len(alphabet))] for _ in range(26))
            if nid not in existing_ids:
                return nid
        return "att_act_" + "".join(alphabet[0] for _ in range(26))

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    rec_re = re.compile(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _append_request_log("VALIDATION_ERROR", {"field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(person_record_id, str) or not rec_re.fullmatch(person_record_id):
        _append_request_log("VALIDATION_ERROR", {"field": "person_record_id"})
        return _err("VALIDATION_ERROR", "person_record_id is invalid", field="person_record_id")
    if not isinstance(body, str) or len(body) < 1:
        _append_request_log("VALIDATION_ERROR", {"field": "body"})
        return _err("VALIDATION_ERROR", "body must be a non-empty string", field="body")
    if title is not None and not isinstance(title, str):
        _append_request_log("VALIDATION_ERROR", {"field": "title"})
        return _err("VALIDATION_ERROR", "title must be a string when provided", field="title")
    if author_record_id is not None and (not isinstance(author_record_id, str) or not rec_re.fullmatch(author_record_id)):
        _append_request_log("VALIDATION_ERROR", {"field": "author_record_id"})
        return _err("VALIDATION_ERROR", "author_record_id is invalid", field="author_record_id")
    if metadata is not None and not isinstance(metadata, dict):
        _append_request_log("VALIDATION_ERROR", {"field": "metadata"})
        return _err("VALIDATION_ERROR", "metadata must be an object when provided", field="metadata")

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _append_request_log("NOT_FOUND", {"workspace_id": workspace_id})
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    records = _load("records.json")
    if isinstance(records, dict) and "rows" in records:
        records = records.get("rows")
    if not isinstance(records, list):
        records = []

    person = next((r for r in records if isinstance(r, dict)
                   and r.get("id") == person_record_id
                   and r.get("workspace_id") == workspace_id
                   and r.get("record_type") == "person"), None)
    if not person:
        _append_request_log("NOT_FOUND", {"person_record_id": person_record_id})
        return _err("NOT_FOUND", "Person record not found", person_record_id=person_record_id)

    if author_record_id is not None:
        author = next((r for r in records if isinstance(r, dict)
                       and r.get("id") == author_record_id
                       and r.get("workspace_id") == workspace_id), None)
        if not author:
            _append_request_log("NOT_FOUND", {"author_record_id": author_record_id})
            return _err("NOT_FOUND", "Author record not found", author_record_id=author_record_id)

    notes_tasks = _load("notes_tasks.json")
    if isinstance(notes_tasks, dict) and "rows" in notes_tasks:
        notes_tasks = notes_tasks.get("rows")
    if not isinstance(notes_tasks, list):
        notes_tasks = []

    existing_ids = set()
    for a in notes_tasks:
        if isinstance(a, dict) and isinstance(a.get("id"), str):
            existing_ids.add(a["id"])

    now = _now_iso()
    new_row = {
        "id": _new_activity_id(existing_ids),
        "workspace_id": workspace_id,
        "activity_type": "note",
        "attio_activity_id": None,
        "status": "active",
        "author_record_id": author_record_id,
        "title": title,
        "body": body,
        "due_at": None,
        "completed_at": None,
        "linked_record_ids": [person_record_id],
        "metadata": metadata if isinstance(metadata, dict) else {},
        "created_at": now,
        "updated_at": now
    }

    notes_tasks.append(new_row)
    _save("notes_tasks.json", notes_tasks)

    _append_request_log("OK", {"note_id": new_row["id"], "linked_record_id": person_record_id})
    return {"data": new_row}

def search_people_by_company(workspace_id, company_query, person_query=None, limit=None, cursor=None, sort=None, sort_direction=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    _WS_RE = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")

    def _new_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        v = ms
        chars = []
        for _ in range(10):
            v, r = divmod(v, 32)
            chars.append(alphabet[r])
        chars = chars[::-1]
        rand = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{''.join(chars)}{rand}"

    def _log(endpoint, status, workspace_id=None, detail=None, latency_ms=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _new_id("att_log"),
                "endpoint": endpoint,
                "status": status,
                "workspace_id": workspace_id,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _normalize_domain(x):
        if not isinstance(x, str):
            return None
        s = x.strip().lower()
        if s == "":
            return None
        # strip scheme
        if "://" in s:
            s = s.split("://", 1)[1]
        # strip path/query
        s = s.split("/", 1)[0].split("?", 1)[0].split("#", 1)[0]
        if s.startswith("www."):
            s = s[4:]
        # strip port
        s = s.split(":", 1)[0]
        return s or None

    def _deep_text(obj, limit_chars=20000):
        # conservative text extraction for relevance matching
        parts = []

        def walk(o):
            if len(" ".join(parts)) > limit_chars:
                return
            if o is None:
                return
            if isinstance(o, str):
                parts.append(o)
            elif isinstance(o, (int, float, bool)):
                parts.append(str(o))
            elif isinstance(o, dict):
                for k, v in o.items():
                    if isinstance(k, str):
                        parts.append(k)
                    walk(v)
            elif isinstance(o, list):
                for it in o:
                    walk(it)

        walk(obj)
        return " ".join(parts).lower()

    def _text_score(haystack_lower, q_lower):
        # simple token score: count of matched tokens + phrase boost
        if not q_lower:
            return 0
        q = q_lower.strip()
        if q == "":
            return 0
        tokens = [t for t in re.split(r"\s+", q) if t]
        score = 0
        for t in tokens:
            if t in haystack_lower:
                score += 1
        if q in haystack_lower:
            score += 3
        return score

    def _encode_cursor(offset, seed):
        payload = {"o": offset, "s": seed}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if c is None:
            return 0, None
        if not isinstance(c, str) or c.strip() == "":
            return None, None
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict):
                return None, None
            o = payload.get("o")
            s = payload.get("s")
            if not isinstance(o, int) or o < 0:
                return None, None
            return o, s
        except Exception:
            return None, None

    t0 = time.time()
    endpoint = "search-people-by-company"

    # Validate
    if not isinstance(workspace_id, str) or not _WS_RE.match(workspace_id):
        _log(endpoint, "error", workspace_id=workspace_id, detail="invalid workspace_id", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(company_query, dict):
        _log(endpoint, "error", workspace_id=workspace_id, detail="company_query must be object", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "company_query must be an object", field="company_query")
    if person_query is not None and not isinstance(person_query, dict):
        _log(endpoint, "error", workspace_id=workspace_id, detail="person_query must be object", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "person_query must be an object", field="person_query")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(endpoint, "error", workspace_id=workspace_id, detail="invalid limit", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
    allowed_sort = {"relevance", "display_name", "last_interaction_at", "last_activity_at", "attio_updated_at", "created_at"}
    if sort is None:
        sort = "relevance"
    if sort not in allowed_sort:
        _log(endpoint, "error", workspace_id=workspace_id, detail="invalid sort", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort", allowed=sorted(list(allowed_sort)))
    if sort_direction is None:
        sort_direction = "desc"
    if sort_direction not in {"asc", "desc"}:
        _log(endpoint, "error", workspace_id=workspace_id, detail="invalid sort_direction", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "sort_direction is invalid", field="sort_direction")
    offset, seed = _decode_cursor(cursor)
    if offset is None:
        _log(endpoint, "error", workspace_id=workspace_id, detail="invalid cursor", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    # Existence
    workspaces = _load("workspaces.json")
    if not any(isinstance(w, dict) and w.get("id") == workspace_id for w in workspaces):
        _log(endpoint, "error", workspace_id=workspace_id, detail="workspace not found", latency_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "workspace not found", resource="workspace", id=workspace_id)

    records = _load("records.json")
    if not isinstance(records, list):
        records = []

    # Pre-split records
    companies = []
    people = []
    for r in records:
        if not isinstance(r, dict) or r.get("workspace_id") != workspace_id:
            continue
        if r.get("record_type") == "company":
            companies.append(r)
        elif r.get("record_type") == "person":
            people.append(r)

    # Company filtering
    cq_text = company_query.get("text")
    if cq_text is not None and not isinstance(cq_text, str):
        _log(endpoint, "error", workspace_id=workspace_id, detail="company_query.text invalid", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "company_query.text must be a string", field="company_query.text")
    cq_domain = company_query.get("domain")
    if cq_domain is not None and not isinstance(cq_domain, str):
        _log(endpoint, "error", workspace_id=workspace_id, detail="company_query.domain invalid", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "company_query.domain must be a string", field="company_query.domain")
    cq_status = company_query.get("status")
    if cq_status is not None and cq_status not in {"active", "archived", "deleted"}:
        _log(endpoint, "error", workspace_id=workspace_id, detail="company_query.status invalid", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "company_query.status is invalid", field="company_query.status")
    cq_attrs = company_query.get("attributes")
    if cq_attrs is not None and not isinstance(cq_attrs, dict):
        _log(endpoint, "error", workspace_id=workspace_id, detail="company_query.attributes invalid", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "company_query.attributes must be an object", field="company_query.attributes")

