    cq_dom_norm = _normalize_domain(cq_domain) if isinstance(cq_domain, str) else None
    cq_dom_l = cq_domain.lower().strip() if isinstance(cq_domain, str) else None

    def _match_attrs(rec_attrs, filters):
        # strict: missing keys are validation errors
        if filters is None:
            return True, None
        if not isinstance(rec_attrs, dict):
            rec_attrs = {}
        for k, v in filters.items():
            if k not in rec_attrs:
                return False, ("VALIDATION_ERROR", f"Unknown attribute key in filter: {k}", {"field": f"company_query.attributes.{k}"})
            rv = rec_attrs.get(k)
            if isinstance(v, dict):
                # support {"eq": x} and {"contains": y}
                if "eq" in v:
                    if rv != v.get("eq"):
                        return False, None
                elif "contains" in v:
                    needle = v.get("contains")
                    if not isinstance(needle, str):
                        return False, ("VALIDATION_ERROR", "contains must be a string", {"field": f"company_query.attributes.{k}.contains"})
                    if not isinstance(rv, str) or needle.lower() not in rv.lower():
                        return False, None
                else:
                    return False, ("VALIDATION_ERROR", f"Unsupported operator for attribute filter: {k}", {"field": f"company_query.attributes.{k}"})
            else:
                if rv != v:
                    return False, None
        return True, None

    matched_company_ids = set()
    company_relevance = {}  # company_id -> score
    for c in companies:
        if c.get("status") != cq_status:
            continue
        # domain filter (exact or partial)
        if cq_dom_l:
            cd = c.get("domain")
            if not isinstance(cd, str) or cd.strip() == "":
                continue
            cd_l = cd.lower()
            if cq_dom_norm:
                # allow exact normalized equals, else partial substring against normalized
                if cd_l != cq_dom_norm and cq_dom_norm not in cd_l:
                    continue
            else:
                if cq_dom_l not in cd_l:
                    continue
        # text filter
        score = 0
        if cq_text_l:
            hay = " ".join(
                [
                    (c.get("display_name") or ""),
                    (c.get("domain") or ""),
                    _deep_text(c.get("attributes")),
                    _deep_text(c.get("raw_json")),
                ]
            ).lower()
            score = _text_score(hay, cq_text_l)
            if score <= 0:
                continue
        ok, err = _match_attrs(c.get("attributes"), cq_attrs)
        if err:
            code, msg, extra = err
            _log(endpoint, "error", workspace_id=workspace_id, detail=msg, latency_ms=int((time.time() - t0) * 1000))
            return _err(code, msg, **extra)
        if not ok:
            continue
        cid = c.get("id")
        if isinstance(cid, str):
            matched_company_ids.add(cid)
            company_relevance[cid] = max(company_relevance.get(cid, 0), score)

    # If no company criteria provided except defaults, this could be broad; still ok.
    # Now find people associated with matched companies via attributes/raw_json links.
    # Heuristic: person.attributes may include company record id at keys like 'company_id', 'company', 'company_record_id'
    # or raw_json fragments. We'll check multiple.
    def _extract_person_company_ids(p):
        ids = set()
        attrs = p.get("attributes") if isinstance(p.get("attributes"), dict) else {}
        raw = p.get("raw_json") if isinstance(p.get("raw_json"), dict) else {}
        for key in ("company_id", "company_record_id", "company", "employer_id", "account_id"):
            v = attrs.get(key)
            if isinstance(v, str):
                ids.add(v)
            elif isinstance(v, dict):
                for kk in ("id", "record_id"):
                    if isinstance(v.get(kk), str):
                        ids.add(v.get(kk))
        # scan for nested "company" dicts with id fields in raw_json
        def walk(o, depth=0):
            if depth > 6:
                return
            if isinstance(o, dict):
                for k, v in o.items():
                    if k in ("company", "employer", "account") and isinstance(v, dict):
                        for kk in ("id", "record_id"):
                            if isinstance(v.get(kk), str):
                                ids.add(v.get(kk))
                    walk(v, depth + 1)
            elif isinstance(o, list):
                for it in o:
                    walk(it, depth + 1)

        walk(raw)
        return ids

    pq_text = None
    pq_status = None
    if person_query:
        pq_text = person_query.get("text")
        pq_status = person_query.get("status")
        if pq_text is not None and not isinstance(pq_text, str):
            _log(endpoint, "error", workspace_id=workspace_id, detail="person_query.text invalid", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "person_query.text must be a string", field="person_query.text")
        if pq_status is not None and pq_status not in {"active", "archived", "deleted"}:
            _log(endpoint, "error", workspace_id=workspace_id, detail="person_query.status invalid", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "person_query.status is invalid", field="person_query.status")
    if pq_status is None:
        pq_status = "active"
    pq_text_l = pq_text.lower().strip() if isinstance(pq_text, str) else None

    results = []
    for p in people:
        if p.get("status") != pq_status:
            continue
        pcids = _extract_person_company_ids(p)
        if matched_company_ids and not (pcids & matched_company_ids):
            continue

        rel = 0
        # combine relevance from company + person text
        if sort == "relevance":
            rel = 0
            if matched_company_ids:
                rel = max((company_relevance.get(cid, 0) for cid in (pcids & matched_company_ids)), default=0)
            if pq_text_l:
                hay_p = " ".join(
                    [
                        (p.get("display_name") or ""),
                        (p.get("email") or ""),
                        _deep_text(p.get("attributes")),
                        _deep_text(p.get("raw_json")),
                    ]
                ).lower()
                pr = _text_score(hay_p, pq_text_l)
                if pr <= 0:
                    continue
                rel += pr
            elif company_query.get("text"):
                # if company text existed, keep; otherwise relevance stays possibly 0
                pass
        else:
            # Apply person text filter even if not sorting by relevance
            if pq_text_l:
                hay_p = " ".join(
                    [
                        (p.get("display_name") or ""),
                        (p.get("email") or ""),
                        _deep_text(p.get("attributes")),
                        _deep_text(p.get("raw_json")),
                    ]
                ).lower()
                if _text_score(hay_p, pq_text_l) <= 0:
                    continue

        results.append({"person": p, "_relevance": rel})

    # Sort
    reverse = sort_direction == "desc"

    def _sort_key(item):
        p = item["person"]
        if sort == "relevance":
            return item["_relevance"]
        if sort == "display_name":
            return (p.get("display_name") or "").lower()
        if sort == "last_interaction_at":
            dt = _parse_dt(p.get("last_interaction_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if sort == "last_activity_at":
            dt = _parse_dt(p.get("last_activity_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if sort == "attio_updated_at":
            dt = _parse_dt(p.get("attio_updated_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if sort == "created_at":
            dt = _parse_dt(p.get("created_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return 0

    try:
        results.sort(key=_sort_key, reverse=reverse)
    except Exception:
        _log(endpoint, "error", workspace_id=workspace_id, detail="sort failure", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "unable to sort with provided parameters")

    total = len(results)
    page = results[offset : offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset, seed or _new_id("att_seed")) if has_more else None

    out_people = [it["person"] for it in page]

    _log(endpoint, "ok", workspace_id=workspace_id, detail=f"returned {len(out_people)} of {total}", latency_ms=int((time.time() - t0) * 1000))
    return {
        "people": out_people,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

def search_people_by_company_list(workspace_id, list_id, person_query=None, limit=None, cursor=None, sort=None, sort_direction=None, **_extra):
