    pq_text = None
    pq_status = None
    if person_query:
        pq_text = person_query.get("text")
        pq_status = person_query.get("status")
        if pq_text is not None and not isinstance(pq_text, str):
            _log(endpoint, "error", workspace_id=workspace_id, detail="person_query.text invalid", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "person_query.text must be a string", field="person_query.text")
        if pq_status is not None and pq_status not in {"active", "archived", "deleted"}:
            _log(endpoint, "error", workspace_id=workspace_id, detail="person_query.status invalid", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "person_query.status is invalid", field="person_query.status")
    if pq_status is None:
        pq_status = "active"
    pq_text_l = pq_text.lower().strip() if isinstance(pq_text, str) else None

    people = [r for r in rec_by_id.values() if r.get("record_type") == "person" and r.get("status") == pq_status]

    results = []
    for p in people:
        pcids = _extract_person_company_ids(p)
        if company_ids and not (pcids & company_ids):
            continue
        rel = 0
        if sort == "relevance":
            if pq_text_l:
                hay = " ".join([(p.get("display_name") or ""), (p.get("email") or ""), _deep_text(p.get("attributes")), _deep_text(p.get("raw_json"))]).lower()
                rel = _text_score(hay, pq_text_l)
                if rel <= 0:
                    continue
            else:
                rel = 0
        else:
            if pq_text_l:
                hay = " ".join([(p.get("display_name") or ""), (p.get("email") or ""), _deep_text(p.get("attributes")), _deep_text(p.get("raw_json"))]).lower()
                if _text_score(hay, pq_text_l) <= 0:
                    continue
        results.append({"person": p, "_relevance": rel})

    reverse = sort_direction == "desc"

    def _sort_key(item):
        p = item["person"]
        if sort == "relevance":
            return item["_relevance"]
        if sort == "display_name":
            return (p.get("display_name") or "").lower()
        if sort == "last_interaction_at":
            dt = _parse_dt(p.get("last_interaction_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if sort == "last_activity_at":
            dt = _parse_dt(p.get("last_activity_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if sort == "attio_updated_at":
            dt = _parse_dt(p.get("attio_updated_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if sort == "created_at":
            dt = _parse_dt(p.get("created_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return 0

    try:
        results.sort(key=_sort_key, reverse=reverse)
    except Exception:
        _log(endpoint, "error", workspace_id=workspace_id, detail="sort failure", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "unable to sort with provided parameters")

    total = len(results)
    page = results[offset : offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset, seed or _new_id("att_seed")) if has_more else None

    out_people = [it["person"] for it in page]

    _log(endpoint, "ok", workspace_id=workspace_id, detail=f"returned {len(out_people)} of {total}", latency_ms=int((time.time() - t0) * 1000))
    return {"people": out_people, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def search_people_by_notes(workspace_id, query, limit=None, cursor=None, sort=None, sort_direction=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    _WS_RE = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")

    def _new_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        v = ms
        chars = []
        for _ in range(10):
            v, r = divmod(v, 32)
            chars.append(alphabet[r])
        chars = chars[::-1]
        rand = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{''.join(chars)}{rand}"

    def _log(endpoint, status, workspace_id=None, detail=None, latency_ms=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _new_id("att_log"),
                "endpoint": endpoint,
                "status": status,
                "workspace_id": workspace_id,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _encode_cursor(offset, seed):
        payload = {"o": offset, "s": seed}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if c is None:
            return 0, None
        if not isinstance(c, str) or c.strip() == "":
            return None, None
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict):
                return None, None
            o = payload.get("o")
            s = payload.get("s")
            if not isinstance(o, int) or o < 0:
                return None, None
            return o, s
        except Exception:
            return None, None

    t0 = time.time()
    endpoint = "search-people-by-notes"

    # Validate
    if not isinstance(workspace_id, str) or not _WS_RE.match(workspace_id):
        _log(endpoint, "error", workspace_id=workspace_id, detail="invalid workspace_id", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(query, str) or query.strip() == "":
        _log(endpoint, "error", workspace_id=workspace_id, detail="empty query", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(endpoint, "error", workspace_id=workspace_id, detail="invalid limit", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
    allowed_sort = {"relevance", "last_activity_at", "attio_updated_at", "created_at"}
    if sort is None:
        sort = "relevance"
    if sort not in allowed_sort:
        _log(endpoint, "error", workspace_id=workspace_id, detail="invalid sort", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort", allowed=sorted(list(allowed_sort)))
    if sort_direction is None:
        sort_direction = "desc"
    if sort_direction not in {"asc", "desc"}:
        _log(endpoint, "error", workspace_id=workspace_id, detail="invalid sort_direction", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "sort_direction is invalid", field="sort_direction")
    offset, seed = _decode_cursor(cursor)
    if offset is None:
        _log(endpoint, "error", workspace_id=workspace_id, detail="invalid cursor", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    # Existence
    workspaces = _load("workspaces.json")
    if not any(isinstance(w, dict) and w.get("id") == workspace_id for w in workspaces):
        _log(endpoint, "error", workspace_id=workspace_id, detail="workspace not found", latency_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "workspace not found", resource="workspace", id=workspace_id)

    records = _load("records.json")
    if not isinstance(records, list):
        records = []
    notes_tasks = _load("notes_tasks.json")
    if not isinstance(notes_tasks, list):
        notes_tasks = []

    people = {r.get("id"): r for r in records if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("record_type") == "person" and r.get("status") == "active"}
    if not people:
        _log(endpoint, "ok", workspace_id=workspace_id, detail="no people", latency_ms=int((time.time() - t0) * 1000))
        return {"people": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}

    ql = query.lower().strip()

    # Find notes that match and are linked to people
    person_scores = {}  # person_id -> relevance score from notes
    for nt in notes_tasks:
        if not isinstance(nt, dict):
            continue
        if nt.get("workspace_id") != workspace_id:
            continue
        if nt.get("activity_type") != "note":
            continue
        if nt.get("status") != "active":
            continue
        body = nt.get("body") or ""
        if not isinstance(body, str) or body == "":
            continue
        hay = body.lower()
        if ql not in hay:
            # allow token match too
            tokens = [t for t in re.split(r"\s+", ql) if t]
            if not any(t in hay for t in tokens):
                continue
        # score
        score = 0
        tokens = [t for t in re.split(r"\s+", ql) if t]
        for t in tokens:
            if t in hay:
                score += 1
        if ql in hay:
            score += 3

        linked = nt.get("linked_record_ids")
        if not isinstance(linked, list):
            continue
        for rid in linked:
            if rid in people:
                person_scores[rid] = max(person_scores.get(rid, 0), score)

    matched = []
    for pid, sc in person_scores.items():
        p = people.get(pid)
        if p:
            matched.append({"person": p, "_relevance": sc})

    reverse = sort_direction == "desc"

    def _sort_key(item):
        p = item["person"]
        if sort == "relevance":
            return item["_relevance"]
        if sort == "last_activity_at":
            dt = _parse_dt(p.get("last_activity_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if sort == "attio_updated_at":
            dt = _parse_dt(p.get("attio_updated_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if sort == "created_at":
            dt = _parse_dt(p.get("created_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return 0

    try:
        matched.sort(key=_sort_key, reverse=reverse)
    except Exception:
        _log(endpoint, "error", workspace_id=workspace_id, detail="sort failure", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "unable to sort with provided parameters")

    total = len(matched)
    page = matched[offset : offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset, seed or _new_id("att_seed")) if has_more else None

    out_people = [it["person"] for it in page]

    _log(endpoint, "ok", workspace_id=workspace_id, detail=f"returned {len(out_people)} of {total}", latency_ms=int((time.time() - t0) * 1000))
    return {"people": out_people, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def get_lists(workspace_id, list_type=None, applies_to=None, status=None, limit=None, cursor=None, sort=None, sort_direction=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-lists"
    ws_pat = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if obj.get("v") != 1 or obj.get("ep") != endpoint:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _mk_cursor(off):
        payload = {"v": 1, "ep": endpoint, "offset": off}
        b = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    def _log(status_code, workspace_local_id=None, extra=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_local_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now_iso(),
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(workspace_id, str) or not ws_pat.match(workspace_id):
        _log(400, None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if list_type is not None and list_type not in {"pipeline", "segment", "static", "other"}:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported list_type")
    if applies_to is not None and applies_to not in {"company", "person", "custom", "mixed"}:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported applies_to")
    if status is not None and status not in {"active", "archived", "deleted"}:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit is out of range")
    if sort is None:
        sort = "name"
    if sort not in {"name", "created_at", "updated_at"}:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort")
    if sort_direction is None:
        sort_direction = "asc"
    if sort_direction not in {"asc", "desc"}:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort_direction")
    off = _parse_cursor(cursor)
    if off is None:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor")

    workspaces = _load("workspaces.json")
    if not any(isinstance(w, dict) and w.get("id") == workspace_id for w in workspaces):
        _log(404, workspace_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    lists = _load("lists.json")
    if not isinstance(lists, list):
        lists = []

    rows = []
    for r in lists:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if list_type is not None and r.get("list_type") != list_type:
            continue
        if applies_to is not None and r.get("applies_to") != applies_to:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    def _sort_key(x):
        v = x.get(sort)
        if sort == "name":
            return ("" if v is None else str(v).lower(), x.get("id") or "")
        # ISO datetime strings sort lexicographically if consistent
        return ("" if v is None else str(v), x.get("id") or "")

    reverse = sort_direction == "desc"
    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # If data is malformed, degrade to id sort without crashing.
        rows.sort(key=lambda x: str(x.get("id") or ""), reverse=reverse)

    total = len(rows)
    page = rows[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _mk_cursor(next_off) if has_more else None

    out = []
    for r in page:
        out.append({
            "id": r.get("id"),
            "attio_list_id": r.get("attio_list_id"),
            "name": r.get("name"),
            "list_type": r.get("list_type"),
            "applies_to": r.get("applies_to"),
            "status": r.get("status"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    _log(200, workspace_id, extra={"returned": len(out), "total": total})
    return {
        "lists": out,
        "pagination": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    }

