def get_list_entries(workspace_id, list_id, status=None, record_type=None, limit=None, cursor=None, sort=None, sort_direction=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-list-entries"
    ws_pat = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    lst_pat = re.compile(r"^att_lst_[0-9A-HJKMNP-TV-Z]{26}$")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if obj.get("v") != 1 or obj.get("ep") != endpoint:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _mk_cursor(off):
        payload = {"v": 1, "ep": endpoint, "offset": off}
        b = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    def _log(status_code, ws=None, extra=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "workspace_id": ws,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now_iso(),
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(workspace_id, str) or not ws_pat.match(workspace_id):
        _log(400, None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(list_id, str) or not lst_pat.match(list_id):
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "list_id is malformed")
    if status is not None and status not in {"active", "removed"}:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported status")
    if record_type is not None and record_type not in {"company", "person", "custom"}:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported record_type")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit is out of range")
    if sort is None:
        sort = "added_at"
    if sort not in {"added_at", "updated_at", "created_at"}:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort")
    if sort_direction is None:
        sort_direction = "desc"
    if sort_direction not in {"asc", "desc"}:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort_direction")
    off = _parse_cursor(cursor)
    if off is None:
        _log(400, workspace_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor")

    # Existence checks
    workspaces = _load("workspaces.json")
    if not any(isinstance(w, dict) and w.get("id") == workspace_id for w in workspaces):
        _log(404, workspace_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    lists = _load("lists.json")
    lrow = None
    if isinstance(lists, list):
        for l in lists:
            if isinstance(l, dict) and l.get("id") == list_id and l.get("workspace_id") == workspace_id:
                lrow = l
                break
    if lrow is None:
        _log(404, workspace_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "List not found in workspace")

    records = _load("records.json")
    rec_by_id = {}
    if isinstance(records, list):
        for r in records:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                rid = r.get("id")
                if rid:
                    rec_by_id[rid] = r

    entries = _load("list_entries.json")
    if not isinstance(entries, list):
        entries = []

    matched = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id:
            continue
        if e.get("list_id") != list_id:
            continue
        if status is not None and e.get("status") != status:
            continue
        r = rec_by_id.get(e.get("record_id"))
        if r is None:
            continue
        if record_type is not None and r.get("record_type") != record_type:
            continue
        matched.append((e, r))

    reverse = sort_direction == "desc"

    def _sort_key(t):
        e, r = t
        v = e.get(sort)
        # Use string compare for ISO-ish datetimes; stable tie-breaker by id
        return ("" if v is None else str(v), str(e.get("id") or ""))

    try:
        matched.sort(key=_sort_key, reverse=reverse)
    except Exception:
        matched.sort(key=lambda t: str(t[0].get("id") or ""), reverse=reverse)

    total = len(matched)
    page = matched[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _mk_cursor(next_off) if has_more else None

    out = []
    for e, r in page:
        out.append({
            "entry": {
                "id": e.get("id"),
                "attio_entry_id": e.get("attio_entry_id"),
                "list_id": e.get("list_id"),
                "record_id": e.get("record_id"),
                "status": e.get("status"),
                "entry_attributes": e.get("entry_attributes"),
                "added_at": e.get("added_at"),
                "removed_at": e.get("removed_at"),
                "created_at": e.get("created_at"),
                "updated_at": e.get("updated_at"),
            },
            "record": {
                "id": r.get("id"),
                "record_type": r.get("record_type"),
                "display_name": r.get("display_name"),
                "domain": r.get("domain"),
                "email": r.get("email"),
                "phone": r.get("phone"),
                "status": r.get("status"),
                "attio_object": r.get("attio_object"),
                "attio_record_id": r.get("attio_record_id"),
                "updated_at": r.get("updated_at"),
            }
        })

    _log(200, workspace_id, extra={"list_id": list_id, "returned": len(out), "total": total})
    return {
        "list": {"id": lrow.get("id"), "name": lrow.get("name"), "list_type": lrow.get("list_type"), "applies_to": lrow.get("applies_to")},
        "entries": out,
        "pagination": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    }

def filter_list_entries(workspace_id, list_id, attribute_key, attribute_value, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "filter-list-entries"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential": None,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return "bad"
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else "bad"
        except Exception:
            return "bad"

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    lst_re = re.compile(r"^att_lst_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _log("VALIDATION_ERROR", {"field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(list_id, str) or not lst_re.fullmatch(list_id):
        _log("VALIDATION_ERROR", {"field": "list_id"})
        return _err("VALIDATION_ERROR", "list_id is invalid", field="list_id")
    if not isinstance(attribute_key, str) or attribute_key.strip() == "":
        _log("VALIDATION_ERROR", {"field": "attribute_key"})
        return _err("VALIDATION_ERROR", "attribute_key must be a non-empty string", field="attribute_key")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "removed"):
            _log("VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, removed", field="status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
    if sort is None:
        sort = "-added_at"
    if not isinstance(sort, str) or sort not in ("added_at", "-added_at", "updated_at", "-updated_at"):
        _log("VALIDATION_ERROR", {"field": "sort"})
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    cur = _decode_cursor(cursor)
    if cur == "bad":
        _log("VALIDATION_ERROR", {"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("NOT_FOUND", {"workspace_id": workspace_id})
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
    if ws.get("status") == "deleting":
        _log("UNAUTHORIZED", {"workspace_status": ws.get("status")})
        return _err("UNAUTHORIZED", "Workspace is not accessible", workspace_id=workspace_id, workspace_status=ws.get("status"))

    lists = _load("lists.json")
    if isinstance(lists, dict) and "rows" in lists:
        lists = lists.get("rows")
    if not isinstance(lists, list):
        lists = []
    lst = next((l for l in lists if isinstance(l, dict) and l.get("id") == list_id and l.get("workspace_id") == workspace_id), None)
    if not lst:
        _log("NOT_FOUND", {"list_id": list_id})
        return _err("NOT_FOUND", "List not found", list_id=list_id)

    entries = _load("list_entries.json")
    if isinstance(entries, dict) and "rows" in entries:
        entries = entries.get("rows")
    if not isinstance(entries, list):
        entries = []

    # filter to workspace/list, then attribute match
    filtered = []
    missing_key_seen = False
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id or e.get("list_id") != list_id:
            continue
        if status is not None and e.get("status") != status:
            continue
        attrs = e.get("entry_attributes")
        if attrs is None:
            attrs = {}
        if not isinstance(attrs, dict):
            continue
        if attribute_key not in attrs:
            # business rule: invalid attribute keys yield error rather than ignore
            missing_key_seen = True
            continue
        if attrs.get(attribute_key) == attribute_value:
            filtered.append(e)

    if missing_key_seen and len(filtered) == 0:
        _log("VALIDATION_ERROR", {"field": "attribute_key"})
        return _err("VALIDATION_ERROR", "attribute_key is not present in entry_attributes for this list", field="attribute_key")

    key = sort.lstrip("-")
    desc = sort.startswith("-")

    def _dt(s):
        if not isinstance(s, str):
            return ""
        return s

    filtered.sort(key=lambda x: _dt(x.get(key)), reverse=desc)

    start = 0
    if isinstance(cur, dict):
        if cur.get("list_id") != list_id or cur.get("workspace_id") != workspace_id:
            _log("VALIDATION_ERROR", {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        if cur.get("sort") != sort:
            _log("VALIDATION_ERROR", {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        start = int(cur.get("offset") or 0)
        if start < 0:
            start = 0

    page = filtered[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < len(filtered)
    next_cursor = _encode_cursor({"workspace_id": workspace_id, "list_id": list_id, "sort": sort, "offset": next_offset}) if has_more else None

    _log("OK", {"returned": len(page), "total": len(filtered), "has_more": has_more})
    return {
        "workspace_id": workspace_id,
        "list_id": list_id,
        "attribute_key": attribute_key,
        "attribute_value": attribute_value,
        "status": status,
        "sort": sort,
        "limit": limit,
        "total": len(filtered),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "entries": page
    }

def advanced_filter_list_entries(workspace_id, list_id, conditions, match=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
