        return _err("VALIDATION_ERROR", "conditions must be a non-empty array", field="conditions")

    if match is None:
        match = "all"
    if match not in ("all", "any"):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "match is invalid", "field": "match"})
        return _err("VALIDATION_ERROR", "match is invalid", field="match")

    if status is None:
        status = "active"
    if status not in ("active", "removed"):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "status is invalid", "field": "status"})
        return _err("VALIDATION_ERROR", "status is invalid", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "limit must be 1..200", "field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be 1..200", field="limit")

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "cursor is malformed", "field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
    offset = 0
    if isinstance(cursor, str) and cursor.strip().startswith("off:"):
        try:
            offset = int(cursor.strip().split(":", 1)[1])
            if offset < 0:
                offset = 0
        except Exception:
            _log("error", detail={"code": "VALIDATION_ERROR", "message": "cursor is malformed", "field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    if sort is None:
        sort = "-added_at"
    if sort not in ("added_at", "-added_at", "updated_at", "-updated_at"):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "sort is invalid", "field": "sort"})
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    # validate conditions and operators
    allowed_ops = {"eq", "neq", "in", "nin", "contains", "exists", "gte", "gt", "lte", "lt"}
    for i, c in enumerate(conditions):
        if not isinstance(c, dict):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"conditions[{i}] must be an object", "field": "conditions"})
            return _err("VALIDATION_ERROR", f"conditions[{i}] must be an object", field="conditions")
        ak = c.get("attribute_key")
        op = c.get("operator")
        if not isinstance(ak, str) or not ak.strip():
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"conditions[{i}].attribute_key is required", "field": "attribute_key"})
            return _err("VALIDATION_ERROR", f"conditions[{i}].attribute_key is required", field="attribute_key")
        if op not in allowed_ops:
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"conditions[{i}].operator is invalid", "field": "operator"})
            return _err("VALIDATION_ERROR", f"conditions[{i}].operator is invalid", field="operator")
        if op in ("in", "nin") and not isinstance(c.get("value"), list):
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"conditions[{i}].value must be an array for operator {op}", "field": "value"})
            return _err("VALIDATION_ERROR", f"conditions[{i}].value must be an array for operator {op}", field="value")

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws_row is None:
        _log("error", detail={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")

    lists = _load("lists.json")
    if isinstance(lists, dict) and "rows" in lists:
        lists = lists.get("rows")
    if not isinstance(lists, list):
        lists = []
    lst = next((l for l in lists if isinstance(l, dict) and l.get("id") == list_id and l.get("workspace_id") == workspace_id), None)
    if lst is None:
        _log("error", detail={"code": "NOT_FOUND", "message": "List not found"})
        return _err("NOT_FOUND", "List not found")

    list_entries = _load("list_entries.json")
    if isinstance(list_entries, dict) and "rows" in list_entries:
        list_entries = list_entries.get("rows")
    if not isinstance(list_entries, list):
        list_entries = []

    # invalid attribute keys should error rather than ignore: require key exists in at least one entry for the list
    keys_seen = set()
    for e in list_entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id or e.get("list_id") != list_id:
            continue
        ea = e.get("entry_attributes")
        if isinstance(ea, dict):
            for k in ea.keys():
                if isinstance(k, str):
                    keys_seen.add(k)
    for c in conditions:
        k = c.get("attribute_key")
        if isinstance(k, str) and k and keys_seen and k not in keys_seen:
            _log("error", detail={"code": "VALIDATION_ERROR", "message": f"Unknown attribute key: {k}", "field": "attribute_key"})
            return _err("VALIDATION_ERROR", f"Unknown attribute key: {k}", field="attribute_key")

    def _cmp(op, exists, left, right):
        if op == "exists":
            return bool(exists)
        if not exists:
            return False
        if op == "eq":
            return left == right
        if op == "neq":
            return left != right
        if op == "contains":
            if isinstance(left, str) and isinstance(right, str):
                return right.lower() in left.lower()
            if isinstance(left, list):
                return right in left
            if isinstance(left, dict) and isinstance(right, str):
                return right in left
            return False
        if op in ("in", "nin"):
            if not isinstance(right, list):
                return False
            hit = left in right
            return hit if op == "in" else (not hit)
        try:
            if op == "gte":
                return left >= right
            if op == "gt":
                return left > right
            if op == "lte":
                return left <= right
            if op == "lt":
                return left < right
        except TypeError:
            return False
        return False

    def _matches(e):
        ea = e.get("entry_attributes")
        if not isinstance(ea, dict):
            ea = {}
        checks = []
        for c in conditions:
            k = c.get("attribute_key")
            op = c.get("operator")
            val = c.get("value", None)
            exists = k in ea
            checks.append(_cmp(op, exists, ea.get(k), val))
        return all(checks) if match == "all" else any(checks)

    entries = []
    for e in list_entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id:
            continue
        if e.get("list_id") != list_id:
            continue
        if e.get("status") != status:
            continue
        if _matches(e):
            entries.append(e)

    def _dt_key(v):
        if not isinstance(v, str) or not v:
            return None
        s = v
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    reverse = sort.startswith("-")
    field = sort[1:] if reverse else sort
    if field in ("added_at", "updated_at"):
        entries.sort(key=lambda e: (_dt_key(e.get(field)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), e.get("id") or ""), reverse=reverse)

    total = len(entries)
    page = entries[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = ("off:%d" % next_offset) if has_more else None

    resp = {"entries": page, "meta": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more}}
    _log("ok")
    return resp

def add_record_to_list(workspace_id, list_id, record_id, entry_attributes=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add-record-to-list"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "credential": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail
        })
        _save("request_logs.json", logs)

    def _new_entry_id():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "att_lse_" + "".join(alphabet[random.randrange(len(alphabet))] for _ in range(26))

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    lst_re = re.compile(r"^att_lst_[0-9A-HJKMNP-TV-Z]{26}$")
    rec_re = re.compile(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _log("VALIDATION_ERROR", {"field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(list_id, str) or not lst_re.fullmatch(list_id):
        _log("VALIDATION_ERROR", {"field": "list_id"})
        return _err("VALIDATION_ERROR", "list_id is invalid", field="list_id")
    if not isinstance(record_id, str) or not rec_re.fullmatch(record_id):
        _log("VALIDATION_ERROR", {"field": "record_id"})
        return _err("VALIDATION_ERROR", "record_id is invalid", field="record_id")
    if entry_attributes is None:
        entry_attributes = {}
    if not isinstance(entry_attributes, dict):
        _log("VALIDATION_ERROR", {"field": "entry_attributes"})
        return _err("VALIDATION_ERROR", "entry_attributes must be an object", field="entry_attributes")

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("NOT_FOUND", {"workspace_id": workspace_id})
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
    if ws.get("status") == "deleting":
        _log("UNAUTHORIZED", {"workspace_status": ws.get("status")})
        return _err("UNAUTHORIZED", "Workspace is not accessible", workspace_id=workspace_id, workspace_status=ws.get("status"))

    lists = _load("lists.json")
    if isinstance(lists, dict) and "rows" in lists:
        lists = lists.get("rows")
    if not isinstance(lists, list):
        lists = []
    lst = next((l for l in lists if isinstance(l, dict) and l.get("id") == list_id and l.get("workspace_id") == workspace_id), None)
    if not lst:
        _log("NOT_FOUND", {"list_id": list_id})
        return _err("NOT_FOUND", "List not found", list_id=list_id)

    records = _load("records.json")
    if isinstance(records, dict) and "rows" in records:
        records = records.get("rows")
    if not isinstance(records, list):
        records = []
    rec = next((r for r in records if isinstance(r, dict) and r.get("id") == record_id and r.get("workspace_id") == workspace_id), None)
    if not rec:
        _log("NOT_FOUND", {"record_id": record_id})
        return _err("NOT_FOUND", "Record not found", record_id=record_id)

    # validate entry_attributes object already done; for pipeline lists validate stage if provided
    if lst.get("list_type") == "pipeline" and "stage" in entry_attributes:
        fc = lst.get("field_config")
        if not isinstance(fc, dict):
            _log("VALIDATION_ERROR", {"field": "field_config"})
            return _err("VALIDATION_ERROR", "List field_config is invalid", field="field_config")
        stages = fc.get("stages") or fc.get("pipeline_stages") or fc.get("stage_options")
        stage_ids = set()
        if isinstance(stages, list):
            for s in stages:
                if isinstance(s, dict) and isinstance(s.get("id"), str):
                    stage_ids.add(s.get("id"))
                elif isinstance(s, str):
                    stage_ids.add(s)
        if stage_ids and entry_attributes.get("stage") not in stage_ids:
            _log("VALIDATION_ERROR", {"field": "entry_attributes.stage"})
            return _err("VALIDATION_ERROR", "Invalid stage for pipeline list", field="entry_attributes.stage", allowed_stage_ids=sorted(stage_ids))

    entries = _load("list_entries.json")
    if isinstance(entries, dict) and "rows" in entries:
        entries = entries.get("rows")
    if not isinstance(entries, list):
        entries = []

    now = _now_iso()

    # idempotent/reactivate: unique(list_id, record_id) where status='active'
    existing = None
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") == workspace_id and e.get("list_id") == list_id and e.get("record_id") == record_id:
            existing = e
            break

    if existing:
        # Reactivate if removed, or update attributes if already active (idempotent-ish)
        if existing.get("status") == "removed":
            existing["status"] = "active"
            existing["removed_at"] = None
            existing["added_at"] = now
        # merge/replace entry_attributes on create-style call: set to provided keys (keep others)
        ea = existing.get("entry_attributes")
        if ea is None or not isinstance(ea, dict):
            ea = {}
        for k, v in entry_attributes.items():
            ea[k] = v
        existing["entry_attributes"] = ea
        existing["updated_at"] = now
        _save("list_entries.json", entries)
        _log("OK", {"id": existing.get("id"), "reactivated": True if existing.get("status") == "active" else False})
        return existing

    # create new
    new_id = _new_entry_id()
    existing_ids = {e.get("id") for e in entries if isinstance(e, dict)}
    tries = 0
    while new_id in existing_ids and tries < 10:
        new_id = _new_entry_id()
        tries += 1

    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "list_id": list_id,
        "record_id": record_id,
        "attio_entry_id": None,
        "status": "active",
        "entry_attributes": entry_attributes,
        "added_at": now,
        "removed_at": None,
        "created_at": now,
        "updated_at": now
    }
    entries.append(row)
    _save("list_entries.json", entries)
    _log("OK", {"id": new_id, "created": True})
    return row

def remove_record_from_list(workspace_id, list_id, record_id, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "remove-record-from-list"

    ws_pat = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    lst_pat = re.compile(r"^att_lst_[0-9A-HJKMNP-TV-Z]{26}$")
    rec_pat = re.compile(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now() + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "credential": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        }
        if meta is not None:
            entry["meta"] = meta
        logs.append(entry)
        _save("request_logs.json", logs)

    # ---- validate ----
    if not isinstance(workspace_id, str) or not ws_pat.match(workspace_id):
        _log("VALIDATION_ERROR", {"field": "workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")
    if not isinstance(list_id, str) or not lst_pat.match(list_id):
        _log("VALIDATION_ERROR", {"field": "list_id"})
        return _err("VALIDATION_ERROR", "Invalid list_id format.", field="list_id")
    if not isinstance(record_id, str) or not rec_pat.match(record_id):
        _log("VALIDATION_ERROR", {"field": "record_id"})
        return _err("VALIDATION_ERROR", "Invalid record_id format.", field="record_id")

    # ---- resolve workspace/list ----
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace not active.")

    lists = _load("lists.json")
    lst = next((l for l in lists if isinstance(l, dict) and l.get("id") == list_id and l.get("workspace_id") == workspace_id), None)
    if lst is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "List not found in workspace.")

    entries = _load("list_entries.json")
    if not isinstance(entries, list):
        entries = []

    entry = None
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") == workspace_id and e.get("list_id") == list_id and e.get("record_id") == record_id:
            entry = e
            break

    if entry is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "List entry not found for that record in that list.")

    if entry.get("status") == "removed":
        _log("CONFLICT")
        return _err("CONFLICT", "List entry is already removed.")

    # transition active -> removed
    now = _now()
    entry["status"] = "removed"
    entry["removed_at"] = now
    entry["updated_at"] = now
    _save("list_entries.json", entries)
    _log("ok", {"entry_id": entry.get("id")})
    return {"data": entry}

def update_list_entry(workspace_id, list_entry_id, entry_attributes=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update-list-entry"
    used_credential = None

    def _log(status_code, ok, extra=None):
        try:
            logs = _load("request_logs.json")
            now = datetime.datetime.now(datetime.timezone.utc).isoformat()
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "ts": now,
                "endpoint": endpoint,
                "workspace_id": workspace_id,
                "credential_id": used_credential,
                "status": status_code,
                "ok": bool(ok),
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if extra:
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
            _log(400, False)
            return _err("VALIDATION_ERROR", "workspace_id is malformed")
        if not isinstance(list_entry_id, str) or not re.match(r"^att_lse_[0-9A-HJKMNP-TV-Z]{26}$", list_entry_id):
            _log(400, False)
            return _err("VALIDATION_ERROR", "list_entry_id is malformed")
        if entry_attributes is not None and not isinstance(entry_attributes, dict):
            _log(400, False)
            return _err("VALIDATION_ERROR", "entry_attributes must be an object")
        if status is not None and status not in ("active", "removed"):
            _log(400, False)
            return _err("VALIDATION_ERROR", "status must be one of: active, removed")
        if entry_attributes is None and status is None:
            _log(400, False)
            return _err("VALIDATION_ERROR", "At least one of entry_attributes or status must be provided")
    except Exception as e:
        _log(500, False)
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log(404, False)
        return _err("NOT_FOUND", "Workspace not found")

    if ws.get("status") != "active":
        _log(401, False)
        return _err("UNAUTHORIZED", "Workspace is not active")

    entries = _load("list_entries.json")
    idx = None
    entry = None
    for i, e in enumerate(entries):
        if e.get("id") == list_entry_id:
            idx = i
            entry = e
            break
    if not entry:
        _log(404, False)
        return _err("NOT_FOUND", "List entry not found")
    if entry.get("workspace_id") != workspace_id:
        _log(404, False)
        return _err("NOT_FOUND", "List entry not found in workspace")

    lists = _load("lists.json")
    parent_list = next((l for l in lists if l.get("id") == entry.get("list_id")), None)
    if not parent_list or parent_list.get("workspace_id") != workspace_id:
        _log(404, False)
        return _err("NOT_FOUND", "Parent list not found in workspace")

    records = _load("records.json")
    parent_record = next((r for r in records if r.get("id") == entry.get("record_id")), None)
    if not parent_record or parent_record.get("workspace_id") != workspace_id:
        _log(404, False)
        return _err("NOT_FOUND", "Parent record not found in workspace")

    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Lifecycle transition validation
    if status is not None:
        cur = entry.get("status")
        if cur not in ("active", "removed"):
            _log(409, False)
            return _err("CONFLICT", "List entry has invalid current status")
        allowed = {"active": ["removed"], "removed": ["active"]}
        if status != cur and status not in allowed.get(cur, []):
            _log(409, False)
            return _err("INVALID_TRANSITION", f"Cannot transition list entry status from {cur} to {status}")

    # Pipeline stage validation if updating entry_attributes
    if entry_attributes is not None:
        if parent_list.get("list_type") == "pipeline":
            fc = parent_list.get("field_config")
            if not isinstance(fc, dict):
                _log(409, False)
                return _err("CONFLICT", "List field_config is invalid")
            stage_ids = set()
            if isinstance(fc.get("stages"), list):
                for s in fc["stages"]:
                    if isinstance(s, dict) and isinstance(s.get("id"), str):
                        stage_ids.add(s["id"])
            if isinstance(fc.get("stage_ids"), list):
                for sid in fc["stage_ids"]:
                    if isinstance(sid, str):
                        stage_ids.add(sid)
            if isinstance(fc.get("stages_by_id"), dict):
                for sid in fc["stages_by_id"].keys():
                    if isinstance(sid, str):
                        stage_ids.add(sid)

            # If the client sets a stage, it must be valid
            if "stage" in entry_attributes:
                v = entry_attributes.get("stage")
                if v is None or not isinstance(v, str):
                    _log(400, False)
                    return _err("VALIDATION_ERROR", "entry_attributes.stage must be a string for pipeline lists")
                if stage_ids and v not in stage_ids:
                    _log(409, False)
                    return _err("CONFLICT", "Invalid stage id for pipeline list", stage=v)

    # Uniqueness constraints on (list_id, record_id) where status='active'
    if status == "active" and entry.get("status") != "active":
        for e in entries:
            if e.get("id") != entry.get("id") and e.get("list_id") == entry.get("list_id") and e.get("record_id") == entry.get("record_id") and e.get("status") == "active":
                _log(409, False)
                return _err("CONFLICT", "An active entry for this record already exists in the list")

    # Apply changes
    mutated = False
    updated = dict(entry)

    if entry_attributes is not None:
        updated["entry_attributes"] = entry_attributes
        mutated = True

    if status is not None and status != entry.get("status"):
        updated["status"] = status
        mutated = True
        if status == "removed":
            updated["removed_at"] = now
        elif status == "active":
            updated["removed_at"] = None
            # Reactivation: set added_at to now per business rule (added_at set on create/reactivate)
            updated["added_at"] = now

    if not mutated:
        _log(404, False)
        return _err("NOT_FOUND", "No changes applied")

    updated["updated_at"] = now
    entries[idx] = updated
    _save("list_entries.json", entries)

    _log(200, True)
    return {"list_entry": updated}

def filter_list_entries_by_parent(workspace_id, list_id, parent_conditions, match=None, entry_status=None, record_type=None, record_status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "filter-list-entries-by-parent"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _get_log_file():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(status, detail=None):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now() + "|" + str(time.time()) + "|" + str(random.getrandbits(64))).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail,
        })
        _save(fn, logs)

    def _encode_cursor(o):
        raw = json.dumps(o, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return "bad"
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else "bad"
        except Exception:
            return "bad"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(float(v), tz=datetime.timezone.utc)
        if isinstance(v, str):
            try:
                s = v[:-1] + "+00:00" if v.endswith("Z") else v
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    ws_pat = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    lst_pat = re.compile(r"^att_lst_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(workspace_id, str) or not ws_pat.fullmatch(workspace_id):
        _log("error", {"code": "VALIDATION_ERROR", "message": "workspace_id is invalid", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(list_id, str) or not lst_pat.fullmatch(list_id):
        _log("error", {"code": "VALIDATION_ERROR", "message": "list_id is invalid", "field": "list_id"})
        return _err("VALIDATION_ERROR", "list_id is invalid", field="list_id")
    if not isinstance(parent_conditions, list) or len(parent_conditions) < 1:
        _log("error", {"code": "VALIDATION_ERROR", "message": "parent_conditions must be a non-empty array", "field": "parent_conditions"})
        return _err("VALIDATION_ERROR", "parent_conditions must be a non-empty array", field="parent_conditions")
    if match is None:
        match = "all"
    if match not in ("all", "any"):
        _log("error", {"code": "VALIDATION_ERROR", "message": "match is invalid", "field": "match"})
        return _err("VALIDATION_ERROR", "match is invalid", field="match")
    if entry_status is not None and entry_status not in ("active", "removed"):
        _log("error", {"code": "VALIDATION_ERROR", "message": "entry_status is invalid", "field": "entry_status"})
        return _err("VALIDATION_ERROR", "entry_status is invalid", field="entry_status")
    if record_type is not None and record_type not in ("company", "person", "custom"):
        _log("error", {"code": "VALIDATION_ERROR", "message": "record_type is invalid", "field": "record_type"})
        return _err("VALIDATION_ERROR", "record_type is invalid", field="record_type")
    if record_status is not None and record_status not in ("active", "archived", "deleted"):
        _log("error", {"code": "VALIDATION_ERROR", "message": "record_status is invalid", "field": "record_status"})
        return _err("VALIDATION_ERROR", "record_status is invalid", field="record_status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", {"code": "VALIDATION_ERROR", "message": "limit must be 1..200", "field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be 1..200", field="limit")
    if sort is None:
        sort = "added_at"
    if sort not in ("added_at", "-added_at", "updated_at", "-updated_at"):
        _log("error", {"code": "VALIDATION_ERROR", "message": "sort is invalid", "field": "sort"})
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    allowed_fields = {
        "display_name", "domain", "email", "phone", "record_type", "status",
        "attio_object", "attio_record_id", "last_interaction_at", "last_activity_at",
        "attio_created_at", "attio_updated_at", "created_at", "updated_at"
    }
    allowed_ops = {"eq", "neq", "in", "nin", "contains", "exists", "gte", "gt", "lte", "lt"}

    # Validate conditions and collect fields used (invalid key => error)
    for j, c in enumerate(parent_conditions):
        if not isinstance(c, dict):
            _log("error", {"code": "VALIDATION_ERROR", "message": f"parent_conditions[{j}] must be an object", "field": f"parent_conditions[{j}]"})
            return _err("VALIDATION_ERROR", f"parent_conditions[{j}] must be an object", field=f"parent_conditions[{j}]")
        f = c.get("field")
        op = c.get("operator")
        if f not in allowed_fields:
            _log("error", {"code": "VALIDATION_ERROR", "message": "Unsupported condition field", "field": "field", "condition_index": j, "value": f})
            return _err("VALIDATION_ERROR", "Unsupported condition field", field="field", condition_index=j, value=f)
        if op not in allowed_ops:
            _log("error", {"code": "VALIDATION_ERROR", "message": "Unsupported condition operator", "field": "operator", "condition_index": j, "value": op})
            return _err("VALIDATION_ERROR", "Unsupported condition operator", field="operator", condition_index=j, value=op)

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log("error", {"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log("error", {"code": "UNAUTHORIZED", "message": "Workspace is not active", "status": ws.get("status")})
        return _err("UNAUTHORIZED", "Workspace is not active", status=ws.get("status"))

    lists = _load("lists.json")
    if not isinstance(lists, list):
        lists = []
    lst = next((l for l in lists if isinstance(l, dict) and l.get("id") == list_id and l.get("workspace_id") == workspace_id), None)
    if lst is None:
        _log("error", {"code": "NOT_FOUND", "message": "List not found"})
        return _err("NOT_FOUND", "List not found", list_id=list_id)

    entries = _load("list_entries.json")
    if not isinstance(entries, list):
        entries = []
    records = _load("records.json")
    if not isinstance(records, list):
        records = []
    rec_by_id = {r.get("id"): r for r in records if isinstance(r, dict) and isinstance(r.get("id"), str) and r.get("workspace_id") == workspace_id}

    def _cmp(field, op, val, rec):
        rv = rec.get(field)
        if op == "exists":
            return rv is not None
        if op == "contains":
            if rv is None:
                return False
            return str(val).lower() in str(rv).lower()
        if op in ("eq", "neq", "gte", "gt", "lte", "lt"):
            # datetime-aware compare if parseable
            rdt = _parse_dt(rv)
            vdt = _parse_dt(val)
            if rdt is not None and vdt is not None:
                a, b = rdt, vdt
            else:
                a, b = rv, val
            try:
                if op == "eq": return a == b
                if op == "neq": return a != b
                if op == "gte": return a >= b
                if op == "gt": return a > b
                if op == "lte": return a <= b
                if op == "lt": return a < b
            except Exception:
                return False
        if op in ("in", "nin"):
            if not isinstance(val, list):
                return False
            ok = rv in val
            return ok if op == "in" else (not ok)
        return False

    matched = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id or e.get("list_id") != list_id:
            continue
        if entry_status is not None and e.get("status") != entry_status:
            continue
        parent = rec_by_id.get(e.get("record_id"))
        if parent is None:
            continue
        if record_type is not None and parent.get("record_type") != record_type:
            continue
        if record_status is not None and parent.get("status") != record_status:
            continue

        bools = []
        for c in parent_conditions:
            bools.append(_cmp(c.get("field"), c.get("operator"), c.get("value"), parent))
        ok = all(bools) if match == "all" else any(bools)
        if ok:
            matched.append(e)

    reverse = sort.startswith("-")
    sort_key = sort[1:] if reverse else sort

    def _dt_or_min(v):
        dt = _parse_dt(v)
        if dt is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return dt

    matched.sort(key=lambda r: _dt_or_min(r.get(sort_key)), reverse=reverse)

    cur = _decode_cursor(cursor)
    if cur == "bad":
        _log("error", {"code": "VALIDATION_ERROR", "message": "cursor is malformed", "field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    start = 0
    if isinstance(cur, dict) and cur.get("list_id") == list_id and isinstance(cur.get("offset"), int):
        start = max(0, cur["offset"])

    page = matched[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < len(matched)
    next_cursor = _encode_cursor({"list_id": list_id, "offset": next_offset}) if has_more else None

    _log("ok", {"returned": len(page), "total": len(matched), "has_more": has_more})
    return {
        "entries": page,
        "meta": {
            "total": len(matched),
            "returned": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

