        if sort not in ("added_at", "-added_at", "updated_at", "-updated_at"):
            _log(400, False)
            return _err("VALIDATION_ERROR", "sort is invalid")
        offset = _decode_cursor(cursor)
        if offset is None:
            _log(400, False)
            return _err("VALIDATION_ERROR", "cursor is invalid")
    except Exception as e:
        _log(500, False)
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log(404, False)
