        if e.get("list_id") != list_id:
            continue
        if e.get("record_id") != record_id:
            continue
        if status is not None and e.get("status") != status:
            continue
        filtered.append(e)

    key = sort.lstrip("-")
    rev = sort.startswith("-")

    def _sort_key(e):
        v = e.get(key)
        return v if isinstance(v, str) else ""

    filtered.sort(key=_sort_key, reverse=rev)

    total = len(filtered)
