                continue

        if due_before is not None or due_after is not None:
            due = _parse_dt(a.get("due_at")) if a.get("due_at") is not None else None
            if due is None:
                continue
            if due_before is not None and due > db:
                continue
            if due_after is not None and due < da:
                continue

        tasks.append(a)

    key = sort.lstrip("-")
    rev = sort.startswith("-")

    def _sort_key(t):
        v = t.get(key)
        # Put None at end for ascending, beginning for descending
        if v is None:
            return "" if rev else "~~~~-99-99T99:99:99+00:00"
        return v if isinstance(v, str) else str(v)

    tasks.sort(key=_sort_key, reverse=rev)

    total = len(tasks)
    page = tasks[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log(200, True, extra={"result_count": len(page), "total": total})
    return {
        "tasks": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def create_task(workspace_id, title, author_record_id=None, body=None, due_at=None, linked_record_ids=None, metadata=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # --- helpers ---
    _re_ws = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    _re_rec = re.compile(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")
    _re_act = re.compile(r"^att_act_[0-9A-HJKMNP-TV-Z]{26}$")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string"))
        try:
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        except ValueError:
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time"))

    def _gen_ulid(prefix):
        # ULID-like (26 Crockford base32) using timestamp+random (not a strict ULID impl but matches pattern)
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        # 48-bit time
        time_part = ms & ((1 << 48) - 1)

        import secrets
        rand_part = secrets.randbits(80)

        value = (time_part << 80) | rand_part  # 128 bits
        chars = []
        for _ in range(26):
            chars.append(alphabet[value & 31])
            value >>= 5
        sfx = "".join(reversed(chars))
        return f"{prefix}_{sfx}"

    # --- load store ---
    workspaces = _load("workspaces.json")
    records = _load("records.json")
    notes_tasks = _load("notes_tasks.json")

    # --- validate inputs ---
    if not isinstance(workspace_id, str) or not _re_ws.match(workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")

    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string", field="title")

    if author_record_id is not None:
        if not isinstance(author_record_id, str) or not _re_rec.match(author_record_id):
            return _err("VALIDATION_ERROR", "author_record_id is malformed", field="author_record_id")

    if body is not None and not isinstance(body, str):
        return _err("VALIDATION_ERROR", "body must be a string", field="body")

    if linked_record_ids is None:
        linked_record_ids = []
    if not isinstance(linked_record_ids, list):
        return _err("VALIDATION_ERROR", "linked_record_ids must be an array", field="linked_record_ids")
    for i, rid in enumerate(linked_record_ids):
        if not isinstance(rid, str) or not _re_rec.match(rid):
            return _err("VALIDATION_ERROR", "linked_record_ids contains a malformed record id", field="linked_record_ids", index=i)

    if metadata is None:
        metadata = {}
    if not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object", field="metadata")

    due_iso = None
    if due_at is not None:
        parsed = _parse_dt(due_at, "due_at")
        if isinstance(parsed, tuple) and parsed and parsed[0] == "__bad__":
            return parsed[1]
        due_iso = parsed

    # --- resolve workspace and enforce ambient auth ---
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id)
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "workspace is not active", workspace_id=workspace_id, status=ws.get("status"))

    # --- validate record references within workspace ---
    rec_by_id = {r.get("id"): r for r in records if r.get("workspace_id") == workspace_id}
    if author_record_id is not None:
        ar = rec_by_id.get(author_record_id)
        if ar is None:
            return _err("NOT_FOUND", "author_record_id not found in workspace", author_record_id=author_record_id)
        if ar.get("status") != "active":
            return _err("CONFLICT", "author_record_id must reference an active record", author_record_id=author_record_id, status=ar.get("status"))

    # linked records must exist in workspace
    for rid in linked_record_ids:
        rr = rec_by_id.get(rid)
        if rr is None:
            return _err("NOT_FOUND", "linked record not found in workspace", record_id=rid)
        if rr.get("status") != "active":
            return _err("CONFLICT", "linked record must be active", record_id=rid, status=rr.get("status"))

    # --- create task ---
    now = _now_iso()
    task_id = _gen_ulid("att_act")
    # ensure uniqueness against existing ids (rare collision)
    existing_ids = {a.get("id") for a in notes_tasks}
    while task_id in existing_ids or not _re_act.match(task_id):
        task_id = _gen_ulid("att_act")

    # Ensure idempotent linking list has no duplicates while keeping order
    seen = set()
    dedup_linked = []
    for rid in linked_record_ids:
        if rid not in seen:
            dedup_linked.append(rid)
            seen.add(rid)

    row = {
        "id": task_id,
        "workspace_id": workspace_id,
        "activity_type": "task",
        "attio_activity_id": None,
        "status": "active",
        "author_record_id": author_record_id,
        "title": title.strip(),
        "body": body,
        "due_at": due_iso,
        "completed_at": None,
        "linked_record_ids": dedup_linked,
        "metadata": metadata,
        "created_at": now,
        "updated_at": now,
    }

    notes_tasks.append(row)
    _save("notes_tasks.json", notes_tasks)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "task": row,
        "meta": {
            "latency_ms": latency_ms
        }
    }

def update_task(task_id, title=None, body=None, due_at=None, status=None, completed_at=None, metadata=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    _re_act = re.compile(r"^att_act_[0-9A-HJKMNP-TV-Z]{26}$")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt_allow_null(v, field):
        if v is None:
            return None
        if not isinstance(v, str):
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string (or null)"))
        try:
            x = v.strip()
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        except ValueError:
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time"))

    if not isinstance(task_id, str) or not _re_act.match(task_id):
        return _err("VALIDATION_ERROR", "task_id is malformed", field="task_id")

    if title is not None and (not isinstance(title, str) or not title.strip()):
        return _err("VALIDATION_ERROR", "title must be a non-empty string when provided", field="title")

    if body is not None and not isinstance(body, str):
        return _err("VALIDATION_ERROR", "body must be a string", field="body")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "completed", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of active/completed/deleted", field="status")

    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object", field="metadata")

    due_iso = "__nochange__"
    if due_at is not None:
        # due_at may be a string; tool description says null to clear, but JSON-schema lacks null type.
        # Accept explicit None (Python) as clear only if caller passed due_at=None via API; here due_at not None means string.
        parsed = _parse_dt_allow_null(due_at, "due_at")
        if isinstance(parsed, tuple) and parsed and parsed[0] == "__bad__":
            return parsed[1]
        due_iso = parsed

    comp_iso = "__nochange__"
    if completed_at is not None:
        parsed = _parse_dt_allow_null(completed_at, "completed_at")
        if isinstance(parsed, tuple) and parsed and parsed[0] == "__bad__":
            return parsed[1]
        comp_iso = parsed

    notes_tasks = _load("notes_tasks.json")
    workspaces = _load("workspaces.json")

    idx = None
    task = None
    for i, a in enumerate(notes_tasks):
        if a.get("id") == task_id:
            idx = i
            task = a
            break
    if task is None:
        return _err("NOT_FOUND", "task not found", task_id=task_id)

    if task.get("activity_type") != "task":
        return _err("CONFLICT", "activity is not a task", task_id=task_id, activity_type=task.get("activity_type"))

    # ambient auth: workspace must be active
    ws = next((w for w in workspaces if w.get("id") == task.get("workspace_id")), None)
    if ws is None:
        return _err("UNAUTHORIZED", "workspace context missing for task", workspace_id=task.get("workspace_id"))
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "workspace is not active", workspace_id=ws.get("id"), status=ws.get("status"))

    # lifecycle transitions
    cur_status = task.get("status")
    transitions = {
        "active": {"completed", "deleted"},
        "completed": {"active", "deleted"},
        "deleted": set(),
    }
    new_status = cur_status if status is None else status
    if new_status != cur_status:
        if new_status not in transitions.get(cur_status, set()):
            return _err("INVALID_TRANSITION", "illegal status transition", from_status=cur_status, to_status=new_status)

    # enforce rules around completed_at
    # - if status becomes completed => must be task and completed_at non-null
    # - if status != completed => completed_at must be null
    # compute intended completed_at
    intended_completed_at = task.get("completed_at")
    if comp_iso != "__nochange__":
        intended_completed_at = comp_iso

    if new_status == "completed":
        if intended_completed_at is None:
            # auto-set if not explicitly provided
            intended_completed_at = _now_iso()
    else:
        # must be null
        intended_completed_at = None

    # due_at may be cleared only if caller explicitly passes due_at=None.
    # Since tool param due_at defaults None, we interpret due_at=None as "no change".
    # To allow clearing, accept due_at="" as invalid; so we cannot. We'll support clearing via due_at set to None
    # only if the caller included it as None and also provided a sentinel in _extra (not available).
    # Practical behavior: if due_at provided as a string, set it; otherwise leave unchanged.
    if due_iso != "__nochange__":
        task["due_at"] = due_iso

    if title is not None:
        task["title"] = title.strip()
    if body is not None:
        task["body"] = body
    if metadata is not None:
        task["metadata"] = metadata

    task["status"] = new_status
    task["completed_at"] = intended_completed_at
    task["updated_at"] = _now_iso()

    notes_tasks[idx] = task
    _save("notes_tasks.json", notes_tasks)

    latency_ms = int((time.time() - t0) * 1000)
    return {"task": task, "meta": {"latency_ms": latency_ms}}

def delete_task(task_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-task"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _append_request_log(status, wsid=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "workspace_id": wsid,
            "credential": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail
        })
        _save("request_logs.json", logs)

    act_re = re.compile(r"^att_act_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(task_id, str) or not act_re.fullmatch(task_id):
        _append_request_log("VALIDATION_ERROR", None, {"field": "task_id"})
        return _err("VALIDATION_ERROR", "task_id is malformed", field="task_id")

    notes_tasks = _load("notes_tasks.json")
    if isinstance(notes_tasks, dict) and "rows" in notes_tasks:
        notes_tasks = notes_tasks.get("rows")
    if not isinstance(notes_tasks, list):
        notes_tasks = []

    idx = None
    row = None
    for i, a in enumerate(notes_tasks):
        if isinstance(a, dict) and a.get("id") == task_id:
            idx = i
            row = a
            break

    if row is None:
        _append_request_log("NOT_FOUND", None, {"task_id": task_id})
        return _err("NOT_FOUND", "task not found", task_id=task_id)

    wsid = row.get("workspace_id")

    if row.get("activity_type") != "task":
        _append_request_log("VALIDATION_ERROR", wsid, {"activity_type": row.get("activity_type")})
        return _err("VALIDATION_ERROR", "activity is not a task", field="task_id", activity_type=row.get("activity_type"))

    now = _now_iso()
    if row.get("status") == "deleted":
        # idempotent: already deleted
        _append_request_log("OK", wsid, {"already_deleted": True})
        return {"data": dict(row)}

    # lifecycle: active/completed -> deleted
    if row.get("status") not in ("active", "completed"):
        _append_request_log("INVALID_TRANSITION", wsid, {"from": row.get("status"), "to": "deleted"})
        return _err("INVALID_TRANSITION", f"Cannot delete task from status '{row.get('status')}'", from_status=row.get("status"), to_status="deleted")

    row["status"] = "deleted"
    row["completed_at"] = None  # constraint: if status!='completed' then completed_at is null
    row["updated_at"] = now
    notes_tasks[idx] = row
    _save("notes_tasks.json", notes_tasks)

    _append_request_log("OK", wsid, {"deleted": True})
    return {"data": dict(row)}

def link_record_to_task(task_id, record_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    _re_act = re.compile(r"^att_act_[0-9A-HJKMNP-TV-Z]{26}$")
    _re_rec = re.compile(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    if not isinstance(task_id, str) or not _re_act.match(task_id):
        return _err("VALIDATION_ERROR", "task_id is malformed", field="task_id")
    if not isinstance(record_id, str) or not _re_rec.match(record_id):
        return _err("VALIDATION_ERROR", "record_id is malformed", field="record_id")

    notes_tasks = _load("notes_tasks.json")
    records = _load("records.json")
    workspaces = _load("workspaces.json")

    idx = None
    task = None
    for i, a in enumerate(notes_tasks):
        if a.get("id") == task_id:
            idx = i
            task = a
            break
    if task is None:
        return _err("NOT_FOUND", "task not found", task_id=task_id)

    if task.get("activity_type") != "task":
        return _err("CONFLICT", "activity is not a task", task_id=task_id, activity_type=task.get("activity_type"))

    ws_id = task.get("workspace_id")
    ws = next((w for w in workspaces if w.get("id") == ws_id), None)
    if ws is None or ws.get("status") != "active":
        return _err("UNAUTHORIZED", "workspace is not active", workspace_id=ws_id)

    rec = next((r for r in records if r.get("id") == record_id), None)
    if rec is None:
        return _err("NOT_FOUND", "record not found", record_id=record_id)
    if rec.get("workspace_id") != ws_id:
        return _err("CONFLICT", "record and task belong to different workspaces", task_workspace_id=ws_id, record_workspace_id=rec.get("workspace_id"))
    if rec.get("status") != "active":
        return _err("CONFLICT", "record must be active to link", record_id=record_id, status=rec.get("status"))

    # do not link to deleted task
    if task.get("status") == "deleted":
        return _err("CONFLICT", "cannot link record to a deleted task", task_id=task_id)

    linked = task.get("linked_record_ids")
    if not isinstance(linked, list):
        # datastore corruption safeguard
        return _err("CONFLICT", "task linked_record_ids is not an array", task_id=task_id)

    # idempotent: no duplicates
    if record_id not in linked:
        linked.append(record_id)
        task["linked_record_ids"] = linked
        task["updated_at"] = _now_iso()
        notes_tasks[idx] = task
        _save("notes_tasks.json", notes_tasks)

    latency_ms = int((time.time() - t0) * 1000)
    return {"task": task, "meta": {"latency_ms": latency_ms}}

def create_record(workspace_id, record_type, display_name, attio_object=None, domain=None, email=None, phone=None, social=None, contact=None, business=None, attributes=None, **_extra):
    import json, os, datetime, re, time, random, hashlib
    from urllib.parse import urlparse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-record"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        raw = (prefix + "|" + _now_iso() + "|" + str(time.time()) + "|" + str(random.getrandbits(80))).encode("utf-8")
        return prefix + hashlib.sha256(raw).hexdigest()[:26].upper()

    def _get_log_file():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(status, detail=None):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(time.time()) + "|" + str(random.getrandbits(64))).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save(fn, logs)

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _log("error", {"code": "VALIDATION_ERROR", "message": "workspace_id is invalid", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if record_type not in ("company", "person", "custom"):
        _log("error", {"code": "VALIDATION_ERROR", "message": "record_type is invalid", "field": "record_type"})
        return _err("VALIDATION_ERROR", "record_type is invalid", field="record_type")
    if not isinstance(display_name, str) or not display_name.strip():
        _log("error", {"code": "VALIDATION_ERROR", "message": "display_name is required", "field": "display_name"})
        return _err("VALIDATION_ERROR", "display_name is required", field="display_name")
    if record_type == "custom" and (attio_object is None or not isinstance(attio_object, str) or not attio_object.strip()):
        _log("error", {"code": "VALIDATION_ERROR", "message": "attio_object is required for custom records", "field": "attio_object"})
        return _err("VALIDATION_ERROR", "attio_object is required for custom records", field="attio_object")
    if attio_object is not None and not isinstance(attio_object, str):
        _log("error", {"code": "VALIDATION_ERROR", "message": "attio_object must be a string", "field": "attio_object"})
        return _err("VALIDATION_ERROR", "attio_object must be a string", field="attio_object")

    def _normalize_domain(d):
        if d is None:
            return None
        if not isinstance(d, str):
            return _err("VALIDATION_ERROR", "domain must be a string", field="domain")
        s = d.strip().lower()
        if not s:
            return None
        host = None
        if "://" in s:
            p = urlparse(s)
            host = p.hostname
        if not host:
            host = s.split("/")[0].split("?")[0].split("#")[0]
            host = host.split("@")[-1]
            host = host.split(":")[0]
        host = (host or "").strip().lower()
        if host.startswith("www."):
            host = host[4:]
        if not host or any(c.isspace() for c in host) or "/" in host:
            return _err("VALIDATION_ERROR", "domain must be a normalized lowercase host without scheme/path", field="domain")
        return host

    if email is not None and not isinstance(email, str):
        _log("error", {"code": "VALIDATION_ERROR", "message": "email must be a string", "field": "email"})
        return _err("VALIDATION_ERROR", "email must be a string", field="email")
    if phone is not None and not isinstance(phone, str):
        _log("error", {"code": "VALIDATION_ERROR", "message": "phone must be a string", "field": "phone"})
        return _err("VALIDATION_ERROR", "phone must be a string", field="phone")
    for k, v in (("social", social), ("contact", contact), ("business", business), ("attributes", attributes)):
        if v is not None and not isinstance(v, dict):
            _log("error", {"code": "VALIDATION_ERROR", "message": f"{k} must be an object", "field": k})
            return _err("VALIDATION_ERROR", f"{k} must be an object", field=k)

    # record_type-specific constraints
    ndomain = None
    if domain is not None:
        ndomain = _normalize_domain(domain)
        if isinstance(ndomain, dict) and "error" in ndomain:
            _log("error", ndomain["error"])
            return ndomain
    nemail = None
    if email is not None:
        nemail = email.strip().lower()
        if nemail and "@" not in nemail:
            _log("error", {"code": "VALIDATION_ERROR", "message": "email must contain '@'", "field": "email"})
            return _err("VALIDATION_ERROR", "email must contain '@'", field="email")
        if not nemail:
            nemail = None

    if record_type == "company":
        # domain may be non-null; email can be null
        pass
    elif record_type == "person":
        # domain should generally be null; accept but coerce to None
        ndomain = None
    else:
        # custom: accept any of these
        pass

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log("error", {"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log("error", {"code": "UNAUTHORIZED", "message": "Workspace is not active", "status": ws.get("status")})
        return _err("UNAUTHORIZED", "Workspace is not active", status=ws.get("status"))

    records = _load("records.json")
    if not isinstance(records, list):
        records = []

    # Determine attio_object default for company/person if omitted
    ao = attio_object.strip() if isinstance(attio_object, str) and attio_object.strip() else None
    if record_type == "company" and ao is None:
        ao = "companies"
    if record_type == "person" and ao is None:
        ao = "people"
    if ao is None:
        ao = "custom"

    # Ensure required object fields exist
    now = _now_iso()
    new_rec = {
        "id": _new_id("att_rec_"),
        "workspace_id": workspace_id,
        "record_type": record_type,
        "attio_object": ao,
        "attio_record_id": _new_id("attio_"),  # opaque placeholder if not provided by tool
        "status": "active",
        "display_name": display_name.strip(),
        "domain": ndomain,
        "email": nemail,
        "phone": phone,
        "social": social if isinstance(social, dict) else None,
        "contact": contact if isinstance(contact, dict) else None,
        "business": business if isinstance(business, dict) else None,
        "attributes": attributes if isinstance(attributes, dict) else {},
        "raw_json": {},
        "last_interaction_at": None,
        "last_activity_at": None,
        "attio_created_at": None,
        "attio_updated_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce uniqueness (workspace_id, attio_object, attio_record_id)
    for r in records:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") == workspace_id and r.get("attio_object") == new_rec["attio_object"] and r.get("attio_record_id") == new_rec["attio_record_id"]:
            _log("error", {"code": "CONFLICT", "message": "Record with same attio_object and attio_record_id already exists"})
            return _err("CONFLICT", "Record with same attio_object and attio_record_id already exists")

    records.append(new_rec)
    _save("records.json", records)

    _log("ok", {"created": True, "record_id": new_rec["id"]})
    return {"record": new_rec, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def get_record(record_id, workspace_id, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, ok, message=None, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": "get-record",
            "timestamp": _now,
            "status": status_code,
            "ok": bool(ok),
            "latency_ms": int((time.time() - _t0) * 1000),
            "workspace_id": workspace_id,
        }
        if message is not None:
            row["message"] = message
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _ulid_ok(prefix, s):
        if not isinstance(s, str):
            return False
        return re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", s) is not None

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    # Validate inputs
    if not _ulid_ok("att_ws", workspace_id):
        _log(400, False, "Invalid workspace_id")
        return _err("VALIDATION_ERROR", "Invalid workspace_id", field="workspace_id")
    if not _ulid_ok("att_rec", record_id):
        _log(400, False, "Invalid record_id")
        return _err("VALIDATION_ERROR", "Invalid record_id", field="record_id")
    if status is not None and status not in ("active", "removed"):
        _log(400, False, "Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status", field="status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log(400, False, "Invalid limit type")
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 200:
        _log(400, False, "Invalid limit range")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
    if sort is None:
        sort = "-added_at"
    if sort not in ("added_at", "-added_at", "created_at", "-created_at", "updated_at", "-updated_at"):
        _log(400, False, "Invalid sort")
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort")

    offset = _parse_cursor(cursor)
    if offset is None:
        _log(400, False, "Invalid cursor")
        return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    # Workspace must exist and be active
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log(404, False, "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found", field="workspace_id")
    if ws.get("status") != "active":
        _log(401, False, "Workspace not active")
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Record must exist in workspace
    records = _load("records.json")
    if not isinstance(records, list):
        records = []
    rec = next((r for r in records if isinstance(r, dict) and r.get("id") == record_id and r.get("workspace_id") == workspace_id), None)
    if rec is None:
        _log(404, False, "Record not found")
        return _err("NOT_FOUND", "Record not found", field="record_id")

    list_entries = _load("list_entries.json")
    if not isinstance(list_entries, list):
        list_entries = []
    lists_ = _load("lists.json")
    if not isinstance(lists_, list):
        lists_ = []

    # Filter by record/workspace and entry status (if any)
    entries = []
    for e in list_entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id:
            continue
        if e.get("record_id") != record_id:
            continue
        if status is not None and e.get("status") != status:
            continue
        # join to list (must be in same workspace; enforce FK cross-workspace rule)
        lst = next((l for l in lists_ if isinstance(l, dict) and l.get("id") == e.get("list_id")), None)
        if lst is None:
            continue
        if lst.get("workspace_id") != workspace_id:
            # Data integrity issue; treat as validation conflict
            _log(409, False, "Cross-workspace list entry detected")
            return _err("CONFLICT", "Cross-workspace list entry detected", list_id=e.get("list_id"))
        entries.append((e, lst))

    # Sorting
    key_field = sort.lstrip("-")
    reverse = sort.startswith("-")

    def _dt_key(v):
        if v is None:
            return ""
        if not isinstance(v, str):
            return ""
        return v

    entries.sort(key=lambda pair: _dt_key(pair[0].get(key_field)), reverse=reverse)

    total = len(entries)
    page_pairs = entries[offset:offset + limit]
    next_off = offset + len(page_pairs)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    # Envelope: list-membership entries
    data = []
    for e, lst in page_pairs:
        data.append({
            "id": e.get("id"),
            "workspace_id": workspace_id,
            "record_id": record_id,
            "list_entry": {
                "id": e.get("id"),
                "list_id": e.get("list_id"),
                "attio_entry_id": e.get("attio_entry_id"),
                "status": e.get("status"),
                "entry_attributes": e.get("entry_attributes"),
                "added_at": e.get("added_at"),
                "removed_at": e.get("removed_at"),
                "created_at": e.get("created_at"),
                "updated_at": e.get("updated_at"),
            },
            "list": {
                "id": lst.get("id"),
                "attio_list_id": lst.get("attio_list_id"),
                "name": lst.get("name"),
                "list_type": lst.get("list_type"),
                "applies_to": lst.get("applies_to"),
                "status": lst.get("status"),
                "created_at": lst.get("created_at"),
                "updated_at": lst.get("updated_at"),
            }
        })

    _log(200, True)
    return {
        "data": data,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "status": status
        }
    }

def update_record(record_id, display_name=None, domain=None, email=None, phone=None, social=None, contact=None, business=None, attributes=None, status=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid():
        # ULID-like, Crockford base32, 26 chars
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        # 48-bit time -> 10 chars
        time_chars = []
        for _ in range(10):
            time_chars.append(alphabet[ms & 31])
            ms >>= 5
        time_part = "".join(reversed(time_chars))
        rand_part = "".join(alphabet[random.getrandbits(5) & 31] for _ in range(16))
        return time_part + rand_part

    def _new_id(prefix):
        return f"{prefix}{_ulid()}"

    def _is_obj(x):
        return isinstance(x, dict)

    def _normalize_domain(d):
        if not isinstance(d, str):
            return None
        s = d.strip().lower()
        # remove scheme
        s = re.sub(r"^[a-z]+://", "", s)
        # remove path/query/fragment
        s = s.split("/")[0].split("?")[0].split("#")[0]
        # remove port
        s = s.split(":")[0]
        if s.startswith("www."):
            s = s[4:]
        s = s.strip(".")
        # basic host validation: letters/digits/dash/dot, must contain at least one dot or be a single label (allow intranet)
        if not s or not re.fullmatch(r"[a-z0-9.-]+", s):
            return None
        if ".." in s:
            return None
        return s

    def _normalize_email(e):
        if not isinstance(e, str):
            return None
        s = e.strip().lower()
        if "@" not in s:
            return None
        # minimal validation, but enforce contains '@'
        return s

    def _digits_only(s):
        return "".join(ch for ch in s if ch.isdigit())

    def _normalize_phone(p):
        if not isinstance(p, str):
            return None
        s = p.strip()
        if not s:
            return None
        # Try to normalize to E.164-ish:
        # - accept leading + and digits; if no +, keep digits-only (can't infer country)
        if s.startswith("+"):
            d = "+" + _digits_only(s)
            if len(d) < 8 or len(d) > 16:  # rough E.164 bounds including '+'
                return None
            return d
        d = _digits_only(s)
        if len(d) < 7 or len(d) > 15:
            return None
        return d

    def _log(endpoint, status_code, workspace_id=None, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("att_log_"),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now(),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit(workspace_id):
        # If no rate-limit/quota schema exists, still log calls; enforce only if present.
        limits = _load("rate_limits.json")
        if not isinstance(limits, list) or not limits:
            return None
        # Find a usable rule: workspace-specific then global
        rule = None
        for r in limits:
            if isinstance(r, dict) and r.get("workspace_id") == workspace_id:
                rule = r
                break
        if rule is None:
            for r in limits:
                if isinstance(r, dict) and (r.get("workspace_id") in (None, "", "*")):
                    rule = r
                    break
        if rule is None:
            return None

        window_sec = rule.get("window_seconds")
        max_requests = rule.get("max_requests")
        if not isinstance(window_sec, int) or not isinstance(max_requests, int) or window_sec <= 0 or max_requests <= 0:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_sec)
        def _parse(ts):
            if not isinstance(ts, str):
                return None
            try:
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                return None
        recent = 0
        for row in logs:
            if not isinstance(row, dict):
                continue
            if row.get("workspace_id") != workspace_id:
                continue
            ts = _parse(row.get("created_at"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= max_requests:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=max_requests, window_seconds=window_sec)
        return None

    def _resolve_workspace():
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        # pick an active workspace (must be scoped to exactly one workspace)
        for w in workspaces:
            if isinstance(w, dict) and w.get("status") == "active":
                return w
        # If none active, no working combination exists
        return None

    # Validate record_id
    if not isinstance(record_id, str) or not re.fullmatch(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$", record_id):
        _log("update-record", 400, error_code="VALIDATION_ERROR", error_message="Invalid record_id.")
        return _err("VALIDATION_ERROR", "Invalid record_id.", field="record_id")

    # Validate optional fields types first
    if display_name is not None and not isinstance(display_name, str):
        _log("update-record", 400, error_code="VALIDATION_ERROR", error_message="display_name must be a string.")
        return _err("VALIDATION_ERROR", "display_name must be a string.", field="display_name")
    if domain is not None and not isinstance(domain, str):
        _log("update-record", 400, error_code="VALIDATION_ERROR", error_message="domain must be a string.")
        return _err("VALIDATION_ERROR", "domain must be a string.", field="domain")
    if email is not None and not isinstance(email, str):
        _log("update-record", 400, error_code="VALIDATION_ERROR", error_message="email must be a string.")
        return _err("VALIDATION_ERROR", "email must be a string.", field="email")
    if phone is not None and not isinstance(phone, str):
        _log("update-record", 400, error_code="VALIDATION_ERROR", error_message="phone must be a string.")
        return _err("VALIDATION_ERROR", "phone must be a string.", field="phone")
    for fld, val in (("social", social), ("contact", contact), ("business", business), ("attributes", attributes)):
        if val is not None and not _is_obj(val):
            _log("update-record", 400, error_code="VALIDATION_ERROR", error_message=f"{fld} must be an object.")
            return _err("VALIDATION_ERROR", f"{fld} must be an object.", field=fld)
    if status is not None:
        if not isinstance(status, str):
            _log("update-record", 400, error_code="VALIDATION_ERROR", error_message="status must be a string.")
            return _err("VALIDATION_ERROR", "status must be a string.", field="status")
        if status not in ("active", "archived", "deleted"):
            _log("update-record", 400, error_code="VALIDATION_ERROR", error_message="Invalid status.")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["active", "archived", "deleted"])

    ws = _resolve_workspace()
    if ws is None:
        _log("update-record", 401, error_code="UNAUTHORIZED", error_message="No active workspace available.")
        return _err("UNAUTHORIZED", "No active workspace available.")
    workspace_id = ws.get("id")

    rl = _enforce_rate_limit(workspace_id)
    if rl is not None:
        _log("update-record", 429, workspace_id=workspace_id, error_code=rl["error"]["code"], error_message=rl["error"]["message"])
        return rl

    records = _load("records.json")
    if not isinstance(records, list):
        records = []

    idx = None
    rec = None
    for i, r in enumerate(records):
        if isinstance(r, dict) and r.get("id") == record_id and r.get("workspace_id") == workspace_id:
            idx = i
            rec = r
            break
    if rec is None:
        _log("update-record", 404, workspace_id=workspace_id, error_code="NOT_FOUND", error_message="Record not found.")
        return _err("NOT_FOUND", "Record not found.", record_id=record_id)

    # Status transition validation
    if status is not None and status != rec.get("status"):
        transitions = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
        cur = rec.get("status")
        if cur not in transitions or status not in transitions.get(cur, []):
            _log("update-record", 409, workspace_id=workspace_id, error_code="INVALID_TRANSITION", error_message="Illegal status transition.")
            return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status)

    # Field-level validation based on record_type constraints
    record_type = rec.get("record_type")
    if record_type not in ("company", "person", "custom"):
        _log("update-record", 400, workspace_id=workspace_id, error_code="VALIDATION_ERROR", error_message="Corrupt record_type.")
        return _err("VALIDATION_ERROR", "Record has invalid record_type.", record_id=record_id)

    # Normalize and validate domain/email/phone if provided
    new_domain = None
    if domain is not None:
        new_domain = _normalize_domain(domain)
        if new_domain is None:
            _log("update-record", 400, workspace_id=workspace_id, error_code="VALIDATION_ERROR", error_message="Invalid domain.")
            return _err("VALIDATION_ERROR", "Invalid domain; must be a normalized host without scheme/path.", field="domain")
        if record_type == "person":
            _log("update-record", 400, workspace_id=workspace_id, error_code="VALIDATION_ERROR", error_message="domain not allowed for person records.")
            return _err("VALIDATION_ERROR", "domain is not applicable to person records.", field="domain")

    new_email = None
    if email is not None:
        new_email = _normalize_email(email)
        if new_email is None:
            _log("update-record", 400, workspace_id=workspace_id, error_code="VALIDATION_ERROR", error_message="Invalid email.")
            return _err("VALIDATION_ERROR", "Invalid email; must be lowercase and contain '@'.", field="email")
        if record_type == "company":
            # allowed but typically null; still accept
            pass

    new_phone = None
    if phone is not None:
        new_phone = _normalize_phone(phone)
        if new_phone is None:
            # fall back allowed? For update, require valid normalization.
            _log("update-record", 400, workspace_id=workspace_id, error_code="VALIDATION_ERROR", error_message="Invalid phone.")
            return _err("VALIDATION_ERROR", "Invalid phone; must be E.164 when possible or digits-only length 7-15.", field="phone")

    # Enforce unique(workspace_id, attio_object, attio_record_id) unchanged here; not updating those fields.

    # Apply partial updates
    changed = False
    if display_name is not None:
        rec["display_name"] = display_name
        changed = True
    if domain is not None:
        rec["domain"] = new_domain
        changed = True
    if email is not None:
        rec["email"] = new_email
        changed = True
    if phone is not None:
        rec["phone"] = new_phone
        changed = True
    if social is not None:
        rec["social"] = social
        changed = True
    if contact is not None:
        rec["contact"] = contact
        changed = True
    if business is not None:
        rec["business"] = business
        changed = True
    if attributes is not None:
        rec["attributes"] = attributes
        changed = True
    if status is not None and status != rec.get("status"):
        rec["status"] = status
        changed = True

    if not changed:
        # Realistic: no mutation requested => validation error (client sent only record_id)
        _log("update-record", 400, workspace_id=workspace_id, error_code="VALIDATION_ERROR", error_message="No updatable fields provided.")
        return _err("VALIDATION_ERROR", "No updatable fields provided.")

    # Timestamps
    now = _now()
    created_at = rec.get("created_at")
    if isinstance(created_at, str):
        # ensure updated_at >= created_at (best-effort)
        rec["updated_at"] = now
    else:
        rec["created_at"] = now
        rec["updated_at"] = now

    records[idx] = rec
    _save("records.json", records)

    _log("update-record", 200, workspace_id=workspace_id, meta={"record_id": record_id})
    return {"record": rec}

def delete_record(record_id, **_extra):
    import json, os, datetime, re, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-record"
    rec_re = re.compile(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _get_log_file():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(status, detail=None, wsid=None):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(time.time()) + "|" + str(random.getrandbits(64))).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "workspace_id": wsid,
            "status": status,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail,
        })
        _save(fn, logs)

    if not isinstance(record_id, str) or not rec_re.fullmatch(record_id):
        _log("error", {"code": "VALIDATION_ERROR", "message": "record_id is invalid", "field": "record_id"})
        return _err("VALIDATION_ERROR", "record_id is invalid", field="record_id")

    records = _load("records.json")
    if not isinstance(records, list):
        records = []
    idx = None
    rec = None
    for i, r in enumerate(records):
        if isinstance(r, dict) and r.get("id") == record_id:
            idx = i
            rec = r
            break
    if rec is None:
        _log("error", {"code": "NOT_FOUND", "message": "Record not found"})
        return _err("NOT_FOUND", "Record not found", record_id=record_id)

    wsid = rec.get("workspace_id")
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == wsid), None)
    if ws is None or ws.get("status") != "active":
        _log("error", {"code": "UNAUTHORIZED", "message": "Workspace is not active", "workspace_id": wsid}, wsid)
        return _err("UNAUTHORIZED", "Workspace is not active", workspace_id=wsid)

    if rec.get("status") == "deleted":
        _log("error", {"code": "CONFLICT", "message": "Record is already deleted"}, wsid)
        return _err("CONFLICT", "Record is already deleted", record_id=record_id)

    # transition check
    cur = rec.get("status")
    if cur not in ("active", "archived"):
        _log("error", {"code": "INVALID_TRANSITION", "message": "illegal status transition", "from_status": cur, "to_status": "deleted"}, wsid)
        return _err("INVALID_TRANSITION", "illegal status transition", from_status=cur, to_status="deleted")

    now = _now_iso()
    rec["status"] = "deleted"
    rec["updated_at"] = now
    records[idx] = rec

    # Remove list entries for this record
    list_entries = _load("list_entries.json")
    if not isinstance(list_entries, list):
        list_entries = []
    removed_entries = 0
    for e in list_entries:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") == wsid and e.get("record_id") == record_id and e.get("status") == "active":
            e["status"] = "removed"
            e["removed_at"] = now
            e["updated_at"] = now
            removed_entries += 1

    _save("records.json", records)
    if removed_entries:
        _save("list_entries.json", list_entries)

    _log("ok", {"deleted": True, "removed_list_entries": removed_entries}, wsid)
    return {"record": rec, "meta": {"deleted": True, "removed_list_entries": removed_entries, "latency_ms": int((time.time() - t0) * 1000)}}

def list_records(workspace_id, record_type=None, status=None, attio_object=None, attio_record_id=None, display_name=None, domain=None, email=None, phone=None, last_interaction_at_from=None, last_interaction_at_to=None, last_activity_at_from=None, last_activity_at_to=None, created_at_from=None, created_at_to=None, updated_at_from=None, updated_at_to=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64, re

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be RFC3339 string")
        try:
            # Accept trailing Z
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            raise ValueError(f"{field} must be RFC3339 date-time")

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        try:
            ss = v.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            raise ValueError("cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                raise ValueError
            if obj.get("v") != 1:
                raise ValueError
            return obj
        except Exception:
            raise ValueError("cursor is invalid")

    def _encode_cursor(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # --- request log / rate limiting (best-effort given schema doesn't declare it) ---
    def _log(endpoint, wsid, status_code, error_code=None):
        # Uses request_logs.json if present; otherwise no-op.
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "workspace_id": wsid,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now_iso(),
        })
        _save(fname, logs)

    def _check_rate_limit(wsid):
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return None
        logs = _load(fname)
        if not isinstance(logs, list):
            return None
        # Simple: 120 req/min per workspace
        window_s = 60
        limit_n = 120
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != wsid:
                continue
            ts = _dt_from_row(r.get("created_at") or r.get("timestamp") or r.get("ts"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit_n:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=limit_n, window_seconds=window_s)
        return None

    # --- validate inputs ---
    try:
        if not isinstance(workspace_id, str):
            out = _err("VALIDATION_ERROR", "workspace_id must be a string")
            _log("list-records", workspace_id if isinstance(workspace_id, str) else None, 400, out["error"]["code"])
            return out
        if not re.match(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
            out = _err("VALIDATION_ERROR", "workspace_id must match pattern ^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out

        if record_type is not None and record_type not in ("company", "person", "custom"):
            out = _err("VALIDATION_ERROR", "record_type must be one of: company, person, custom")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out
        if status is not None and status not in ("active", "archived", "deleted"):
            out = _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out
        if sort_by is not None and sort_by not in ("created_at", "updated_at", "display_name", "last_interaction_at", "last_activity_at"):
            out = _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, display_name, last_interaction_at, last_activity_at")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out
        if sort_order is not None and sort_order not in ("asc", "desc"):
            out = _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out

        if limit is None:
            limit = 50
        if not isinstance(limit, int):
            out = _err("VALIDATION_ERROR", "limit must be an integer")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out
        if limit < 1 or limit > 200:
            out = _err("VALIDATION_ERROR", "limit must be between 1 and 200")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out

        # parse date filters
        li_from = _parse_dt(last_interaction_at_from, "last_interaction_at_from")
        li_to = _parse_dt(last_interaction_at_to, "last_interaction_at_to")
        la_from = _parse_dt(last_activity_at_from, "last_activity_at_from")
        la_to = _parse_dt(last_activity_at_to, "last_activity_at_to")
        c_from = _parse_dt(created_at_from, "created_at_from")
        c_to = _parse_dt(created_at_to, "created_at_to")
        u_from = _parse_dt(updated_at_from, "updated_at_from")
        u_to = _parse_dt(updated_at_to, "updated_at_to")

        if li_from and li_to and li_from > li_to:
            out = _err("VALIDATION_ERROR", "last_interaction_at_from must be <= last_interaction_at_to")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out
        if la_from and la_to and la_from > la_to:
            out = _err("VALIDATION_ERROR", "last_activity_at_from must be <= last_activity_at_to")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out
        if c_from and c_to and c_from > c_to:
            out = _err("VALIDATION_ERROR", "created_at_from must be <= created_at_to")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out
        if u_from and u_to and u_from > u_to:
            out = _err("VALIDATION_ERROR", "updated_at_from must be <= updated_at_to")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out

        cursor_obj = _decode_cursor(cursor) if cursor is not None else None
        if cursor_obj is not None and cursor_obj.get("workspace_id") != workspace_id:
            out = _err("VALIDATION_ERROR", "cursor does not belong to the specified workspace_id")
            _log("list-records", workspace_id, 400, out["error"]["code"])
            return out

        rl = _check_rate_limit(workspace_id)
        if rl:
            _log("list-records", workspace_id, 429, rl["error"]["code"])
            return rl

        # validate workspace exists and is usable
        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            out = _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
            _log("list-records", workspace_id, 404, out["error"]["code"])
            return out
        if ws.get("status") != "active":
            out = _err("UNAUTHORIZED", "Workspace is not active", workspace_id=workspace_id, status=ws.get("status"))
            _log("list-records", workspace_id, 401, out["error"]["code"])
            return out

        rows = _load("records.json")
        if not isinstance(rows, list):
            rows = []

        def _match_exact(row, key, val):
            if val is None:
                return True
            if not isinstance(val, str):
                return False
            return row.get(key) == val

        filtered = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id:
                continue
            if record_type is not None and r.get("record_type") != record_type:
                continue
            if status is not None and r.get("status") != status:
                continue
            if not _match_exact(r, "attio_object", attio_object):
                continue
            if not _match_exact(r, "attio_record_id", attio_record_id):
                continue
            if not _match_exact(r, "display_name", display_name):
                continue
            if not _match_exact(r, "domain", domain):
                continue
            if not _match_exact(r, "email", email):
                continue
            if not _match_exact(r, "phone", phone):
                continue

            # dt windows
            r_li = _dt_from_row(r.get("last_interaction_at"))
            r_la = _dt_from_row(r.get("last_activity_at"))
            r_c = _dt_from_row(r.get("created_at"))
            r_u = _dt_from_row(r.get("updated_at"))

            if li_from and (r_li is None or r_li < li_from):
                continue
            if li_to and (r_li is None or r_li > li_to):
                continue
            if la_from and (r_la is None or r_la < la_from):
                continue
            if la_to and (r_la is None or r_la > la_to):
                continue
            if c_from and (r_c is None or r_c < c_from):
                continue
            if c_to and (r_c is None or r_c > c_to):
                continue
            if u_from and (r_u is None or r_u < u_from):
                continue
            if u_to and (r_u is None or r_u > u_to):
                continue

            filtered.append(r)

        sb = sort_by or "updated_at"
        so = sort_order or "desc"

        def _sort_key(row):
            v = row.get(sb)
            if sb in ("created_at", "updated_at", "last_interaction_at", "last_activity_at"):
                dt = _dt_from_row(v)
                return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            if sb == "display_name":
                return (v or "").lower()
            return v

        reverse = (so == "desc")
        filtered.sort(key=_sort_key, reverse=reverse)

        start = 0
        if cursor_obj is not None:
            if not isinstance(cursor_obj.get("offset"), int) or cursor_obj["offset"] < 0:
                out = _err("VALIDATION_ERROR", "cursor is invalid")
                _log("list-records", workspace_id, 400, out["error"]["code"])
                return out
            start = cursor_obj["offset"]

        total = len(filtered)
        page = filtered[start:start + limit]
        next_offset = start + len(page)
        has_more = next_offset < total
        next_cursor = _encode_cursor({"v": 1, "workspace_id": workspace_id, "offset": next_offset, "sort_by": sb, "sort_order": so}) if has_more else None

        resp = {
            "data": page,
            "meta": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "sort_by": sb,
                "sort_order": so,
            }
        }
        _log("list-records", workspace_id, 200, None)
        return resp

    except ValueError as ve:
        out = _err("VALIDATION_ERROR", str(ve))
        _log("list-records", workspace_id if isinstance(workspace_id, str) else None, 400, out["error"]["code"])
        return out
    except Exception as e:
        out = _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))
        _log("list-records", workspace_id if isinstance(workspace_id, str) else None, 500, out["error"]["code"])
        return out

def batch_create_records(workspace_id, records, **_extra):
    import json, os, datetime, time, re, secrets
    from urllib.parse import urlparse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "batch-create-records"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _get_log_file():
        for fn in ("request_logs.json", "usage.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(status_s, detail=None):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_%d_%d" % (int(time.time() * 1000), len(logs) + 1),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail,
        })
        _save(fn, logs)

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "workspace_id is invalid", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(records, list) or len(records) < 1 or len(records) > 500:
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "records must be an array with 1..500 items", "field": "records"})
        return _err("VALIDATION_ERROR", "records must be an array with 1..500 items", field="records")

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws_row is None:
        _log("error", detail={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")

    store = _load("records.json")
    if isinstance(store, dict) and "rows" in store:
        store = store.get("rows")
    if not isinstance(store, list):
        store = []

    existing_trip = {(r.get("workspace_id"), r.get("attio_object"), r.get("attio_record_id")) for r in store if isinstance(r, dict)}

    def _parse_dt(v, field):
        if v is None:
            return None
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{field} must be RFC3339 string", field=field)
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be RFC3339 date-time", field=field)

    def _normalize_domain(d):
        if d is None:
            return None
        if not isinstance(d, str):
            return _err("VALIDATION_ERROR", "domain must be a string", field="domain")
        s = d.strip().lower()
        if not s:
            return None
        host = None
        if "://" in s:
            p = urlparse(s)
            host = p.hostname
        if not host:
            host = s.split("/")[0].split("?")[0].split("#")[0]
            host = host.split("@")[-1]
            host = host.split(":")[0]
        host = (host or "").strip().lower()
        if host.startswith("www."):
            host = host[4:]
        if not host or any(c.isspace() for c in host) or "/" in host:
            return _err("VALIDATION_ERROR", "domain must be a normalized host (no scheme/path)", field="domain")
        return host

    def _normalize_email(e):
        if e is None:
            return None
        if not isinstance(e, str):
            return _err("VALIDATION_ERROR", "email must be a string", field="email")
        s = e.strip().lower()
        if not s:
            return None
        if "@" not in s:
            return _err("VALIDATION_ERROR", "email must contain '@'", field="email")
        return s

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        v = ms
        ts_chars = []
        for _ in range(10):
            v, r = divmod(v, 32)
            ts_chars.append(alphabet[r])
        ts = "".join(reversed(ts_chars))
        rand = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}_{ts}{rand}"

    now = _now_iso()
    results = []
    created = []

    for idx, it in enumerate(records):
        if not isinstance(it, dict):
            results.append({"index": idx, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "item must be an object"}})
            continue

        rt = it.get("record_type")
        dn = it.get("display_name")
        if rt not in ("company", "person", "custom"):
            results.append({"index": idx, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "record_type is invalid", "field": "record_type"}})
            continue
        if not isinstance(dn, str) or not dn.strip():
            results.append({"index": idx, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "display_name is required", "field": "display_name"}})
            continue
        attio_object = it.get("attio_object")
        if rt == "custom":
            if not isinstance(attio_object, str) or not attio_object.strip():
                results.append({"index": idx, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "attio_object is required for custom records", "field": "attio_object"}})
                continue
        if not isinstance(attio_object, str) or not attio_object.strip():
            attio_object = "companies" if rt == "company" else ("people" if rt == "person" else attio_object)

        st = it.get("status") or "active"
        if st not in ("active", "archived", "deleted"):
            results.append({"index": idx, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "status is invalid", "field": "status"}})
            continue

        dom = None
        em = None
        if rt == "company":
            dom = _normalize_domain(it.get("domain"))
            if isinstance(dom, dict) and "error" in dom:
                results.append({"index": idx, "ok": False, "error": dom["error"]})
                continue
        if rt == "person":
            em = _normalize_email(it.get("email"))
            if isinstance(em, dict) and "error" in em:
                results.append({"index": idx, "ok": False, "error": em["error"]})
                continue

        for fld in ("social", "contact", "business", "attributes", "raw_json"):
            if it.get(fld) is not None and not isinstance(it.get(fld), dict):
                results.append({"index": idx, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": f"{fld} must be an object", "field": fld}})
                break
        else:
            # parse datetimes
            parsed_times = {}
            for fld in ("last_interaction_at", "last_activity_at", "attio_created_at", "attio_updated_at"):
                pv = _parse_dt(it.get(fld), fld)
                if isinstance(pv, dict) and "error" in pv:
                    results.append({"index": idx, "ok": False, "error": pv["error"]})
                    parsed_times = None
                    break
                parsed_times[fld] = pv
            if parsed_times is None:
                continue

            rid = _gen_id("att_rec")
            while any(isinstance(r, dict) and r.get("id") == rid for r in store) or any(r.get("id") == rid for r in created):
                rid = _gen_id("att_rec")

            attio_record_id = it.get("attio_record_id")
            if not isinstance(attio_record_id, str) or not attio_record_id.strip():
                attio_record_id = _gen_id("attio")
            attio_record_id = attio_record_id.strip()

            while (workspace_id, attio_object, attio_record_id) in existing_trip:
                attio_record_id = _gen_id("attio")

            row = {
                "id": rid,
                "workspace_id": workspace_id,
                "record_type": rt,
                "attio_object": attio_object,
                "attio_record_id": attio_record_id,
                "status": st,
                "display_name": dn.strip(),
                "domain": dom if rt == "company" else None,
                "email": em if rt == "person" else None,
                "phone": it.get("phone") if isinstance(it.get("phone"), str) else None,
                "social": it.get("social") if isinstance(it.get("social"), dict) else None,
                "contact": it.get("contact") if isinstance(it.get("contact"), dict) else None,
                "business": it.get("business") if isinstance(it.get("business"), dict) else None,
                "attributes": it.get("attributes") if isinstance(it.get("attributes"), dict) else {},
                "raw_json": it.get("raw_json") if isinstance(it.get("raw_json"), dict) else {},
                "last_interaction_at": parsed_times.get("last_interaction_at"),
                "last_activity_at": parsed_times.get("last_activity_at"),
                "attio_created_at": parsed_times.get("attio_created_at"),
                "attio_updated_at": parsed_times.get("attio_updated_at"),
                "created_at": now,
                "updated_at": now,
            }
            created.append(row)
            existing_trip.add((workspace_id, attio_object, attio_record_id))
            results.append({"index": idx, "ok": True, "record": row})

    if created:
        store.extend(created)
        _save("records.json", store)
    _log("ok", detail={"created": len(created), "failed": len(results) - len(created)})
    return {"results": results, "meta": {"created": len(created), "failed": len(results) - len(created)}}

def batch_update_records(workspace_id, records, **_extra):
    import json, os, datetime, re, time, hashlib, random
    from urllib.parse import urlparse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "batch-update-records"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _get_log_file():
        for fn in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    def _log(status_s, detail=None):
        fn = _get_log_file()
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(time.time()) + "|" + str(random.getrandbits(64))).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "detail": detail,
        })
        _save(fn, logs)

    ws_re = re.compile(r"^att_ws_[0-9A-HJKMNP-TV-Z]{26}$")
    rec_re = re.compile(r"^att_rec_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(workspace_id, str) or not ws_re.fullmatch(workspace_id):
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "workspace_id is invalid", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is invalid", field="workspace_id")
    if not isinstance(records, list) or len(records) < 1 or len(records) > 500:
        _log("error", detail={"code": "VALIDATION_ERROR", "message": "records must be an array with 1..500 items", "field": "records"})
        return _err("VALIDATION_ERROR", "records must be an array with 1..500 items", field="records")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log("error", detail={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log("error", detail={"code": "UNAUTHORIZED", "message": "Workspace is not active", "status": ws.get("status")})
        return _err("UNAUTHORIZED", "Workspace is not active", status=ws.get("status"))

    store_recs = _load("records.json")
    if not isinstance(store_recs, list):
        store_recs = []
    id_to_index = {r.get("id"): i for i, r in enumerate(store_recs) if isinstance(r, dict) and isinstance(r.get("id"), str)}

    def _transition_ok(cur, to):
        transitions = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
        return cur == to or (cur in transitions and to in transitions[cur])

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        try:
            s = v[:-1] + "+00:00" if v.endswith("Z") else v
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        except Exception:
            return None

    def _normalize_domain(d):
        if d is None:
            return None
        if not isinstance(d, str):
            return _err("VALIDATION_ERROR", "domain must be a string", field="domain")
        s = d.strip().lower()
        if not s:
            return None
        host = None
        if "://" in s:
            p = urlparse(s)
            host = p.hostname
        if not host:
            host = s.split("/")[0].split("?")[0].split("#")[0]
            host = host.split("@")[-1]
            host = host.split(":")[0]
        host = (host or "").strip().lower()
        if host.startswith("www."):
            host = host[4:]
        if not host or any(c.isspace() for c in host) or "/" in host:
            return _err("VALIDATION_ERROR", "domain must be a normalized host (no scheme/path)", field="domain")
        return host

    results = []
    mutated = False
    now = _now_iso()

    for i, it in enumerate(records):
        if not isinstance(it, dict):
            results.append({"id": None, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": f"records[{i}] must be an object", "field": f"records[{i}]"}})
            continue
        rid = it.get("id")
        if not isinstance(rid, str) or not rec_re.fullmatch(rid):
            results.append({"id": rid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "id is invalid", "field": "id"}})
            continue
        idx = id_to_index.get(rid)
        if idx is None:
            results.append({"id": rid, "ok": False, "error": {"code": "NOT_FOUND", "message": "Record not found"}})
            continue
        rec = store_recs[idx]
        if rec.get("workspace_id") != workspace_id:
            results.append({"id": rid, "ok": False, "error": {"code": "CONFLICT", "message": "Cross-workspace record update is not allowed"}})
            continue

        # Validate and apply fields
        if "status" in it and it["status"] is not None:
            st = it["status"]
            if st not in ("active", "archived", "deleted"):
                results.append({"id": rid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "status is invalid", "field": "status"}})
                continue
            if not _transition_ok(rec.get("status"), st):
                results.append({"id": rid, "ok": False, "error": {"code": "INVALID_TRANSITION", "message": "illegal status transition", "from_status": rec.get("status"), "to_status": st}})
                continue
            rec["status"] = st

        for k in ("attio_record_id", "display_name", "email", "phone", "attio_object"):
            if k in it:
                v = it.get(k)
                if v is not None and not isinstance(v, str):
                    results.append({"id": rid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": f"{k} must be a string", "field": k}})
                    rec = None
                    break
                if k == "email" and v is not None:
                    v = v.strip().lower()
                    if v and "@" not in v:
                        results.append({"id": rid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "email must contain '@'", "field": "email"}})
                        rec = None
                        break
                    v = v or None
                rec[k] = v
        if rec is None:
            continue

        if "domain" in it:
            nd = _normalize_domain(it.get("domain"))
            if isinstance(nd, dict) and "error" in nd:
                results.append({"id": rid, "ok": False, "error": nd["error"]})
                continue
            rec["domain"] = nd

        for k in ("social", "contact", "business", "attributes", "raw_json"):
            if k in it:
                v = it.get(k)
                if v is not None and not isinstance(v, dict):
                    results.append({"id": rid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": f"{k} must be an object", "field": k}})
                    rec = None
                    break
                if v is None:
                    # keep required objects for attributes/raw_json; treat None as no-op
                    continue
                rec[k] = v
        if rec is None:
            continue

        for k in ("last_interaction_at", "last_activity_at", "attio_updated_at"):
            if k in it:
                v = it.get(k)
                if v is None:
                    rec[k] = None
                else:
                    parsed = _parse_dt(v)
                    if parsed is None:
                        results.append({"id": rid, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": f"{k} must be ISO date-time", "field": k}})
                        rec = None
                        break
                    rec[k] = parsed
        if rec is None:
            continue

        rec["updated_at"] = now
        store_recs[idx] = rec
        mutated = True
        results.append({"id": rid, "ok": True, "record": rec})

    if mutated:
        _save("records.json", store_recs)
    _log("ok", detail={"updated_count": sum(1 for r in results if r.get("ok")), "failed_count": sum(1 for r in results if not r.get("ok"))})

    return {
        "results": results,
        "meta": {
            "workspace_id": workspace_id,
            "updated_count": sum(1 for r in results if r.get("ok")),
            "failed_count": sum(1 for r in results if not r.get("ok")),
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def whoami(authorization, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "whoami"
    used_cred = None

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, outcome, wsid=None, cred=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now_iso()}|{len(logs)}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "workspace_id": wsid,
            "credential_id": cred,
            "status": status_code,
            "outcome": outcome,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    if not isinstance(authorization, str) or not authorization.strip():
        _log(400, "validation_error")
        return _err("VALIDATION_ERROR", "authorization is required")

    # Enforce rate/quota if configured
    cfg = _load("service_config.json")
    rate = quota = None
    if isinstance(cfg, dict):
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now = datetime.datetime.now(datetime.timezone.utc)

    def _dt(v):
        if isinstance(v, str):
            try:
                if v.endswith("Z"): v = v[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(v)
                if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    if isinstance(rate, int) and rate > 0:
        one_min = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs[::-1]:
            ts = _dt(r.get("created_at"))
            if not ts:
                continue
            if ts < one_min:
                break
            c += 1
        if c >= rate:
            _log(429, "rate_limited")
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate, window_seconds=60)

    if isinstance(quota, int) and quota > 0:
        day = now - datetime.timedelta(days=1)
        c = 0
        for r in logs[::-1]:
            ts = _dt(r.get("created_at"))
            if not ts:
                continue
            if ts < day:
                break
            c += 1
        if c >= quota:
            _log(429, "quota_exceeded")
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=quota, window_seconds=86400)

    # Authenticate: match against credentials store if present; otherwise deny (whoami requires explicit auth)
    token = authorization.strip()
    if token.lower().startswith("bearer "):
        token = token[7:].strip()

    creds = _load("credentials.json")
    if not isinstance(creds, list):
        creds = []
    # Accept either id match or client-visible value match
    cred = None
    for c in creds:
        if not isinstance(c, dict):
            continue
        if c.get("id") == token or c.get("token") == token or c.get("api_key") == token or c.get("value") == token:
            cred = c
            break
    if not cred:
        # Try service_config single key
        if isinstance(cfg, dict) and (cfg.get("api_key") == token or cfg.get("token") == token):
            cred = {"id": "cfg_credential", "scopes": cfg.get("scopes"), "workspace_id": cfg.get("workspace_id")}
    if not cred:
        _log(401, "unauthorized")
        return _err("UNAUTHORIZED", "Invalid or missing credentials")

    used_cred = cred.get("id") if isinstance(cred, dict) else None

    # Resolve workspace context: must find a workspace that can serve calls.
    wsid = None
    if isinstance(cred, dict):
        wsid = cred.get("workspace_id")
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    ws = None
    if isinstance(wsid, str):
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == wsid), None)
    if not ws:
        # fallback: choose an active workspace if any
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"), None)

    if not ws:
        _log(401, "unauthorized", wsid=None, cred=used_cred)
        return _err("UNAUTHORIZED", "No authorized workspace available for these credentials")

    wsid = ws.get("id")

    # Compute consumption
    one_min = now - datetime.timedelta(minutes=1)
    day = now - datetime.timedelta(days=1)
    minute_count = 0
    day_count = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        ts = _dt(r.get("created_at"))
        if not ts:
            continue
        if ts >= day:
            day_count += 1
        if ts >= one_min:
            minute_count += 1

    scopes = []
    if isinstance(cred, dict):
        sc = cred.get("scopes")
        if isinstance(sc, list):
            scopes = sc
        elif isinstance(sc, str):
            scopes = [sc]

    _log(200, "ok", wsid=wsid, cred=used_cred)
    return {
        "data": {
            "credential": {
                "id": used_cred,
                "type": cred.get("type") if isinstance(cred, dict) else None,
                "scopes": scopes
            },
            "workspace": {
                "id": wsid,
                "attio_workspace_id": ws.get("attio_workspace_id"),
                "name": ws.get("name"),
                "status": ws.get("status"),
                "last_schema_sync_at": ws.get("last_schema_sync_at")
            },
            "limits": {
                "rate_limit_per_minute": rate,
                "quota_per_day": quota
            },
            "usage": {
                "requests_last_minute": minute_count,
                "requests_last_day": day_count
            }
        }
    }

def create_list(workspace_id, name, list_type, applies_to, field_config=None, status=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Validation helpers
    def _is_obj(v): return isinstance(v, dict)
    def _is_str(v): return isinstance(v, str)
    def _ulid_like(prefix, v):
        if not _is_str(v): return False
        return re.match(r"^%s_[0-9A-HJKMNP-TV-Z]{26}$" % re.escape(prefix), v) is not None

    # ---- Load stores
    workspaces = _load("workspaces.json")
    lists = _load("lists.json")
    reqlog = _load("request_log.json")
    usage = _load("usage.json")

    # ---- Resolve workspace & authorization (ambient)
    if not _ulid_like("att_ws", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")

    ws = None
    for w in workspaces:
        if w.get("id") == workspace_id:
            ws = w
            break

    # If explicit workspace_id isn't found, we must not refuse a well-formed request merely due to missing auth param.
    # Search for any active workspace that can serve this call.
    if ws is None:
        for w in workspaces:
            if w.get("status") == "active":
                ws = w
                break
        if ws is None:
            # log unauthorized
            reqlog.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "create-list",
                "workspace_id": None,
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", reqlog)
            return _err("UNAUTHORIZED", "No authorized workspace available for this operation.")
    else:
        if ws.get("status") != "active":
            # treat as unauthorized for operational access
            reqlog.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "create-list",
                "workspace_id": ws.get("id"),
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", reqlog)
            return _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=ws.get("status"))

    # ---- Rate limit (simple: 120 requests/min/workspace based on request_log)
    # Enforce before executing mutation.
    window_s = 60
    limit = 120
    ws_id = ws.get("id")
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
    cnt = 0
    for r in reqlog:
        if r.get("workspace_id") != ws_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            rt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if rt >= cutoff:
            cnt += 1
    if cnt >= limit:
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "create-list",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "RATE_LIMIT",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", retry_after_seconds=5)

    # ---- Input validation
    if not _is_str(name) or len(name.strip()) < 1:
        return _err("VALIDATION_ERROR", "Invalid name.", field="name")
    name = name.strip()

    if list_type not in ("segment", "pipeline"):
        return _err("VALIDATION_ERROR", "Invalid list_type.", field="list_type")
    if applies_to not in ("company", "person", "record"):
        return _err("VALIDATION_ERROR", "Invalid applies_to.", field="applies_to")

    # Map tool "record" to schema "custom"
    applies_to_db = "custom" if applies_to == "record" else applies_to

    if status is None:
        status = "active"
    if status not in ("active", "archived"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if field_config is None:
        field_config = {}
    if not _is_obj(field_config):
        return _err("VALIDATION_ERROR", "field_config must be a JSON object.", field="field_config")

    # Business rule: refuse invalid list_type/applies_to combinations.
    # For this integration: pipelines cannot be mixed/custom; segments can target anything.
    if list_type == "pipeline" and applies_to_db not in ("company", "person"):
        return _err("VALIDATION_ERROR", "Pipelines must apply to 'company' or 'person'.", field="applies_to")

    # Pipeline field_config validation: must include stages with id+name and unique ids.
    if list_type == "pipeline":
        stages = field_config.get("stages")
        if not isinstance(stages, list) or len(stages) < 1:
            return _err("VALIDATION_ERROR", "Pipeline field_config must include non-empty 'stages' array.", field="field_config.stages")
        seen = set()
        for i, st in enumerate(stages):
            if not isinstance(st, dict):
                return _err("VALIDATION_ERROR", "Each stage must be an object.", field=f"field_config.stages[{i}]")
            sid = st.get("id")
            sname = st.get("name")
            if not _is_str(sid) or not sid.strip():
                return _err("VALIDATION_ERROR", "Stage id is required.", field=f"field_config.stages[{i}].id")
            if not _is_str(sname) or not sname.strip():
                return _err("VALIDATION_ERROR", "Stage name is required.", field=f"field_config.stages[{i}].name")
            if sid in seen:
                return _err("VALIDATION_ERROR", "Duplicate stage id in pipeline configuration.", field=f"field_config.stages[{i}].id", duplicate_id=sid)
            seen.add(sid)

    # Uniqueness constraints: unique(workspace_id, name)
    for l in lists:
        if l.get("workspace_id") == ws_id and l.get("name") == name and l.get("status") != "deleted":
            reqlog.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "create-list",
                "workspace_id": ws_id,
                "status": "error",
                "error_code": "CONFLICT",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", reqlog)
            return _err("CONFLICT", "A list with this name already exists in the workspace.", conflict_field="name")

    # Generate ids
    new_id = "lst_" + uuid.uuid4().hex
    # We don't have upstream Attio list id; store a locally-generated opaque id.
    attio_list_id = "attio_lst_" + uuid.uuid4().hex

    row = {
        "id": new_id,
        "workspace_id": ws_id,
        "attio_list_id": attio_list_id,
        "name": name,
        "list_type": list_type,
        "applies_to": applies_to_db if applies_to_db in ("company", "person", "custom", "mixed") else "other",
        "status": status,
        "field_config": field_config,
        "created_at": now,
        "updated_at": now
    }
    lists.append(row)
    _save("lists.json", lists)

    # Update usage counters
    if isinstance(usage, dict):
        usage.setdefault("calls_total", 0)
        usage["calls_total"] += 1
        usage.setdefault("calls_by_endpoint", {})
        usage["calls_by_endpoint"]["create-list"] = usage["calls_by_endpoint"].get("create-list", 0) + 1
        usage.setdefault("calls_by_workspace", {})
        usage["calls_by_workspace"][ws_id] = usage["calls_by_workspace"].get(ws_id, 0) + 1
        _save("usage.json", usage)

    reqlog.append({
        "id": "req_" + uuid.uuid4().hex,
        "endpoint": "create-list",
        "workspace_id": ws_id,
        "status": "ok",
        "timestamp": now,
        "latency_ms": int((time.time() - t0) * 1000)
    })
    _save("request_log.json", reqlog)

    return {"list": row}

def update_list(workspace_id, list_id, name=None, field_config=None, status=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_obj(v): return isinstance(v, dict)
    def _is_str(v): return isinstance(v, str)
    def _ulid_like(prefix, v):
        if not _is_str(v): return False
        return re.match(r"^%s_[0-9A-HJKMNP-TV-Z]{26}$" % re.escape(prefix), v) is not None

    workspaces = _load("workspaces.json")
    lists = _load("lists.json")
    reqlog = _load("request_log.json")

    if not _ulid_like("att_ws", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")
    if not _is_str(list_id) or not list_id:
        return _err("VALIDATION_ERROR", "Invalid list_id.", field="list_id")

    ws = None
    for w in workspaces:
        if w.get("id") == workspace_id:
            ws = w
            break
    if ws is None:
        # try any active workspace (ambient auth)
        for w in workspaces:
            if w.get("status") == "active":
                ws = w
                break
        if ws is None:
            reqlog.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "update-list",
                "workspace_id": None,
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", reqlog)
            return _err("UNAUTHORIZED", "No authorized workspace available for this operation.")
    else:
        if ws.get("status") != "active":
            reqlog.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "update-list",
                "workspace_id": ws.get("id"),
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", reqlog)
            return _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=ws.get("status"))

    ws_id = ws.get("id")

    # Rate limit (120/min)
    window_s = 60
    limit = 120
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
    cnt = 0
    for r in reqlog:
        if r.get("workspace_id") != ws_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            rt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if rt >= cutoff:
            cnt += 1
    if cnt >= limit:
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-list",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "RATE_LIMIT",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", retry_after_seconds=5)

    # Find list and enforce workspace scope
    idx = None
    cur = None
    for i, l in enumerate(lists):
        if l.get("id") == list_id:
            idx = i
            cur = l
            break
    if cur is None:
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-list",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "NOT_FOUND",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("NOT_FOUND", "List not found.", list_id=list_id)

    if cur.get("workspace_id") != ws_id:
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-list",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("UNAUTHORIZED", "Cross-workspace access denied.")

    # Validate fields
    if name is not None:
        if not _is_str(name) or len(name.strip()) < 1:
            return _err("VALIDATION_ERROR", "Invalid name.", field="name")
        name = name.strip()

    if field_config is not None and not _is_obj(field_config):
        return _err("VALIDATION_ERROR", "field_config must be a JSON object.", field="field_config")

    if status is not None and status not in ("active", "archived", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    # Refuse attempts to transition a deleted list
    if cur.get("status") == "deleted" and status is not None and status != "deleted":
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-list",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "INVALID_TRANSITION",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("INVALID_TRANSITION", "Cannot transition a deleted list.", from_status="deleted", to_status=status)

    # Lifecycle transitions (schema): active<->archived, both -> deleted, deleted -> none
    if status is not None and status != cur.get("status"):
        allowed = {
            "active": set(["archived", "deleted"]),
            "archived": set(["active", "deleted"]),
            "deleted": set([])
        }
        if status not in allowed.get(cur.get("status"), set()):
            reqlog.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "update-list",
                "workspace_id": ws_id,
                "status": "error",
                "error_code": "INVALID_TRANSITION",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", reqlog)
            return _err("INVALID_TRANSITION", "Illegal list status transition.", from_status=cur.get("status"), to_status=status)

    # Unique(workspace_id, name) (excluding deleted)
    if name is not None and name != cur.get("name"):
        for l in lists:
            if l.get("id") == cur.get("id"):
                continue
            if l.get("workspace_id") == ws_id and l.get("name") == name and l.get("status") != "deleted":
                reqlog.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": "update-list",
                    "workspace_id": ws_id,
                    "status": "error",
                    "error_code": "CONFLICT",
                    "timestamp": now,
                    "latency_ms": int((time.time() - t0) * 1000)
                })
                _save("request_log.json", reqlog)
                return _err("CONFLICT", "A list with this name already exists in the workspace.", conflict_field="name")

    # Validate pipeline config updates
    new_field_config = cur.get("field_config")
    if field_config is not None:
        new_field_config = field_config
        if cur.get("list_type") == "pipeline":
            stages = new_field_config.get("stages")
            if not isinstance(stages, list) or len(stages) < 1:
                return _err("VALIDATION_ERROR", "Pipeline field_config must include non-empty 'stages' array.", field="field_config.stages")
            seen = set()
            for i, st in enumerate(stages):
                if not isinstance(st, dict):
                    return _err("VALIDATION_ERROR", "Each stage must be an object.", field=f"field_config.stages[{i}]")
                sid = st.get("id")
                sname = st.get("name")
                if not _is_str(sid) or not sid.strip():
                    return _err("VALIDATION_ERROR", "Stage id is required.", field=f"field_config.stages[{i}].id")
                if not _is_str(sname) or not sname.strip():
                    return _err("VALIDATION_ERROR", "Stage name is required.", field=f"field_config.stages[{i}].name")
                if sid in seen:
                    return _err("VALIDATION_ERROR", "Duplicate stage id in pipeline configuration.", field=f"field_config.stages[{i}].id", duplicate_id=sid)
                seen.add(sid)

    # Apply mutation (ensure effect)
    changed = False
    if name is not None and name != cur.get("name"):
        cur["name"] = name
        changed = True
    if field_config is not None:
        cur["field_config"] = new_field_config
        changed = True
    if status is not None and status != cur.get("status"):
        cur["status"] = status
        changed = True

    if not changed:
        # No-op update should not claim success without effect
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-list",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "CONFLICT",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("CONFLICT", "No changes to apply.")

    cur["updated_at"] = now
    lists[idx] = cur
    _save("lists.json", lists)

    reqlog.append({
        "id": "req_" + uuid.uuid4().hex,
        "endpoint": "update-list",
        "workspace_id": ws_id,
        "status": "ok",
        "timestamp": now,
        "latency_ms": int((time.time() - t0) * 1000)
    })
    _save("request_log.json", reqlog)

    return {"list": cur}

def update_record_status(workspace_id, record_id, status, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0081000" if __import__("os").path.isdir("./environment_mix/0081000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_str(v): return isinstance(v, str)
    def _ulid_like(prefix, v):
        if not _is_str(v): return False
        return re.match(r"^%s_[0-9A-HJKMNP-TV-Z]{26}$" % re.escape(prefix), v) is not None

    workspaces = _load("workspaces.json")
    records = _load("records.json")
    list_entries = _load("list_entries.json")
    reqlog = _load("request_log.json")

    if not _ulid_like("att_ws", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")
    if not _is_str(record_id) or not record_id:
        return _err("VALIDATION_ERROR", "Invalid record_id.", field="record_id")
    if status not in ("active", "archived", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    ws = None
    for w in workspaces:
        if w.get("id") == workspace_id:
            ws = w
            break
    if ws is None:
        for w in workspaces:
            if w.get("status") == "active":
                ws = w
                break
        if ws is None:
            reqlog.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "update-record-status",
                "workspace_id": None,
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", reqlog)
            return _err("UNAUTHORIZED", "No authorized workspace available for this operation.")
    else:
        if ws.get("status") != "active":
            reqlog.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "update-record-status",
                "workspace_id": ws.get("id"),
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_log.json", reqlog)
            return _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=ws.get("status"))

    ws_id = ws.get("id")

    # Rate limit (120/min)
    window_s = 60
    limit = 120
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
    cnt = 0
    for r in reqlog:
        if r.get("workspace_id") != ws_id:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            rt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if rt >= cutoff:
            cnt += 1
    if cnt >= limit:
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-record-status",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "RATE_LIMIT",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", retry_after_seconds=5)

    # Find record
    ridx = None
    rec = None
    for i, r in enumerate(records):
        if r.get("id") == record_id:
            ridx = i
            rec = r
            break
    if rec is None:
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-record-status",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "NOT_FOUND",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("NOT_FOUND", "Record not found.", record_id=record_id)

    if rec.get("workspace_id") != ws_id:
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-record-status",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("UNAUTHORIZED", "Cross-workspace access denied.")

    cur_status = rec.get("status")

    # Transitions per schema
    allowed = {
        "active": set(["archived", "deleted"]),
        "archived": set(["active", "deleted"]),
        "deleted": set([])
    }

    if status == cur_status:
        # Must not claim success without effect
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-record-status",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "CONFLICT",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("CONFLICT", "Record already in requested status.", status=status)

    if status not in allowed.get(cur_status, set()):
        reqlog.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-record-status",
            "workspace_id": ws_id,
            "status": "error",
            "error_code": "INVALID_TRANSITION",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_log.json", reqlog)
        return _err("INVALID_TRANSITION", "Illegal record status transition.", from_status=cur_status, to_status=status)

    # Apply transition
    rec["status"] = status
    rec["updated_at"] = now
    records[ridx] = rec
    _save("records.json", records)

    # When transitioning to deleted, associated active list entries are marked removed and removed_at set.
    removed_count = 0
    if status == "deleted":
        for i, e in enumerate(list_entries):
            if e.get("workspace_id") != ws_id:
                continue
            if e.get("record_id") != record_id:
                continue
            if e.get("status") == "active":
                e["status"] = "removed"
                e["removed_at"] = now
                e["updated_at"] = now
                list_entries[i] = e
                removed_count += 1
        if removed_count > 0:
            _save("list_entries.json", list_entries)
        else:
            # Still ok: record update had effect.
            pass

    reqlog.append({
        "id": "req_" + uuid.uuid4().hex,
        "endpoint": "update-record-status",
        "workspace_id": ws_id,
        "status": "ok",
        "timestamp": now,
        "latency_ms": int((time.time() - t0) * 1000),
        "meta": {"list_entries_removed": removed_count} if status == "deleted" else None
    })
    _save("request_log.json", reqlog)

    return {"record": rec, "list_entries_removed": removed_count}
